import React from "react";
import { Routes, Route, Navigate } from "react-router-dom";
import { AuthProvider } from "./core/auth/AuthContext";
import { NotificationProvider } from "./core/utils/notifications";
import { AppLayout } from "./components/AppLayout";
import { RequireAuth } from "./core/auth/RequireAuth";
import { GlobalSync } from "./core/sync/GlobalSync";
import { useAppIntegration } from "./useAppIntegration";
import { LoginScreen } from "./screens/login/LoginScreen";
import { LoginTitleBar } from "./components/shell";

const PlanScreen        = React.lazy(() => import("./screens/plan/PlanScreen").then(m => ({ default: m.PlanScreen })));
const DoScreen          = React.lazy(() => import("./screens/do/DoScreen").then(m => ({ default: m.DoScreen })));
const SettingsScreen    = React.lazy(() => import("./screens/settings/SettingsScreen").then(m => ({ default: m.SettingsScreen })));
const WrapScreen        = React.lazy(() => import("./screens/wrap/WrapScreen").then(m => ({ default: m.WrapScreen })));
const GraphScreen       = React.lazy(() => import("./screens/graph/GraphScreen").then(m => ({ default: m.GraphScreen })));
const StatsScreen       = React.lazy(() => import("./screens/stats/StatsScreen").then(m => ({ default: m.StatsScreen })));
const RecapScreen       = React.lazy(() => import("./screens/recap/RecapScreen").then(m => ({ default: m.RecapScreen })));
const MiniTrackerScreen = React.lazy(() => import("./screens/minitracker/MiniTrackerScreen").then(m => ({ default: m.MiniTrackerScreen })));
const DevScreen         = React.lazy(() => import("./screens/dev/DevScreen").then(m => ({ default: m.DevScreen })));
const LauncherScreen    = React.lazy(() => import("./screens/launcher/LauncherScreen").then(m => ({ default: m.LauncherScreen })));
const DocsScreen        = React.lazy(() => import("./screens/docs/DocsScreen").then(m => ({ default: m.DocsScreen })));

function AppRouter() {
    useAppIntegration();

    return (
        <React.Suspense fallback={undefined}>
            <Routes>
                <Route element={<AppLayout />}>
                    <Route path="/plan" element={<PlanScreen />} />
                    <Route path="/do" element={<DoScreen />} />
                    <Route path="/settings" element={<SettingsScreen />} />
                    <Route path="/wrap" element={<WrapScreen />} />
                    <Route path="/graph" element={<GraphScreen />} />
                    <Route path="/stats" element={<StatsScreen />} />
                    <Route path="/recap" element={<RecapScreen />} />
                    <Route path="/dev" element={<DevScreen />} />
                    <Route path="/docs/*" element={<DocsScreen />} />
                </Route>
                <Route path="*" element={<Navigate to="/plan" replace />} />
            </Routes>
        </React.Suspense>
    );
}

export function App() {
    React.useEffect(() => {
        void import("cuelume").then(({ bind }) => bind());
    }, []);

    if (window.location.search.includes("minitracker=true")) {
        return (
            <GlobalSync>
                <MiniTrackerScreen />
            </GlobalSync>
        );
    }

    if (window.location.search.includes("launcher=true")) {
        return (
            <React.Suspense fallback={undefined}>
                <LauncherScreen />
            </React.Suspense>
        );
    }

    return (
        <NotificationProvider>
            <AuthProvider>
                <RequireAuth loginFallback={<LoginScreen />} titleBar={<LoginTitleBar />}>
                    <GlobalSync titleBar={<LoginTitleBar />}>
                        <AppRouter />
                    </GlobalSync>
                </RequireAuth>
            </AuthProvider>
        </NotificationProvider>
    );
}

import { useLocation, Outlet } from "react-router-dom";
import { TitleBar } from "./shell";

export function AppLayout() {
    const location = useLocation();
    const current = location.pathname.substring(1) || 'plan';

    let appClass = 'app';
    if (current === 'do') appClass += ' app-do';
    if (current === 'settings') appClass += ' app-settings';

    return (
        <div className={appClass}>
            <TitleBar current={current} />
            <Outlet />
        </div>
    );
}

export type RecurringMode = "instance" | "following" | "all";

interface RecurringActionModalProps {
    isOpen: boolean;
    actionType: "edit" | "delete";
    onConfirm: (mode: RecurringMode) => void;
    onCancel: () => void;
}

export function RecurringActionModal({ isOpen, actionType, onConfirm, onCancel }: RecurringActionModalProps) {
    if (!isOpen) return <></>;

    const actionText = actionType === "edit" ? "Edit" : "Delete";

    return (
        <div style={{
            position: "fixed",
            top: 0, left: 0, right: 0, bottom: 0,
            backgroundColor: "rgba(0, 0, 0, 0.5)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 99999
        }}>
            <div style={{
                background: "var(--bg-panel, #1e1e1e)",
                padding: "24px",
                borderRadius: "8px",
                width: "320px",
                boxShadow: "0 4px 12px rgba(0,0,0,0.3)",
                color: "var(--fg-primary, #fff)"
            }}>
                <h3 style={{ margin: "0 0 16px 0", fontSize: "16px", fontWeight: 600 }}>{actionText} recurring event</h3>
                
                <div style={{ display: "flex", flexDirection: "column", gap: "12px", marginBottom: "24px" }}>
                    <label style={{ display: "flex", alignItems: "center", gap: "8px", cursor: "pointer", fontSize: "14px" }}>
                        <input type="radio" name="recurring_mode" value="instance" defaultChecked id="mode_instance" />
                        This event
                    </label>
                    <label style={{ display: "flex", alignItems: "center", gap: "8px", cursor: "pointer", fontSize: "14px" }}>
                        <input type="radio" name="recurring_mode" value="following" id="mode_following" />
                        This and following events
                    </label>
                    <label style={{ display: "flex", alignItems: "center", gap: "8px", cursor: "pointer", fontSize: "14px" }}>
                        <input type="radio" name="recurring_mode" value="all" id="mode_all" />
                        All events
                    </label>
                </div>

                <div style={{ display: "flex", justifyContent: "flex-end", gap: "12px" }}>
                    <button 
                        onClick={onCancel}
                        style={{
                            background: "transparent",
                            border: "none",
                            color: "var(--fg-secondary, #aaa)",
                            cursor: "pointer",
                            padding: "6px 12px",
                            fontSize: "14px"
                        }}
                    >
                        Cancel
                    </button>
                    <button 
                        onClick={() => {
                            const selected = document.querySelector('input[name="recurring_mode"]:checked');
                            if (selected && selected instanceof HTMLInputElement) {
                                const mode = selected.value;
                                if (mode === "instance" || mode === "following" || mode === "all") {
                                    onConfirm(mode);
                                }
                            }
                        }}
                        style={{
                            background: "var(--accent, #3b82f6)",
                            border: "none",
                            color: "#fff",
                            cursor: "pointer",
                            padding: "6px 16px",
                            borderRadius: "4px",
                            fontWeight: 500,
                            fontSize: "14px"
                        }}
                    >
                        OK
                    </button>
                </div>
            </div>
        </div>
    );
}

