import { useMemo } from "react";
import { MINUTES_IN_HOUR, HOURS_PER_DAY } from "../../../core/utils/constants";
import { MS_IN_DAY, MS_IN_MINUTE, MINUTES_IN_DAY, toFloatingIso } from "../../../core/utils/date-utils";
import { PX_PER_MIN } from "../types";
import type { DragState } from "../types";
import { ymd, sameDay } from "../../../core/store/data";
import { layoutEvents } from "../layout";
import type { HydratedEvent } from "../../../core/domain/events";
import { isEventAllDay } from "../../../core/domain/events";
import { filterEvents, sortEvents } from "../../../core/domain/filters";
import type { AppFilter } from "../../../core/domain/models";

import { useEventCreation } from "../hooks/useEventCreation";
import { TimeGridBackground } from "./TimeGridBackground";
import { CurrentTimeLine } from "./CurrentTimeLine";
import { CreationPreview } from "./CreationPreview";
import { DropPreview } from "./DropPreview";
import { EventBlock } from "../EventBlock";

const LABEL_OFFSET_PX = 56;
const LABEL_OFFSET_COMPACT_PX = 8;

export interface DayColumnProps<T extends DragState = DragState> {
    date: Date;
    today: Date;
    events: HydratedEvent[];
    filter: AppFilter[];
    sort: string;
    dragState?: T;
    setDragState?: React.Dispatch<React.SetStateAction<T | undefined>>;
    onResizeEvent?: (id: string, startTime: string, endTime: string) => void;
    onMoveEvent?: (id: string, startTime: string, endTime: string) => void;
    onEventClick?: (ev: HydratedEvent) => void;
    onAddEvent?: (date: Date, start: number, end: number) => void;
    showTimeLabels?: boolean;
}

export function DayColumn<T extends DragState = DragState>({
    date,
    today,
    events,
    filter,
    sort,
    dragState,
    setDragState,
    onResizeEvent,
    onMoveEvent,
    onEventClick,
    onAddEvent,
    showTimeLabels = true,
}: DayColumnProps<T>) {
    const isToday = sameDay(date, today);
    const { containerRef, createPreview, onGridPointerDown } = useEventCreation(date, onAddEvent);

    const laid = useMemo(() => {
        const cellDate = ymd(date);
        const cellStart = new Date(`${cellDate}T00:00:00`).getTime();
        const cellEnd = cellStart + MS_IN_DAY;

        let dayEvents = events.filter((e: HydratedEvent) => {
            if (isEventAllDay(e)) return false;
            const eStart = new Date(e.startTime).getTime();
            const eEnd = new Date(e.endTime).getTime();
            return eStart < cellEnd && eEnd > cellStart;
        });

        dayEvents = filterEvents(dayEvents, filter);
        dayEvents = sortEvents(dayEvents, sort);
        
        const mapped = dayEvents.map(e => {
            const eStart = new Date(e.startTime).getTime();
            const eEnd = new Date(e.endTime).getTime();
            const startMins = Math.max(0, (eStart - cellStart) / MS_IN_MINUTE);
            const endMins = Math.min(MINUTES_IN_DAY, (eEnd - cellStart) / MS_IN_MINUTE);
            return { event: e, startMins, endMins };
        });

        return layoutEvents(mapped);
    }, [events, date, filter, sort]);

    const handleResize = (id: string, newStartMins: number, newEndMins: number) => {
        const cellDate = ymd(date);
        const cellStart = new Date(`${cellDate}T00:00:00`);
        const newStartDt = new Date(cellStart.getTime() + newStartMins * MS_IN_MINUTE);
        const newEndDt = new Date(cellStart.getTime() + newEndMins * MS_IN_MINUTE);
        
        if (onResizeEvent) onResizeEvent(id, toFloatingIso(newStartDt), toFloatingIso(newEndDt));
    };

    const handleMove = (id: string, newStartMins: number, newEndMins: number) => {
        const cellDate = ymd(date);
        const cellStart = new Date(`${cellDate}T00:00:00`);
        const newStartDt = new Date(cellStart.getTime() + newStartMins * MS_IN_MINUTE);
        const newEndDt = new Date(cellStart.getTime() + newEndMins * MS_IN_MINUTE);
        
        if (onMoveEvent) onMoveEvent(id, toFloatingIso(newStartDt), toFloatingIso(newEndDt));
    };

    const dropPreview = dragState?.target?.kind === "day-time" && dragState.target.date === ymd(date) ? dragState.target : undefined;

    return (
        <div
            className="day-grid"
            ref={containerRef}
            style={{
                position: 'relative',
                flex: 1,
                minWidth: '200px',
                height: `${HOURS_PER_DAY * MINUTES_IN_HOUR * PX_PER_MIN}px`,
                borderRight: '1px solid var(--border-soft)'
            }}
            data-drop-kind="day-time"
            data-drop-date={ymd(date)}
            onPointerDown={onGridPointerDown}
            onPointerEnter={() => {
                if (dragState?.event) {
                    setDragState?.({
                        ...dragState,
                        target: {
                            kind: "day-time",
                            date: ymd(date),
                            start: dragState.target?.start || 0,
                            end: dragState.target?.end || 0
                        }
                    });
                }
            }}
        >
            <div style={{ position: 'absolute', top: -32, left: 0, right: 0, textAlign: 'center', fontWeight: 'bold', fontSize: '0.9em', color: isToday ? 'var(--accent)' : 'var(--fg)', paddingBottom: '8px' }}>
                {Intl.DateTimeFormat('en-US', { weekday: 'short', month: 'short', day: 'numeric' }).format(date)}
            </div>
            
            <TimeGridBackground isToday={isToday} showLabels={showTimeLabels} />
            {isToday && <CurrentTimeLine showLabels={showTimeLabels} />}

            {laid.map(({ event, startMins, endMins, lane, lanes }) => (
                <EventBlock
                    key={event.id}
                    event={event}
                    startMins={startMins}
                    endMins={endMins}
                    lane={lane}
                    lanes={lanes}
                    onResize={handleResize}
                    onMove={handleMove}
                    {...(dragState !== undefined ? { dragState } : {})}
                    {...(setDragState !== undefined ? { setDragState } : {})}
                    {...(onEventClick !== undefined ? { onEventClick } : {})}
                    labelOffset={showTimeLabels ? LABEL_OFFSET_PX : LABEL_OFFSET_COMPACT_PX}
                />
            ))}

            {createPreview && <CreationPreview preview={createPreview} />}
