import { MS_PER_MINUTE, MINUTES_IN_HOUR } from "../../../core/utils/constants";
import { useState, useEffect } from "react";

export function useCurrentTime() {
    const [nowMin, setNowMin] = useState(() => {
        const d = new Date();
        return d.getHours() * MINUTES_IN_HOUR + d.getMinutes();
    });

    useEffect(() => {
        const interval = setInterval(() => {
            const d = new Date();
            setNowMin(d.getHours() * MINUTES_IN_HOUR + d.getMinutes());
        }, MS_PER_MINUTE);
        return () => clearInterval(interval);
    }, []);

    return nowMin;
}

import { useEffect, useRef } from "react";
import { PX_PER_MIN } from "../types";
import { useSettings } from "../../../core/store/hooks";
import { DEFAULT_SETTINGS } from "../../../core/store/settingsSchema";

export const MONTHS_IN_YEAR = 12;

export function useCurrentTimeScroll() {
    const scrollRef = useRef<HTMLDivElement>(null);
    const [settings] = useSettings();

    useEffect(() => {
        const tick = () => {
            if (scrollRef.current) {
                const startMin = settings.dayTimelineStartView ?? DEFAULT_SETTINGS.dayTimelineStartView;
                (scrollRef.current instanceof HTMLElement ? scrollRef.current : { scrollTop: 0 }).scrollTop = Math.max(
                    0,
                    startMin * PX_PER_MIN,
                );
            }
        };
        tick();
        const id = requestAnimationFrame(tick);
        return () => cancelAnimationFrame(id);
    }, [settings.dayTimelineStartView]);

    return scrollRef;
}

import { MINUTES_IN_HOUR } from "../../../core/utils/constants";
import { useState, useRef, useCallback } from "react";
import { PX_PER_MIN, SNAP_MIN } from "../types";

export function useEventCreation(
    timelineDate: Date,
    onAddEvent?: (d: Date, start: number, end: number) => void
) {
    const containerRef = useRef<HTMLDivElement>(null);
    const [createPreview, setCreatePreview] = useState<{ start: number; end: number }>();

    const onGridPointerDown = useCallback((e: React.PointerEvent<HTMLDivElement>) => {
        if (!(e.target instanceof Element)) return;
        if (e.target.closest(".day-event") || e.target.closest(".day-now")) return;
        if (e.button !== 0) return;
        e.preventDefault();

        const grid = containerRef.current;
        if (!grid) return;
        const rect = grid.getBoundingClientRect();
        const startY = e.clientY - rect.top;
        const startMin = Math.round(startY / PX_PER_MIN / SNAP_MIN) * SNAP_MIN;

        let active = false;

        const move = (ev: PointerEvent) => {
            active = true;
            const currentY = ev.clientY - rect.top;
            const moveMin = Math.round(currentY / PX_PER_MIN / SNAP_MIN) * SNAP_MIN;
            const s = Math.min(startMin, moveMin);
            const eMin = Math.max(startMin, moveMin);
            setCreatePreview({
                start: s,
                end: eMin === s ? s + SNAP_MIN : eMin,
            });
        };

        const up = (ev: PointerEvent) => {
            window.removeEventListener("pointermove", move);
            window.removeEventListener("pointerup", up);
            if (!active) {
                if (onAddEvent) {
                    onAddEvent(timelineDate, startMin, startMin + MINUTES_IN_HOUR);
                }
                return;
            }
            const currentY = ev.clientY - rect.top;
            const moveMin = Math.round(currentY / PX_PER_MIN / SNAP_MIN) * SNAP_MIN;
            const s = Math.min(startMin, moveMin);
            const eMin = Math.max(startMin, moveMin);
            const finalEnd = eMin === s ? s + SNAP_MIN : eMin;
            setCreatePreview(undefined);
            if (onAddEvent) {
                onAddEvent(timelineDate, s, finalEnd);
            }
        };

        window.addEventListener("pointermove", move);
        window.addEventListener("pointerup", up);
    }, [timelineDate, onAddEvent]);

    return { containerRef, createPreview, onGridPointerDown };
}

import type { HydratedEvent } from "../../core/domain/events";

export interface DayLayoutEvent {
    event: HydratedEvent;
    startMins: number;
    endMins: number;
}

// Simple overlap layout: assign each event to the earliest lane that's free.
export function layoutEvents(events: DayLayoutEvent[]) {
    const placed: { start: number; end: number; lane: number }[] = [];
    const result: { event: HydratedEvent; startMins: number; endMins: number; lane: number; lanes?: number }[] = [];
    for (const ev of events) {
        let lane = 0;
        while (
            placed.some(
                (p) =>
                    p.lane === lane &&
                    !(p.end <= ev.startMins || p.start >= ev.endMins),
            )
        ) {
            lane++;
        }
        placed.push({ start: ev.startMins, end: ev.endMins, lane });
        result.push({ event: ev.event, startMins: ev.startMins, endMins: ev.endMins, lane });
    }
    // Determine total lanes per cluster (events that overlap any chain)
    // For simplicity, use max lanes among overlapping events.
    return result.map((r) => {
        let maxLane = r.lane;
        for (const p of placed) {
            if (!(p.end <= r.startMins || p.start >= r.endMins)) {
                if (p.lane > maxLane) maxLane = p.lane;
            }
        }
        return Object.assign({}, r, { lanes: maxLane + 1 });
    });
}

