                    background: "none",
                    border: "none",
                    font: "inherit",
                    textAlign: "left",
                    width: "100%",
                }}
            >
                {value || "Add description..."}
            </button>
        );
    }

    return (
        <textarea
            ref={(el) => { if (el && editing) el.focus(); }}
            value={localValue || ""}
            onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => setLocalValue(e.target.value)}
            onBlur={() => {
                setEditing(false);
                if (localValue !== value) onChange(localValue || "");
            }}
            rows={5}
            style={{
                width: "100%",
                resize: "vertical",
                padding: "4px",
                fontFamily: "inherit",
                border: "1px solid var(--border)",
