import React from "react";
import type { AppEvent, AppTask } from "../../core/domain/models";
import { useCalendars } from "../../core/store/hooks";
import type { CalendarData } from "../../core/store/repositories";
import { getInspectorTitle } from "./inspector-utils";
import { InspectorPaneContent } from "./inspector-content";
import { applyRecurringUpdate, applyRecurringDelete } from "../../core/domain/rrule-utils";
import "./inspector.css";

export type InspectorState = 
    | { type: "task"; id: string }
    | { type: "event"; id: string }
    | { type: "new_task"; draft: AppTask }
    | { type: "new_event"; draft: AppEvent };

interface InspectorPaneProps {
    inspectorState?: InspectorState;
    onClose: () => void;
    tasks: AppTask[];
    setTasks: React.Dispatch<React.SetStateAction<AppTask[]>>;
    events: AppEvent[];
    setEvents: React.Dispatch<React.SetStateAction<AppEvent[]>>;
    interceptRecurringAction?: (event: AppEvent, actionType: "edit" | "delete", updates: Partial<AppEvent> | undefined, execute: (mode: import("../../core/domain/rrule-utils").RecurringMode) => void) => void;
    onDraftChange?: (draft: AppTask | AppEvent | undefined) => void;
}

function isAppTask(item: AppTask | AppEvent | undefined): item is AppTask {
    return !!item && "status" in item;
}

function isAppEvent(item: AppTask | AppEvent | undefined): item is AppEvent {
    return !!item && "startTime" in item;
}

function useCurrentItem(
    currentState: InspectorState | undefined,
    tasks: AppTask[],
    events: AppEvent[],
    draftItem: AppTask | AppEvent | undefined
) {
    if (!currentState) return { isCurrentTask: false, isNew: false };

    switch (currentState.type) {
        case "new_task": {
            const taskDraft = isAppTask(draftItem) ? draftItem : undefined;
            return { currentTask: taskDraft, currentEvent: undefined, currentItem: draftItem, isCurrentTask: true, isNew: true };
        }
        case "new_event": {
            const eventDraft = isAppEvent(draftItem) ? draftItem : undefined;
            return { currentTask: undefined, currentEvent: eventDraft, currentItem: draftItem, isCurrentTask: false, isNew: true };
        }
        case "task": {
            const currentTask = tasks.find((t) => t.id === currentState.id);
            return { currentTask, currentEvent: undefined, currentItem: currentTask, isCurrentTask: true, isNew: false };
        }
        case "event": {
            const currentEvent = events.find((e) => e.id === currentState.id) || events.find((e) => e.id === currentState.id.split("_")[0]);
            return { currentTask: undefined, currentEvent, currentItem: currentEvent, isCurrentTask: false, isNew: false };
        }
        default: {
            const _exhaustiveCheck: never = currentState;
            throw new Error(`Unhandled state type: ${JSON.stringify(_exhaustiveCheck)}`);
        }
    }
}

export function InspectorPane({
    inspectorState,
    onClose,
    tasks,
    setTasks,
    events,
    setEvents,
    interceptRecurringAction,
    onDraftChange
}: InspectorPaneProps) {
    const paneRef = React.useRef<HTMLDivElement>(null);
    const [calendars] = useCalendars();

    const [activeState, setActiveState] = React.useState<InspectorState>();
    const [draftItem, setDraftItem] = React.useState<AppTask | AppEvent>();
    const draftRef = React.useRef<AppTask | AppEvent | undefined>(undefined);
    const [inspectorEditMode, setInspectorEditMode] = React.useState<import("../../core/domain/rrule-utils").RecurringMode | undefined>(undefined);

    React.useEffect(() => {
        if (inspectorState?.type === "new_task" || inspectorState?.type === "new_event") {
            setDraftItem(inspectorState.draft);
            draftRef.current = inspectorState.draft;
        } else if (!inspectorState) {
            setDraftItem(undefined);
            draftRef.current = undefined;
        }
        if (inspectorState) setActiveState(inspectorState);
        setInspectorEditMode(undefined); // Reset mode on new item
    }, [inspectorState]);

    React.useEffect(() => {
        if (onDraftChange) {
            onDraftChange(draftItem);
        }
    }, [draftItem, onDraftChange]);

    const currentState = inspectorState || activeState;
    const { currentTask, currentEvent, currentItem, isCurrentTask, isNew } = useCurrentItem(currentState, tasks, events, draftItem);

    const isReadOnlyCalendar = React.useMemo(() => {
        if (!currentEvent) return false;
        const calId = currentEvent.remoteCollectionId || calendars.find((c: CalendarData) => c.primary)?.id || "primary";
        const cal = calendars.find((c: CalendarData) => c.id === calId);
        return Boolean(cal && cal.accessRole !== "owner" && cal.accessRole !== "writer");
    }, [currentEvent, calendars]);

    const title = getInspectorTitle(currentTask, currentEvent, tasks);
    const isOpen = !!(inspectorState && currentItem);

    const updateTask = React.useCallback((id: string, transform: (task: AppTask) => AppTask) => {
        if (isNew && draftRef.current?.id === id) {
            if (isAppTask(draftRef.current)) {
                const next = transform(draftRef.current);
                draftRef.current = next;
                setDraftItem(next);
            }
        } else {
            setTasks((ts) => ts.map((t) => t.id === id ? transform(t) : t));
        }
    }, [setTasks, isNew]);

    const updateEvent = React.useCallback((id: string, updates: Partial<AppEvent>) => {
        if (isNew && draftRef.current?.id === id) {
            if (isAppEvent(draftRef.current)) {
                const next: AppEvent = { ...draftRef.current, ...updates };
                draftRef.current = next;
                setDraftItem(next);
            }
        } else if (currentEvent && interceptRecurringAction) {
             const isRecurring = !!currentEvent.rrule || Boolean(currentEvent["isInstance"]);
             if (isRecurring && !inspectorEditMode) {
                 interceptRecurringAction(currentEvent, "edit", updates, (mode) => {
                     setInspectorEditMode(mode);
                     setEvents(es => applyRecurringUpdate(es, currentEvent, mode, updates));
                 });
             } else {
                 setEvents(es => applyRecurringUpdate(es, currentEvent, inspectorEditMode || "all", updates));
             }
        } else {
            setEvents((es) => es.map((e) => e.id === id ? { ...e, ...updates } : e));
        }
    }, [setEvents, isNew, currentEvent, interceptRecurringAction, inspectorEditMode]);

    const handleTitleChange = React.useCallback((newTitle: string) => {
        if (!currentItem) return;
        if (isCurrentTask) updateTask(currentItem.id, task => ({ ...task, title: newTitle }));
        else updateEvent(currentItem.id, { title: newTitle });
    }, [currentItem, isCurrentTask, updateTask, updateEvent]);

    const handleDescChange = React.useCallback((desc: string) => {
        if (isReadOnlyCalendar || !currentItem) return;
        if (isCurrentTask) updateTask(currentItem.id, task => ({ ...task, description: desc }));
        else updateEvent(currentItem.id, { description: desc });
    }, [currentItem, isCurrentTask, isReadOnlyCalendar, updateTask, updateEvent]);

    const onPaneDelete = React.useCallback(() => {
        if (!currentItem) return;
        if (isNew) {
            onClose();
            return;
        }
        if (isCurrentTask) {
            setTasks((ts) => ts.filter((t) => t.id !== currentItem.id));
            setEvents((es) => es.filter((e) => e.taskId !== currentItem.id));
        } else if (currentEvent && interceptRecurringAction) {
            const isRecurring = !!currentEvent.rrule || Boolean(currentEvent["isInstance"]);
            if (isRecurring) {
                interceptRecurringAction(currentEvent, "delete", undefined, (mode) => {
                    setEvents(es => applyRecurringDelete(es, currentEvent, mode));
                });
            } else {
                setEvents((es) => es.filter((e) => e.id !== currentItem.id && e.id !== currentItem.id.split("_")[0]));
            }
        } else {
            setEvents((es) => es.filter((e) => e.id !== currentItem.id && e.id !== currentItem.id.split("_")[0]));
        }
        onClose();
    }, [currentItem, isCurrentTask, isNew, setTasks, setEvents, onClose, currentEvent, interceptRecurringAction]);

    const onPaneClose = React.useCallback(() => {
        if (document.activeElement instanceof HTMLElement) {
            document.activeElement.blur();
        }
        
        const draft = draftRef.current;
        if (isNew && draft) {
            if (draft.title && draft.title.trim() !== "") {
                if (isAppTask(draft)) {
                    setTasks((ts) => [draft, ...ts]);
                } else if (isAppEvent(draft)) {
                    setEvents((es) => [...es, draft]);
                }
            }
        }
        onClose();
    }, [isNew, setTasks, setEvents, onClose]);

    React.useEffect(() => {
        function handleClickOutside(e: PointerEvent) {
            if (
                inspectorState &&
                paneRef.current &&
                !(e.target instanceof Node && paneRef.current.contains(e.target))
            ) {
                onPaneClose();
            }
        }
        document.addEventListener("pointerdown", handleClickOutside);
        return () => document.removeEventListener("pointerdown", handleClickOutside);
    }, [inspectorState, onPaneClose]);

    return (
        <div
            ref={paneRef}
            className={`inspector-pane ${isOpen ? "is-open" : ""}`}
        >
            {currentItem && (
                <InspectorPaneContent
                    currentItem={currentItem}
                    {...(currentTask !== undefined ? { currentTask } : {})}
                    {...(currentEvent !== undefined ? { currentEvent } : {})}
                    isReadOnlyCalendar={isReadOnlyCalendar}
                    title={title}
                    tasks={tasks}
                    calendars={calendars}
                    onPaneClose={onPaneClose}
                    onPaneDelete={onPaneDelete}
                    handleTitleChange={handleTitleChange}
                    handleDescChange={handleDescChange}
                    updateTask={updateTask}
                    updateEvent={updateEvent}
                    isNew={isNew}
                />
            )}
        </div>
    );
}

import React from "react";
import type { AppEvent, AppTask } from "../../core/domain/models";
import { editing } from "../../core/domain/models";
import type { CalendarData } from "../../core/store/repositories";
import type { ParsedProperties } from "../../core/utils/sigil-parser";
import { TitleInput, DescriptionInput } from "../inputs";
import { TaskInspector } from "./inspector-task";
import { EventInspector } from "./inspector-event";
import { InspectorPaneHeader } from "./inspector-shared";

function buildSigilTransform(
    props: ParsedProperties,
    existingTags: readonly string[] | undefined,
): (task: AppTask) => AppTask {
    return (task: AppTask): AppTask => {
        let next = task;
        if (props.priority !== undefined) next = editing(next).set('priority', props.priority).done();
        const newTags = props.tags ? [...(existingTags || []), ...props.tags] : undefined;
        if (newTags) next = editing(next).set('tags', newTags).done();
        if (props.duration !== undefined) next = editing(next).set('est', props.duration).done();
        return next;
    };
}

export interface InspectorPaneContentProps {
    currentItem: AppTask | AppEvent;
    currentTask?: AppTask;
    currentEvent?: AppEvent;
    isReadOnlyCalendar: boolean;
    title?: string;
    tasks: AppTask[];
    calendars: CalendarData[];
    onPaneClose: () => void;
    onPaneDelete: () => void;
    handleTitleChange: (t: string) => void;
    handleDescChange: (d: string) => void;
    updateTask: (id: string, transform: (task: AppTask) => AppTask) => void;
    updateEvent: (id: string, updates: Partial<AppEvent>) => void;
    isNew: boolean;
}

export function InspectorPaneContent({
    currentItem,
    currentTask,
    currentEvent,
    isReadOnlyCalendar,
    title,
    tasks,
    calendars,
    onPaneClose,
    onPaneDelete,
    handleTitleChange,
    handleDescChange,
    updateTask,
    updateEvent,
    isNew,
}: InspectorPaneContentProps) {
    const handlePropertiesParsed = (props: ParsedProperties) => {
        if (currentEvent && !isReadOnlyCalendar) return;
        if (!currentTask) return;

        const baseTransform = buildSigilTransform(props, currentTask.tags);

        if (props.day) {
            import('../../core/utils/sigil-parser').then(m => {
                const newDue = m.getDueDateFromSigil(String(props.day));
                updateTask(currentTask.id, task => editing(baseTransform(task)).set('due', newDue).done());
                return undefined;
            }).catch(() => {});
            return;
        }

        if (props.priority !== undefined || props.tags || props.duration !== undefined) {
            updateTask(currentTask.id, baseTransform);
        }
    };

    return (
        <React.Fragment key={currentItem.id}>
            <InspectorPaneHeader handleClose={onPaneClose} handleDelete={onPaneDelete} isReadOnlyCalendar={isReadOnlyCalendar} />
            <div className="inspector-body" style={{ paddingTop: 0 }}>
                <div
                    className="inspector-field"
                    style={{ marginTop: "24px", marginBottom: "4px" }}
                >
                    <TitleInput
                        value={title || ""}
                        onChange={handleTitleChange}
                        disabled={Boolean(currentEvent?.taskId) || isReadOnlyCalendar}
                        onEnter={onPaneClose}
                        parseMode={true}
                        onPropertiesParsed={handlePropertiesParsed}
                        style={{
                            fontSize: "24px",
                            fontWeight: "normal",
                            border: "none",
                            background: "transparent",
                            padding: "0",
                            outline: "none",
                            width: "100%",
                            color: "var(--fg)",
                        }}
                        autoFocus={isNew}
                    />
                </div>
                <div
                    className="inspector-field"
                    style={{
                        flexDirection: "column",
                        alignItems: "flex-start",
                    }}
                >
                    <DescriptionInput
                        value={(currentEvent?.description) || ""}
                        onChange={handleDescChange}
                        disabled={isReadOnlyCalendar}
                    />
                </div>

                {isReadOnlyCalendar && (
                    <div className="inspector-field" style={{color: "var(--tag-red)", fontSize: "0.85em", marginTop: "8px"}}>
                        This event belongs to a read-only calendar and cannot be modified.
                    </div>
                )}

                {currentTask ? (
                    <TaskInspector 
                        task={currentTask} 
                        updateTask={updateTask} 
                    />
                ) : currentEvent ? (
                    <EventInspector 
                        event={currentEvent} 
                        tasks={tasks}
                        calendars={calendars}
                        updateEvent={updateEvent}
                        isReadOnlyCalendar={isReadOnlyCalendar}
                    />
                ) : undefined}
            </div>
        </React.Fragment>
    );
}

import React from "react";
import type { AppEvent } from "../../core/domain/models";
import { isYmdString } from "../../core/domain/models";
import { isEventAllDay } from "../../core/domain/events";
import { Icon } from "../icon";
import { addDays, extractDateFromISO, extractTimeFromISO, extractHourMinuteFromISO } from "../../core/utils/date-utils";
import { ymd } from "../../core/store/data";
import { ICON_TIME_SEPARATOR, ICON_REMOVE, ICON_ADD_TIME, ICON_ADD_END_DATE } from "../../core/utils/icons";

const DEFAULT_START_HOUR = "09:00:00";
const DEFAULT_END_HOUR = "10:00:00";

function getDisplayEndDate(endTime: string, isAllDay: boolean): string {
    if (!isAllDay) return extractDateFromISO(endTime);
    const d = new Date(endTime + "T00:00:00");
    d.setDate(d.getDate() - 1);
    return ymd(d);
}

export function DateTimeGrid({ event, updateEvent, isReadOnlyCalendar }: { event: AppEvent, updateEvent: (id: string, updates: Partial<AppEvent>) => void, isReadOnlyCalendar: boolean }) {
    const isAllDay = isEventAllDay(event);
    const startDay = extractDateFromISO(event.startTime);
    const endDay = getDisplayEndDate(event.endTime, isAllDay);
    
    const [showEndDate, setShowEndDate] = React.useState(startDay !== endDay);
    const [localTime, setLocalTime] = React.useState<{ startTime: string, endTime: string } | undefined>(undefined);

    React.useEffect(() => setShowEndDate(startDay !== endDay), [startDay, endDay]);
    React.useEffect(() => setLocalTime(undefined), [event.startTime, event.endTime]);

    const hasTime = !isAllDay;
    const hasEndDate = showEndDate;
    const currentStartTime = localTime?.startTime || event.startTime;
    const currentEndTime = localTime?.endTime || event.endTime;

    const startDateStr = extractDateFromISO(currentStartTime);
    const startTimeStr = hasTime ? extractHourMinuteFromISO(currentStartTime) : DEFAULT_START_HOUR;
    const endDateStr = getDisplayEndDate(currentEndTime, isAllDay);
    const endTimeStr = hasTime ? extractHourMinuteFromISO(currentEndTime) : DEFAULT_END_HOUR;

    const handleTimeBlur = () => {
        if (localTime) {
            updateEvent(event.id, { startTime: localTime.startTime, endTime: localTime.endTime });
            setLocalTime(undefined);
        }
    };

    const handleRemoveEndDate = () => {
        if (isReadOnlyCalendar) return;
        setShowEndDate(false);
        if (isAllDay) {
            const nextDay = addDays(new Date(startDay + "T00:00:00"), 1);
            updateEvent(event.id, { endTime: ymd(nextDay) });
        } else {
            updateEvent(event.id, { endTime: `${startDay}T${extractTimeFromISO(event.endTime)}` });
        }
    };

    const handleAddTime = () => {
        if (isReadOnlyCalendar) return;
        updateEvent(event.id, { 
            startTime: `${startDay}T${DEFAULT_START_HOUR}`,
            endTime: `${endDay}T${DEFAULT_END_HOUR}`
        });
    };

    const handleRemoveTime = () => {
        if (isReadOnlyCalendar) return;
        let eDay = endDay;
        if (startDay === eDay) eDay = ymd(addDays(new Date(startDay + "T00:00:00"), 1));
        updateEvent(event.id, { 
            startTime: startDay,
            endTime: eDay
        });
    };

    const onStartDateChange = (newDate: string) => {
        if (!isYmdString(newDate)) return;
        
        let newEndTime = undefined;
        if (newDate > endDateStr) {
            if (isAllDay) {
                const dt = new Date(`${newDate}T00:00:00`);
                dt.setDate(dt.getDate() + 1);
                newEndTime = ymd(dt);
            } else {
                newEndTime = `${newDate}T${extractTimeFromISO(currentEndTime)}`;
            }
        }
        
        const updates: Partial<AppEvent> = { 
            startTime: isAllDay ? newDate : `${newDate}T${extractTimeFromISO(currentStartTime)}`,
            ...(newEndTime !== undefined && { endTime: newEndTime })
        };
        updateEvent(event.id, updates);
    };

    const onEndDateChange = (newEndStr: string) => {
        if (!isYmdString(newEndStr)) return;
        if (isAllDay) {
            const dt = new Date(`${newEndStr}T00:00:00`);
            dt.setDate(dt.getDate() + 1);
            updateEvent(event.id, { endTime: ymd(dt) });
        } else {
            updateEvent(event.id, { endTime: `${newEndStr}T${extractTimeFromISO(currentEndTime)}` });
        }
    };

    return (
        <div className="datetime-grid-container">
            <div className={`dtg-layout dtg-has-time-${hasTime} dtg-has-end-${hasEndDate}`}>
                {hasTime && (
                    <TimeSection 
                        startTimeStr={startTimeStr}
                        endTimeStr={endTimeStr}
                        startDateStr={startDateStr}
                        currentEndTime={currentEndTime}
                        currentStartTime={currentStartTime}
                        isReadOnlyCalendar={isReadOnlyCalendar}
                        setLocalTime={setLocalTime}
                        handleTimeBlur={handleTimeBlur}
                        handleRemoveTime={handleRemoveTime}
                    />
                )}

                <div className="dtg-field dtg-date-start">
                    <input type="date" className="inspector-date-input" value={startDateStr} disabled={isReadOnlyCalendar} onChange={(e) => onStartDateChange(e.target.value)} />
                </div>

                {hasEndDate ? (
                    <EndDateSection 
                        endDateStr={endDateStr}
                        startDateStr={startDateStr}
                        isReadOnlyCalendar={isReadOnlyCalendar}
                        onEndDateChange={onEndDateChange}
                        handleRemoveEndDate={handleRemoveEndDate}
                    />
                ) : (
                    <AddActions 
                        isReadOnlyCalendar={isReadOnlyCalendar}
                        handleAddTime={handleAddTime}
                        setShowEndDate={setShowEndDate}
                        hasTime={hasTime}
                    />
                )}
            </div>
        </div>
    );
}

function TimeSection({
    startTimeStr,
    endTimeStr,
    startDateStr,
    currentEndTime,
    currentStartTime,
    isReadOnlyCalendar,
    setLocalTime,
    handleTimeBlur,
    handleRemoveTime,
}: {
    startTimeStr: string,
    endTimeStr: string,
    startDateStr: string,
    currentEndTime: string,
    currentStartTime: string,
    isReadOnlyCalendar: boolean,
    setLocalTime: React.Dispatch<React.SetStateAction<{ startTime: string, endTime: string } | undefined>>,
    handleTimeBlur: () => void,
    handleRemoveTime: () => void,
}) {
    return (
        <>
            <div className="dtg-field dtg-time-start">
                <input
                    type="time"
                    className="inspector-date-input"
                    value={startTimeStr}
                    disabled={isReadOnlyCalendar}
                    onChange={(e) => setLocalTime({ startTime: `${startDateStr}T${e.target.value}:00`, endTime: currentEndTime })}
                    onBlur={handleTimeBlur}
                    onKeyDown={(e) => e.key === "Enter" && handleTimeBlur()}
                />
            </div>
            <div className="dtg-arrow dtg-time-arrow"><Icon name={ICON_TIME_SEPARATOR} size={18} /></div>
            <div className="dtg-field dtg-time-end">
                <input
                    type="time"
                    className="inspector-date-input"
                    value={endTimeStr}
                    disabled={isReadOnlyCalendar}
                    onChange={(e) => setLocalTime({ startTime: currentStartTime, endTime: `${extractDateFromISO(currentEndTime)}T${e.target.value}:00` })}
                    onBlur={handleTimeBlur}
                    onKeyDown={(e) => e.key === "Enter" && handleTimeBlur()}
                />
            </div>
            <div className="dtg-action dtg-time-action">
                <button className="dtg-btn-icon" onClick={handleRemoveTime} disabled={isReadOnlyCalendar} title="Remove time"><Icon name={ICON_REMOVE} size={16} /></button>
            </div>
        </>
    );
}

function EndDateSection({
    endDateStr,
    startDateStr,
    isReadOnlyCalendar,
    onEndDateChange,
    handleRemoveEndDate,
}: {
    endDateStr: string,
    startDateStr: string,
    isReadOnlyCalendar: boolean,
    onEndDateChange: (newEndStr: string) => void,
    handleRemoveEndDate: () => void,
}) {
    return (
        <>
            <div className="dtg-arrow dtg-date-arrow"><Icon name={ICON_TIME_SEPARATOR} size={18} /></div>
            <div className="dtg-field dtg-date-end">
                <input type="date" className="inspector-date-input" value={endDateStr} min={startDateStr} disabled={isReadOnlyCalendar} onChange={(e) => onEndDateChange(e.target.value)} />
            </div>
            <div className="dtg-action dtg-date-action">
                <button className="dtg-btn-icon" onClick={handleRemoveEndDate} disabled={isReadOnlyCalendar} title="Remove end date"><Icon name={ICON_REMOVE} size={16} /></button>
            </div>
        </>
    );
}

function AddActions({
    isReadOnlyCalendar,
    handleAddTime,
    setShowEndDate,
    hasTime,
}: {
    isReadOnlyCalendar: boolean,
    handleAddTime: () => void,
    setShowEndDate: (show: boolean) => void,
    hasTime: boolean,
}) {
    if (!hasTime) {
        return (
            <div className="dtg-inline-actions">
                <button className="dtg-btn-icon" onClick={handleAddTime} disabled={isReadOnlyCalendar} title="Add time"><Icon name={ICON_ADD_TIME} size={18} /></button>
                <button className="dtg-btn-icon" onClick={() => !isReadOnlyCalendar && setShowEndDate(true)} disabled={isReadOnlyCalendar} title="Add end date"><Icon name={ICON_ADD_END_DATE} size={18} /></button>
            </div>
        );
    }
    return (
        <div className="dtg-bottom-actions">
            <button className="dtg-btn-icon" onClick={() => !isReadOnlyCalendar && setShowEndDate(true)} disabled={isReadOnlyCalendar} title="Add end date"><Icon name={ICON_ADD_END_DATE} size={18} /></button>
        </div>
    );
}

import type { AppEvent, AppTask } from "../../core/domain/models";
import { RepeatSelect } from "./inspector-shared";
import { DateTimeGrid } from "./inspector-datetime";

import "./inspector.css";

interface EventInspectorProps {
    event: AppEvent;
    tasks: AppTask[];
    calendars: { id: string, summary?: string, accessRole?: string, primary?: boolean }[];
    updateEvent: (id: string, updates: Partial<AppEvent>) => void;
    isReadOnlyCalendar: boolean;
}



function EventTypeSelector({ event, tasks, updateEvent, isReadOnlyCalendar }: { event: AppEvent, tasks: AppTask[], updateEvent: (id: string, updates: Partial<AppEvent>) => void, isReadOnlyCalendar: boolean }) {
    return (
        <>
            <div className="inspector-field inspector-field-group">
                <select
                    value={event.type}
                    disabled={isReadOnlyCalendar}
                    onChange={(e) => {
                        const type: "busy" | "info" = e.target.value === "busy" ? "busy" : "info";
                        updateEvent(event.id, { type });
                    }}
                >
                    <option value="busy">Busy</option>
                    <option value="info">Informational (Free)</option>
                </select>
            </div>
            <div className="inspector-field">
                <select
                    value={event.taskId || ""}
                    disabled={isReadOnlyCalendar}
                    onChange={(e) => updateEvent(event.id, { taskId: e.target.value || undefined })}
                >
                    <option value="">-- No task attached --</option>
                    {tasks.map((t) => <option key={t.id} value={t.id}>{t.title}</option>)}
                </select>
            </div>
        </>
    );
}

function EventCalendarSelector({ event, calendars, updateEvent, isReadOnlyCalendar }: { event: AppEvent, calendars: { id: string, summary?: string, accessRole?: string, primary?: boolean }[], updateEvent: (id: string, updates: Partial<AppEvent>) => void, isReadOnlyCalendar: boolean }) {
    return (
        <div className="inspector-field inspector-field-group">
            <label htmlFor={`calendar-${event.id}`}>Calendar</label>
            <select
                id={`calendar-${event.id}`}
                value={event.remoteCollectionId || calendars.find((c) => c.primary)?.id || "primary"}
                disabled={isReadOnlyCalendar}
                onChange={(e) => {
                    updateEvent(event.id, { remoteCollectionId: e.target.value });
                }}
            >
                {calendars.map((c) => (
                    <option key={c.id} value={c.id} disabled={c.accessRole !== "owner" && c.accessRole !== "writer"}>
                        {c.summary}{c.accessRole !== "owner" && c.accessRole !== "writer" ? " (Read-Only)" : ""}
                    </option>
                ))}
            </select>
        </div>
    );
}

function EventRepeatControls({ event, updateEvent, isReadOnlyCalendar }: { event: AppEvent, updateEvent: (id: string, updates: Partial<AppEvent>) => void, isReadOnlyCalendar: boolean }) {
    return (
        <div className="inspector-field inspector-field-group">
            <label htmlFor={`rrule-${event.id}`}>Repeat (RRULE)</label>
            <div className="inspector-field-group" style={{ marginTop: 0 }}>
                <RepeatSelect
                    value={event.rrule || ""}
                    disabled={isReadOnlyCalendar}
                    onChange={(e) => updateEvent(event.id, { rrule: e.target.value || undefined })}
                />
                <input
                    type="text"
                    placeholder="Custom RRULE (e.g. FREQ=WEEKLY;BYDAY=TU,TH)"
                    value={event.rrule || ""}
                    disabled={isReadOnlyCalendar}
                    onChange={(e) => updateEvent(event.id, { rrule: e.target.value || undefined })}
                />
            </div>
        </div>
    );
}

export function EventInspector({ event, tasks, calendars, updateEvent, isReadOnlyCalendar }: EventInspectorProps) {
    return (
        <>
            <EventTypeSelector event={event} tasks={tasks} updateEvent={updateEvent} isReadOnlyCalendar={isReadOnlyCalendar} />
            <EventCalendarSelector event={event} calendars={calendars} updateEvent={updateEvent} isReadOnlyCalendar={isReadOnlyCalendar} />
            <EventRepeatControls event={event} updateEvent={updateEvent} isReadOnlyCalendar={isReadOnlyCalendar} />

            <DateTimeGrid event={event} updateEvent={updateEvent} isReadOnlyCalendar={isReadOnlyCalendar} />
        </>
    );
}

