export function LabeledToggle({ label, checked, onChange, disabled }: { label: string, checked: boolean, onChange: (v: boolean) => void, disabled?: boolean }) {
    return (
        <button type="button" className="inspector-toggle-label" disabled={disabled} onClick={() => onChange(!checked)}>
            <div className={`toggle-switch ${checked ? "is-on" : ""}`}>
                <div className="toggle-switch-thumb" />
            </div>
            <span className="inspector-toggle-text">{label}</span>
        </button>
    );
}

import { MINUTES_IN_HOUR } from "../../core/utils/constants";
import React from "react";
import { type AppTask, isAppTaskStatus, isYmdString, editing } from "../../core/domain/models";
import { TaskStatusSelect } from "./inspector-shared";

const MAX_PRIORITY = 4;

interface TaskInspectorProps {
    task: AppTask;
    updateTask: (id: string, transform: (task: AppTask) => AppTask) => void;
}

export function TaskInspector({ task, updateTask }: TaskInspectorProps) {
    return (
        <>
            <div className="inspector-row">
                <div className="inspector-field">
                    <label htmlFor={`status-${task.id}`}>Status</label>
                    <TaskStatusSelect
                        value={task.status || "todo"}
                        onChange={(e) => {
                            const val = e.target.value;
                            if (isAppTaskStatus(val)) {
                                updateTask(task.id, t => editing(t).set('status', val).done());
                            }
                        }}
                    />
                </div>
                <div className="inspector-field">
                    <label htmlFor={`priority-${task.id}`}>Priority</label>
                    <input
                        id={`priority-${task.id}`}
                        type="number"
                        min="0"
                        max={MAX_PRIORITY}
                        value={task.priority ?? 2}
                        onChange={(e: React.ChangeEvent<HTMLInputElement>) =>
                            updateTask(task.id, t => editing(t).set('priority', Math.max(
                                0,
                                Math.min(
                                    MAX_PRIORITY,
                                    parseInt(e.target.value) || 0,
                                ),
                            )).done())
                        }
                    />
                </div>
            </div>

            <div className="inspector-field">
                <label htmlFor={`due-${task.id}`}>Due Date</label>
                <input
                    id={`due-${task.id}`}
                    className="inspector-date-input"
                    type="date"
                    value={task.due ?? ""}
                    onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
                        const raw = e.target.value;
                        if (isYmdString(raw)) {
                            updateTask(task.id, t => editing(t).set('due', raw).done());
                        } else {
                            updateTask(task.id, t => editing(t).clear('due').done());
                        }
                    }}
                />
            </div>

            <div className="inspector-field">
                <label htmlFor={`duration-${task.id}`}>Duration (min)</label>
                <input
                    id={`duration-${task.id}`}
                    type="number"
                    placeholder="Unset"
                    value={!task.est ? "" : task.est}
                    onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
                        let val = e.target.value ? parseInt(e.target.value) : 0;
                        if (val > MINUTES_IN_HOUR) val = MINUTES_IN_HOUR;
                        updateTask(task.id, t => editing(t).set('est', val).done());
                    }}
                />
            </div>
        </>
    );
}

import type { AppTask, AppEvent } from "../../core/domain/models";
import { MINUTES_IN_HOUR } from "../../core/utils/constants";

export function minToTime(m: number): string {
    if (typeof m !== "number" || isNaN(m)) return "";
    const hh = String(Math.floor(m / MINUTES_IN_HOUR)).padStart(2, "0");
    const mm = String(m % MINUTES_IN_HOUR).padStart(2, "0");
    return `${hh}:${mm}`;
}

export function timeToMin(t: string): number {
    if (!t) return 0;
    const [hh, mm] = t.split(":");
    return parseInt(hh || "0", 10) * MINUTES_IN_HOUR + parseInt(mm || "0", 10);
}

export function getInspectorTitle(currentTask: AppTask | undefined, currentEvent: AppEvent | undefined, tasks: AppTask[]): string {
    if (currentTask) return currentTask.title || "";
    if (currentEvent) {
        if (currentEvent.taskId) {
            return tasks.find((t: AppTask) => t.id === currentEvent.taskId)?.title || "";
        }
        return currentEvent.title || "";
    }
    return "";
}

