import { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { ICON_DROPDOWN } from "../../core/utils/icons";
import { Icon } from "../icon";

export function MoreScreensDropdown() {
    const [dropdownOpen, setDropdownOpen] = useState(false);
    const dropdownRef = useRef<HTMLDivElement>(null);
    const navigate = useNavigate();

    useEffect(() => {
        const handleOutsideClick = (e: PointerEvent) => {
            if (
                dropdownRef.current &&
                e.target instanceof Node &&
                !dropdownRef.current.contains(e.target)
            ) {
                setDropdownOpen(false);
            }
        };
        if (dropdownOpen)
            document.addEventListener("pointerdown", handleOutsideClick);
        return () =>
            document.removeEventListener("pointerdown", handleOutsideClick);
    }, [dropdownOpen]);

    return (
        <div className="more-screens-dropdown" ref={dropdownRef}>
            <button
                className={`stage dropdown-btn ${dropdownOpen ? "is-current" : ""}`}
                onClick={() => setDropdownOpen(!dropdownOpen)}
                title="More screens"
                data-cuelume-hover="tick"
                data-cuelume-toggle
            >
                <Icon name={ICON_DROPDOWN} size={18} />
            </button>
            {dropdownOpen && (
                <div className="dropdown-menu">
                    {["wrap", "graph", "stats", "recap", "docs", "dev"].map((screen) => (
                        <button
                            key={screen}
                            className="dd-item"
                            onClick={() => {
                                setDropdownOpen(false);
                                void navigate(`/${screen}`);
                            }}
                            data-cuelume-hover="tick"
                            data-cuelume-toggle
                        >
                            <span className="stage-name">{screen}</span>
                        </button>
                    ))}
                </div>
            )}
        </div>
    );
}

import React from "react";
import { Link } from "react-router-dom";

export function StageIndicator({ current }: { current: string }) {
    const stages = [
        { key: "plan", label: "plan", href: "/plan" },
        { key: "do", label: "do", href: "/do" },
    ];
    const isDefault = ["plan", "do", "settings"].includes(current);

    return (
        <nav className="stages" aria-label="Stages">
            {stages.map((s, i) => (
                <React.Fragment key={s.key}>
                    <Link
                        to={s.href}
                        className={`stage ${current === s.key ? "is-current" : ""}`}
                        aria-current={current === s.key ? "page" : undefined}
                        data-cuelume-hover="tick"
                        data-cuelume-toggle
                    >
                        <span className="stage-name">{s.label}</span>
                    </Link>
                    {(i < stages.length - 1 || !isDefault) && (
                        <span className="stage-sep">|</span>
                    )}
                </React.Fragment>
            ))}
            {!isDefault && current && (
                <div className="stage is-current" style={{ display: "flex" }}>
                    <span className="stage-name">{current}</span>
                </div>
            )}
        </nav>
    );
}

import { MS_PER_SECOND, MS_PER_MINUTE } from "../../core/utils/constants";
import React, { useEffect, useRef } from "react";
import { Icon } from "../icon";
import { syncState, poller } from "../../core/sync";
import { WindowControls } from "./window-controls";

export function SyncStatus() {
    const syncStatus = React.useSyncExternalStore(
        (listener) => syncState.subscribe(listener),
        () => syncState.getUiStatus()
    );
    const syncBtnRef = useRef<HTMLButtonElement>(null);

    useEffect(() => {
        if (syncStatus === "sync_disabled") {
            if (syncBtnRef.current) syncBtnRef.current.title = "Sync Disabled";
            return undefined;
        }

        const updateTitle = () => {
            if (!syncBtnRef.current) return;
            const remaining = Math.max(0, syncState.nextSyncTime - Date.now());
            const m = Math.floor(remaining / MS_PER_MINUTE);
            const s = Math.floor((remaining % MS_PER_MINUTE) / MS_PER_SECOND);
            syncBtnRef.current.title = `Next sync in ${m}m ${s}s (Click to force sync)`;
        };

        updateTitle();
        const interval = setInterval(updateTitle, MS_PER_SECOND);
        return () => clearInterval(interval);
    }, [syncStatus]);

    return (
        <WindowControls>
            <button
                ref={syncBtnRef}
                className="win-btn sync-btn"
                onClick={() => poller.forceSync()}
                data-cuelume-hover="tick"
                data-cuelume-toggle
            >
                <Icon
                    name={syncStatus === "syncing" ? "sync" : syncStatus}
                    size={18}
                    className={`sync-icon ${syncStatus === "syncing" ? "is-syncing" : ""}`}
                    style={{
                        color: syncStatus === "sync_problem" ? "#ff4444" : undefined,
                    }}
                />
            </button>
        </WindowControls>
    );
}

import React, { useState, useRef } from "react";

const SPLIT_PANE_THRESHOLD_PX = 50;
const SIDEBAR_DEFAULT_WIDTH_PX = 360;


function useSplitPane(direction: "horizontal" | "vertical", defaultSize: number, snapThreshold: number) {
    const [size, setSize] = useState(defaultSize);
    const [isDragging, setIsDragging] = useState(false);
    const containerRef = useRef<HTMLDivElement>(null);

    const isHoriz = direction === "horizontal";

    const onPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
        e.preventDefault();
        setIsDragging(true);
        if (e.target instanceof Element) e.target.setPointerCapture(e.pointerId);
    };

    const onPointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
        if (!isDragging || !containerRef.current) return;
        const rect = containerRef.current.getBoundingClientRect();
        let newSize;
        if (isHoriz) {
            newSize = e.clientX - rect.left;
        } else {
            newSize = e.clientY - rect.top;
        }

        if (newSize < snapThreshold) newSize = 0;

        const maxSize = isHoriz ? rect.width : rect.height;
        if (newSize > maxSize - snapThreshold) newSize = maxSize;

        setSize(newSize);
    };

    const onPointerUp = (e: React.PointerEvent<HTMLDivElement>) => {
        setIsDragging(false);
        if (e.target instanceof Element) e.target.releasePointerCapture(e.pointerId);
    };

    return { size, isDragging, containerRef, onPointerDown, onPointerMove, onPointerUp, isHoriz };
}

function getContainerStyle(isHoriz: boolean, isDragging: boolean): React.CSSProperties {
    return {
        display: "flex",
        flexDirection: isHoriz ? "row" : "column",
        width: "100%",
        height: "100%",
        overflow: "hidden",
        pointerEvents: isDragging ? "none" : "auto",
    };
}

function getFirstChildStyle(isHoriz: boolean, size: number, minSize: number): React.CSSProperties {
    return {
        [isHoriz ? "width" : "height"]: size,
        [isHoriz ? "minWidth" : "minHeight"]: size > 0 ? minSize : 0,
        display: size === 0 ? "none" : "flex",
        flexDirection: "column",
        overflow: "hidden",
        flexShrink: 0,
    };
}

function getDividerStyle(isHoriz: boolean, isDragging: boolean): React.CSSProperties {
    return {
        [isHoriz ? "width" : "height"]: "6px",
        [isHoriz ? "marginLeft" : "marginTop"]: "-3px",
        [isHoriz ? "marginRight" : "marginBottom"]: "-3px",
        cursor: isHoriz ? "col-resize" : "row-resize",
        flexShrink: 0,
        zIndex: 10,
        position: "relative",
        pointerEvents: "auto",
        backgroundColor: isDragging ? "var(--accent)" : "transparent",
        transition: "background-color 0.15s ease",
    };
}

const secondChildStyle: React.CSSProperties = {
    flex: 1,
    minWidth: 0,
    minHeight: 0,
    display: "flex",
    flexDirection: "column",
    overflow: "hidden",
};

export function SplitPane({
    direction = "horizontal",
    defaultSize = SIDEBAR_DEFAULT_WIDTH_PX,
    minSize = 100,
    snapThreshold = SPLIT_PANE_THRESHOLD_PX,
    children,
}: {
    direction?: "horizontal" | "vertical";
    defaultSize?: number;
    minSize?: number;
    snapThreshold?: number;
    children: React.ReactNode;
}) {
    const { size, isDragging, containerRef, onPointerDown, onPointerMove, onPointerUp, isHoriz } = useSplitPane(direction, defaultSize, snapThreshold);

    const childArray = React.Children.toArray(children);
    const firstChild = childArray[0];
    const secondChild = childArray[1];

    return (
        <div ref={containerRef} style={getContainerStyle(isHoriz, isDragging)}>
            <div style={getFirstChildStyle(isHoriz, size, minSize)}>
                {firstChild}
            </div>

            <div
                onPointerDown={onPointerDown}
                onPointerMove={onPointerMove}
                onPointerUp={onPointerUp}
                style={getDividerStyle(isHoriz, isDragging)}
                className="split-pane-divider"
            />

            <div style={secondChildStyle}>
                {secondChild}
            </div>
        </div>
    );
}

import React from "react";

export interface TaskCircleProps {
    priority?: number | string;
    isDoneOrChecking: boolean;
    isActive?: boolean;
    onClick: (e: React.MouseEvent<HTMLButtonElement>) => void;
    onContextMenu?: (e: React.MouseEvent<HTMLButtonElement>) => void;
    style?: React.CSSProperties;
    title?: string;
    ariaLabel?: string;
}

export function TaskCircle({
    priority,
    isDoneOrChecking,
    isActive,
    onClick,
    onContextMenu,
    style,
    title,
    ariaLabel,
}: TaskCircleProps) {
