            style={{ border: "none", padding: 0, font: "inherit", color: "inherit", ...style }}
            onClick={onClick}
            onContextMenu={onContextMenu}
            title={title || "Toggle Done"}
            aria-label={ariaLabel || `Priority ${priority}`}
        >
            {isActive ? (
                <svg
                    className="task-circle-play"
