import type { AppTask, AppFilter } from "../../core/domain/models";

export function matchesFilterValue(task: AppTask, column: string, values: (string | number)[]) {
    if (column === "status") return values.includes(task.status || "");
    if (column === "priority") return values.includes(task.priority || 0) || values.includes(String(task.priority));
    if (column === "tag") return values.some((v) => (task.tags || []).includes(String(v)));
    return false;
}

export function checkTaskAgainstFilters(task: AppTask, filters?: AppFilter[]) {
    if (!filters || filters.length === 0) return false;
    for (const f of filters) {
        if (!f.column || (!f.value && f.value !== 0)) continue;
        const values = Array.isArray(f.value) ? f.value : [f.value];
        if (values.length === 0) continue;
        const match = matchesFilterValue(task, f.column, values);
        const passes = f.operator === "is not" ? !match : match;
        if (!passes) return true;
    }
    return false;
}

import React from "react";
import Fuse from "fuse.js";
import { Icon } from "../icon";
import { ICON_ADD_TASK } from "../../core/utils/icons";
import { SearchBar } from "../search-bar";
import { FilterSortButtons } from "../../screens/plan/shared-menus";
import { computeFilterDefaults } from "../../core/domain/filters";
import type { AppTask, AppFilter } from "../../core/domain/models";
import { TaskRow } from "./task-row";
import { useEvents } from "../../core/store/hooks";

export interface TaskListPaneProps {
    tasks: AppTask[];
    setTasks: React.Dispatch<React.SetStateAction<AppTask[]>>;
    filters: AppFilter[];
    setFilters: React.Dispatch<React.SetStateAction<AppFilter[]>>;
    sort: string;
    setSort: (sort: string) => void;
    query: string;
    setQuery: (q: string) => void;
    onDragStart?: (e: React.PointerEvent<HTMLElement> | React.MouseEvent<HTMLElement>, task: AppTask) => void;
    activeDragId?: string;
    onAddTask: (defaults?: Partial<AppTask>) => void;
    onDeleteTask?: (id: string) => void;
    footer?: React.ReactNode;
}


export function TaskListPane({
    tasks,
    setTasks,
    filters,
    setFilters,
    sort,
    setSort,
    query,
    setQuery,
    onDragStart,
    activeDragId,
    onAddTask,
    onDeleteTask,
    footer,
}: TaskListPaneProps) {
    const [events] = useEvents();
    
    const pastDueTaskIds = React.useMemo(() => {
        const now = Date.now();
        const set = new Set<string>();
        const taskMap = new Map(tasks.map((t) => [t.id, t]));
        events.forEach(e => {
            if (e.taskId && taskMap.get(e.taskId)?.status !== 'done') {
                if (new Date(e.endTime).getTime() < now) {
                    set.add(e.taskId);
                }
            }
        });
        return set;
    }, [events, tasks]);

    const updateTask = (id: string, transform: (task: AppTask) => AppTask) =>
        setTasks((ts) => {
            const target = ts.find(t => t.id === id);
            const newStatus = target ? transform(target).status : undefined;
            const becomingDoing = newStatus === "doing";
            return ts.map((t) => {
                if (t.id === id) return transform(t);
                if (becomingDoing && t.status === "doing") return { ...t, status: "todo" as const };
                return t;
            });
        });
    const deleteTask = (id: string) => {
        if (onDeleteTask) {
            onDeleteTask(id);
        } else {
            setTasks((ts) => ts.filter((t) => t.id !== id));
        }
    };

    const allTags = React.useMemo(() => {
        const s = new Set<string>();
        tasks.forEach((t) => (t.tags || []).forEach((tag) => s.add(tag)));
        return Array.from(s).toSorted();
    }, [tasks]);

    const filtered = React.useMemo(() => {
        let xs = tasks;
        for (const f of filters) {
            if (!f.column || (!f.value && f.value !== 0)) continue;
            xs = xs.filter((t) => {
                let match = false;
                const values = Array.isArray(f.value) ? f.value : [f.value];
                if (values.length === 0) return true;
                
                if (f.column === "status") {
                    match = values.includes(t.status || "");
                } else if (f.column === "priority") {
                    match = values.includes(t.priority || 0) || values.includes(String(t.priority));
                } else if (f.column === "tag") {
                    match = values.some((v) => (t.tags || []).includes(String(v)));
                }
                return f.operator === "is not" ? !match : match;
            });
        }
        if (query.trim()) {
            const fuse = new Fuse(xs, {
                keys: ["title", "tags"],
                threshold: 0.4,
            });
            xs = fuse.search(query).map((result) => result.item);
        }
        const cmp: Record<string, (a: AppTask, b: AppTask) => number> = {
            priority: (a, b) => (b.priority || 0) - (a.priority || 0),
            due: (a, b) => (a.due || "9999").localeCompare(b.due || "9999"),
            est: (a, b) => (a.est || 0) - (b.est || 0),
            title: (a, b) => a.title.localeCompare(b.title),
            added: () => 0,
        };
        return xs.toSorted(cmp[sort] || (() => 0));
    }, [tasks, filters, sort, query]);

    const handleAddTask = () => {
        onAddTask(computeFilterDefaults(filters));
    };

    return (
        <aside className="task-pane">
            <header className="task-pane-hd">
                <SearchBar value={query} onChange={setQuery} />
                <div
                    className="task-pane-controls"
                    style={{
                        display: "flex",
                        gap: "8px",
                        alignItems: "center",
                        flexWrap: "wrap",
                        width: "100%",
                    }}
                >
                    <FilterSortButtons
                        filters={filters}
                        setFilters={setFilters}
                        sort={sort}
                        setSort={setSort}
                        columns={[
                            { id: "status", label: "Status" },
                            { id: "priority", label: "Priority" },
                            { id: "tag", label: "Tag" },
                        ]}
                        getValuesForColumn={(col: string) => {
                            if (col === "status")
                                return ["todo", "next-up", "doing", "done"];
                            if (col === "priority") return ["0", "1", "2", "3", "4"];
                            if (col === "tag") return allTags;
                            return [];
                        }}
                        sortOptions={[
                            { id: "priority", label: "Priority" },
                            { id: "due", label: "Due Date" },
                            { id: "est", label: "Estimate" },
                            { id: "title", label: "Title" },
                            { id: "added", label: "Date Added" },
                        ]}
                    />

                    <button
                        style={{
                            marginLeft: "auto",
                            background: "var(--bg-surface)",
                            border: "1px solid var(--border)",
                            color: "var(--fg)",
                            borderRadius: "4px",
                            cursor: "pointer",
                            padding: "4px 6px",
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "center",
                        }}
                        title="Add Task"
                        onClick={handleAddTask}
                    >
                        <Icon name={ICON_ADD_TASK} size={16} />
                    </button>
                </div>
            </header>

            <div
                className="task-list"
                onDoubleClick={(e) => {
                    if (!(e.target instanceof Element)) return;
                    const target = e.target;
                    if (
                        !target.closest(".task-row") &&
                        !target.closest("button")
                    ) {
                        handleAddTask();
                    }
                }}
            >
                {filtered.length === 0 ? (
                    <div className="task-empty">
                        <span className="dim">
                            {tasks.length === 0
                                ? "no tasks exist."
                                : "no tasks match."}
                        </span>
                    </div>
                ) : (
                    filtered.map((t) => (
                        <TaskRow
                            key={t.id}
                            task={t}
                            {...(onDragStart !== undefined ? { onDragStart } : {})}
                            dragging={activeDragId === t.id}
                            updateTask={updateTask}
                            deleteTask={deleteTask}
                            filters={filters}
                            isPastDue={pastDueTaskIds.has(t.id)}
                        />
                    ))
                )}
            </div>

            {footer}
        </aside>
    );
}

import React, { useState } from "react";
import { TODAY, parseYMD, durationLabel, dueLabel } from "../../core/store/data";
import { type AppTask, type AppFilter, isAppTaskStatus, editing } from "../../core/domain/models";
import { checkTaskAgainstFilters } from "./filters";
import { Icon } from "../icon";
import { ICON_OVERDUE, ICON_TABS } from "../../core/utils/icons";
import { TaskCircle } from "../task-circle";

const TRANSITION_DURATION_MS = 400;


export interface TaskRowProps {
    task: AppTask;
    onDragStart?: (e: React.PointerEvent<HTMLDivElement> | React.MouseEvent<HTMLDivElement>, task: AppTask) => void;
    dragging?: boolean;
    updateTask: (id: string, transform: (task: AppTask) => AppTask) => void;
    deleteTask: (id: string) => void;
    filters: AppFilter[];
    isPastDue?: boolean;
}

export function TaskRow({
    task,
    onDragStart,
    dragging,
    updateTask,
    deleteTask,
    filters,
    isPastDue,
}: TaskRowProps) {
    const [isExiting, setIsExiting] = useState(false);
    const [isChecking, setIsChecking] = useState(false);

    const willBeFilteredOut = (newStatus: AppTask["status"]) => {
        return checkTaskAgainstFilters({ ...task, status: newStatus }, filters);
    };

    const handlePointerDown = (e: React.PointerEvent<HTMLDivElement> | React.MouseEvent<HTMLDivElement>) => {
        if (e.button !== 0) return;
        if (e.target instanceof Element && (
            e.target.closest(".task-row-subtask-toggle") ||
            e.target.closest(".task-row-actions") ||
            e.target.closest(".task-circle")
        ))
            return;
        onDragStart?.(e, task);
    };

    const dueStr = task.due ? dueLabel(task.due, TODAY) : "";
    const overdue =
        task.due && parseYMD(task.due) < TODAY && task.status !== "done";

    return (
        <div
            className={`task-row ${dragging ? "is-dragging" : ""} ${task.status === "done" ? "is-done" : ""} ${isExiting ? "is-exiting" : ""}`}
            onPointerDown={handlePointerDown}
        >
            <TaskCircle
                {...(task.priority !== undefined ? { priority: task.priority } : {})}
                isDoneOrChecking={task.status === "done" || isChecking}
                isActive={task.status === "doing"}
                onContextMenu={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    if (task.status !== "doing") {
                        updateTask(task.id, t => editing(t).set('status', 'doing').done());
                    } else {
                        updateTask(task.id, t => editing(t).set('status', 'todo').done());
                    }
                }}
                onClick={(e) => {
                    e.stopPropagation();
                    const newStatus = task.status === "done" ? "todo" : "done";
                    const isRemoving = willBeFilteredOut(newStatus);

                    if (newStatus === "done") {
                        setIsChecking(true);
                        void import("cuelume").then(({ play }) => play("success"));
                    } else {
                        void import("cuelume").then(({ play }) => play("release"));
                    }

                    if (isRemoving) {
                        setIsExiting(true);
                        setTimeout(() => {
                            updateTask(task.id, t => editing(t).set('status', newStatus).done());
                            setIsChecking(false);
                            setIsExiting(false);
                        }, TRANSITION_DURATION_MS);
                        return;
                    }

                    updateTask(task.id, t => editing(t).set('status', newStatus).done());
                    if (newStatus === "todo") {
                        setIsChecking(false);
                    }
                }}
            />
            <div className="task-row-content">
                <TaskRowLine1 
                    task={task} 
                    {...(isPastDue !== undefined ? { isPastDue } : {})} 
                    updateTask={updateTask} 
                    deleteTask={deleteTask} 
                    setIsExiting={setIsExiting} 
                />
                { (task.est || (task.tags && task.tags.length > 0) || (task.subtasks && task.subtasks.length > 0) || dueStr) && (
                    <TaskRowLine2 task={task} dueStr={dueStr} overdue={Boolean(overdue)} />
                )}
            </div>
        </div>
    );
}

function TaskRowLine1({
    task,
    isPastDue,
    updateTask,
    deleteTask,
    setIsExiting,
}: {
    task: AppTask;
    isPastDue?: boolean;
    updateTask: (id: string, transform: (task: AppTask) => AppTask) => void;
    deleteTask: (id: string) => void;
    setIsExiting: (exiting: boolean) => void;
}) {
    return (
        <div className="task-row-line1">
            <span className="task-row-title">
                {isPastDue && task.status !== "done" && (
                    <Icon name={ICON_OVERDUE} size={14} style={{ marginRight: '4px', color: 'var(--p0)', verticalAlign: 'middle' }} />
                )}
                {task.title}
                {task.tabs && (
                    <button
                        className="open-tabs-button"
                        title="Open Tabs"
                        onPointerDown={(e) => e.stopPropagation()}
                        onClick={(e) => {
                            e.stopPropagation();
                            const urls = task.tabs?.match(/https?:\/\/[^\s"']+/g) || [];
                            urls.forEach((url) => window.open(url, '_blank'));
                        }}
                        style={{
                            cursor: 'pointer',
                            marginLeft: '6px',
                            verticalAlign: 'middle',
                            display: 'inline-flex',
                            background: 'none',
                            border: 'none',
                            padding: 0,
                        }}
                    >
                        <Icon name={ICON_TABS} size={16} style={{ color: 'var(--accent)' }} />
                    </button>
                )}
            </span>
            {task.status === "next-up" && (
                <span className="status-pill status-nextup">
                    next up
                </span>
            )}
            <select
                className="status-select"
                value={task.status || "todo"}
                onChange={(e) => {
                    const val = e.target.value;
                    if (isAppTaskStatus(val)) {
                        updateTask(task.id, t => editing(t).set('status', val).done());
                    }
                }}
                onClick={(e) => e.stopPropagation()}
            >
                <option value="todo">todo</option>
                <option value="doing">doing</option>
                <option value="next-up">next up</option>
                <option value="done">done</option>
            </select>

            <div className="task-row-actions">
                <button
                    onClick={(e) => {
                        e.stopPropagation();
                        if (e.shiftKey || confirm("Delete task?")) {
                            setIsExiting(true);
                            setTimeout(() => deleteTask(task.id), TRANSITION_DURATION_MS);
                        }
                    }}
                    title="Delete"
                >
                    <span
                        className="material-symbols-outlined"
                        style={{
                            fontSize: "18px",
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "center",
                        }}
                    >
                        delete
                    </span>
                </button>
            </div>
        </div>
    );
}

function TaskRowLine2({ task, dueStr, overdue }: { task: AppTask; dueStr: string; overdue: boolean }) {
    const tags = task.tags || [];
    const subtasks = task.subtasks || [];
    const est = task.est || 0;
    const hasTags = tags.length > 0;
    const hasSubtasks = subtasks.length > 0;
    const hasEst = est > 0;


    const doneSubtasks = hasSubtasks ? subtasks.filter((s) => s.done).length : 0;
    const totalSubtasks = subtasks.length;

    return (
        <div className="task-row-line2">
            {hasEst && (
                <>
                    <span className="meta-est">
                        {durationLabel(est)}
                    </span>
                    {hasTags && <span className="meta-sep">·</span>}
                </>
            )}
            
            {tags.map((tag, i) => (
                <React.Fragment key={tag}>
                    <span className="meta-tag">#{tag}</span>
                    {i < tags.length - 1 && <span className="meta-tag-sep">,</span>}
                </React.Fragment>
            ))}
            
            <span className="meta-spacer" />
            
            {hasSubtasks && (
                <span
                    className="meta-subtasks"
                    title={`${doneSubtasks}/${totalSubtasks} subtasks done`}
                >
                    ☐{doneSubtasks}/{totalSubtasks}
                </span>
            )}
            
            {dueStr && (
                <span className={`meta-due ${overdue ? "is-overdue" : ""}`}>
                    due {dueStr}
                </span>
            )}
        </div>
    );
}

