import React, { useState } from "react";

import { AuthContext } from "./context";

import { useNotification } from "../utils/notifications";
export interface User { uid: string; email: string; displayName: string; }

import {
    loadRemoteIdentityScript,
    requestGoogleAuthCode,
    exchangeAuthCodeForTokens,
} from "./googleAuthUtils";

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({
    children,
}) => {
    const [user, setUser] = useState<User | undefined>(() => {
        const token = localStorage.getItem("google_access_token");
        return token ? { uid: "local-user", email: "user@example.com", displayName: "Local User" } : undefined;
    });
    const [loading] = useState(false);
    const { notify } = useNotification();

    const loginWithGoogle = React.useCallback(async () => {
        const result = await loadRemoteIdentityScript()
            .andThen(() => requestGoogleAuthCode())
            .andThen((code) => exchangeAuthCodeForTokens(code));

        if (result.isOk()) {
            const tokens = result.value;
            if (tokens.accessToken) {
                localStorage.setItem("google_access_token", tokens.accessToken);
                if (tokens.refreshToken) {
                    localStorage.setItem("google_refresh_token", tokens.refreshToken);
                }
                window.location.reload(); // Reload to start sync
            }
        } else {
            console.error("Error signing in with Google:", result.error);
            notify(`Sign in failed: ${result.error.message}`, "error");
        }
    }, [notify]);

    const logout = React.useCallback(async () => {
        try {
            localStorage.removeItem("google_access_token");
            localStorage.removeItem("google_refresh_token");
            setUser(undefined);
            window.location.reload();
        } catch (error: unknown) {
            console.error("Error signing out:", error);
            const message =
                error instanceof Error ? error.message : String(error);
            notify(`Logout failed: ${message}`, "error");
        }
    }, [notify]);

    const contextValue = React.useMemo(
        () => ({ user, loading, loginWithGoogle, logout }),
        [user, loading, loginWithGoogle, logout]
    );

    return (
        <AuthContext.Provider value={contextValue}>
            {children}
        </AuthContext.Provider>
    );
};

import React from "react";
import { useAuth } from "./useAuth";
import { useNotification } from "../utils/notifications";

export function RequireAuth({
    children,
    loginFallback,
    titleBar,
}: {
    children: React.ReactNode;
    loginFallback: React.ReactNode;
    titleBar?: React.ReactNode;
}) {
    const { user, loading } = useAuth();
    const { notify } = useNotification();
    const notified = React.useRef(false);
    const OFFLINE_NOTIFY_DELAY_MS = 500;

    if (import.meta.env.VITE_OFFLINE_MODE === "true") {
        if (!notified.current) {
            notified.current = true;
            // Use setTimeout to ensure it doesn't fire during render
            setTimeout(
                () => notify("Offline mode: Bypassed login", "info"),
                OFFLINE_NOTIFY_DELAY_MS,
            );
        }
        return <>{children}</>;
    }

    if (loading) {
        return (
            <div className="app">
                {titleBar}
                <div style={{ display: "flex", flex: 1, justifyContent: "center", alignItems: "center" }}>
                    Loading...
                </div>
            </div>
        );
    }
    
    const hasGoogleToken = !!localStorage.getItem("google_access_token");

    if (!user || !hasGoogleToken) return <>{loginFallback}</>;
    return <>{children}</>;
}

