import type { ReadonlyStopwatchContext, ClockActionEffect, ClockDisplayData } from "./types";

export interface ClockStrategy {
    getDisplayData(context: ReadonlyStopwatchContext): ClockDisplayData;
    requiresAnimationLoop(context: ReadonlyStopwatchContext): boolean;
    calculateToggle(context: ReadonlyStopwatchContext): ClockActionEffect;
    calculateTaskSelected(context: ReadonlyStopwatchContext): ClockActionEffect;
    calculateReset(context: ReadonlyStopwatchContext): ClockActionEffect;
    calculateStartBreak?(context: ReadonlyStopwatchContext): ClockActionEffect;
}

import type { ClockStrategy } from "./ClockStrategy";
import type { ReadonlyStopwatchContext, ClockDisplayData, ClockActionEffect } from "./types";
import { splitTime } from "./utils";

export class CounterClockStrategy implements ClockStrategy {
    getDisplayData({ currentMs, isPristine }: ReadonlyStopwatchContext): ClockDisplayData {
        const { m } = splitTime(currentMs);
        return {
            primaryText: m,
            showPlayIcon: isPristine,
        };
    }

    requiresAnimationLoop({ state }: ReadonlyStopwatchContext) {
        return state.runningSince !== undefined;
    }

    calculateToggle({ isPristine, activeTask, allowNoTask, state }: ReadonlyStopwatchContext): ClockActionEffect {
        if (isPristine && !activeTask && !allowNoTask) {
            return { selectorOpen: true };
        }
        if (state.runningSince) {
            return {
                shouldLogSession: true,
                newState: {
                    elapsed: state.elapsed + (Date.now() - state.runningSince),
                    runningSince: undefined,
                }
            };
        }
        return { newState: { runningSince: Date.now() } };
    }

    calculateTaskSelected({ running }: ReadonlyStopwatchContext): ClockActionEffect {
        if (!running) {
            return { selectorOpen: false, newState: { runningSince: Date.now() } };
        }
        return { selectorOpen: false };
    }

    calculateReset({ state }: ReadonlyStopwatchContext): ClockActionEffect {
        const effect: ClockActionEffect = {
            selectorOpen: false,
            newState: { elapsed: 0, runningSince: undefined }
        };
        if (state.runningSince) {
            effect.shouldLogSession = true;
        }
        return effect;
    }
}

import { MINUTES_IN_HOUR, MS_PER_SECOND } from "../../utils/constants";
import type { ClockStrategy } from "./ClockStrategy";
import type { ReadonlyStopwatchContext, ClockDisplayData, ClockActionEffect } from "./types";
import { splitTime } from "./utils";
import { PAD2 } from "../../../core/store/data";

const DEFAULT_FLOWTIME_BREAK_DIVISOR = 5;

export class FlowtimeClockStrategy implements ClockStrategy {
    getDisplayData({ currentMs, isPristine, state }: ReadonlyStopwatchContext): ClockDisplayData {
        if (state.isBreak && state.breakStartedAt) {
            const breakRemainingMs = state.breakAllowedMs - (Date.now() - state.breakStartedAt);
            const remSecs = Math.max(0, Math.ceil(breakRemainingMs / MS_PER_SECOND));
            const remM = Math.floor(remSecs / MINUTES_IN_HOUR);
            const remS = remSecs % MINUTES_IN_HOUR;
            const color = remSecs === 0 ? "var(--red)" : "var(--tag-green)";
            
            return {
                primaryText: `${PAD2(remM)}:${PAD2(remS)}`,
                secondaryText: "BREAK",
                color,
            };
        }
        
        const { m } = splitTime(currentMs);
        return {
            primaryText: m,
            showPlayIcon: isPristine,
        };
    }

    requiresAnimationLoop({ state }: ReadonlyStopwatchContext) {
        return state.runningSince !== undefined || state.isBreak;
    }

    calculateToggle({ isPristine, activeTask, allowNoTask, state }: ReadonlyStopwatchContext): ClockActionEffect {
        if (isPristine && !activeTask && !allowNoTask) {
            return { selectorOpen: true };
        }
        if (state.isBreak) return {};

        if (state.runningSince) {
            return {
                shouldLogSession: true,
                newState: {
                    elapsed: state.elapsed + (Date.now() - state.runningSince),
                    runningSince: undefined,
                }
            };
        }
        return { newState: { runningSince: Date.now() } };
    }

    calculateTaskSelected({ running, state }: ReadonlyStopwatchContext): ClockActionEffect {
        if (!running && !state.isBreak) {
            return { selectorOpen: false, newState: { runningSince: Date.now() } };
        }
        return { selectorOpen: false };
    }

    calculateReset({ state }: ReadonlyStopwatchContext): ClockActionEffect {
        const effect: ClockActionEffect = {
            selectorOpen: false,
            newState: {
                elapsed: 0,
                runningSince: undefined,
                isBreak: false,
                breakAllowedMs: 0,
                breakStartedAt: undefined,
            }
        };
        if (state.runningSince && !state.isBreak) {
            effect.shouldLogSession = true;
        }
        return effect;
    }

    calculateStartBreak({ state, settings }: ReadonlyStopwatchContext): ClockActionEffect {
        if (state.isBreak) return { newState: { isBreak: false, elapsed: 0, runningSince: Date.now() } };
        
        const effect: ClockActionEffect = {
            newState: {
                isBreak: true,
                breakAllowedMs: (state.elapsed + (state.runningSince ? Date.now() - state.runningSince : 0)) / (settings?.flowtimeBreakDivisor || DEFAULT_FLOWTIME_BREAK_DIVISOR),
                breakStartedAt: Date.now(),
                runningSince: undefined,
                elapsed: 0,
                breakSoundPlayed: false,
            }
        };
        if (state.runningSince) effect.shouldLogSession = true;
        return effect;
    }
}

import { MINUTES_IN_HOUR, MS_PER_SECOND } from "../../utils/constants";
import type { ClockStrategy } from "./ClockStrategy";
import type { ReadonlyStopwatchContext, ClockDisplayData, ClockActionEffect } from "./types";
import { PAD2 } from "../../../core/store/data";

export const POMODORO_LONG_BREAK_THRESHOLD = 35;
export const POMODORO_BREAK_THRESHOLD = 30;
export const MIN_POLL_INTERVAL_MINUTES = 5;
export const MAX_RETRIES = 3;

export class GuzeyClockStrategy implements ClockStrategy {
    getDisplayData({ state }: ReadonlyStopwatchContext): ClockDisplayData {
        const now = new Date();
        const h = now.getHours();
        const min = now.getMinutes();

        let breakState = "";
        let nextMin = 0;
        let color = "var(--fg)";
        const isLongBreak = h % MAX_RETRIES === 0;

        if (isLongBreak && min < POMODORO_LONG_BREAK_THRESHOLD) {
            breakState = "LONG_BREAK";
            nextMin = POMODORO_LONG_BREAK_THRESHOLD;
            color = "var(--tag-green)";
        } else {
            if (min >= 0 && min < MIN_POLL_INTERVAL_MINUTES) {
                breakState = "BREAK";
                nextMin = MIN_POLL_INTERVAL_MINUTES;
                color = "var(--tag-green)";
            } else if (min >= MIN_POLL_INTERVAL_MINUTES && min < POMODORO_BREAK_THRESHOLD) {
                breakState = "WORK";
                nextMin = POMODORO_BREAK_THRESHOLD;
                color = "var(--fg)";
            } else if (min >= POMODORO_BREAK_THRESHOLD && min < POMODORO_LONG_BREAK_THRESHOLD) {
                breakState = "BREAK";
                nextMin = POMODORO_LONG_BREAK_THRESHOLD;
                color = "var(--tag-green)";
            } else {
                breakState = "WORK";
                nextMin = MINUTES_IN_HOUR;
                color = "var(--fg)";
            }
        }

        const target = new Date(now);
        target.setSeconds(0);
        target.setMilliseconds(0);
        if (nextMin === MINUTES_IN_HOUR) {
            target.setMinutes(0);
            target.setHours(target.getHours() + 1);
        } else {
            target.setMinutes(nextMin);
        }

        const remainingMs = target.getTime() - now.getTime();
        const remS = Math.floor(remainingMs / MS_PER_SECOND);
        const remM = Math.floor(remS / MINUTES_IN_HOUR);
        const finalS = remS % MINUTES_IN_HOUR;

        const isBreakNow = breakState === "BREAK" || breakState === "LONG_BREAK";
        const isPaused = !state.runningSince;

        return {
            primaryText: `${PAD2(remM)}:${PAD2(finalS)}`,
            secondaryText: isPaused ? "TRACKING PAUSED" : breakState,
            color: isPaused ? "var(--fg-dim)" : color,
            isBreak: isBreakNow,
        };
    }

    requiresAnimationLoop() {
        return true;
    }

    calculateToggle({ state }: ReadonlyStopwatchContext): ClockActionEffect {
        if (state.runningSince) {
            return {
                shouldLogSession: true,
                newState: { runningSince: undefined }
            };
        }
        return { newState: { runningSince: Date.now() } };
    }

    calculateTaskSelected(): ClockActionEffect {
        return { selectorOpen: false, newState: { runningSince: Date.now() } };
    }

    calculateReset({ state }: ReadonlyStopwatchContext): ClockActionEffect {
        const effect: ClockActionEffect = {
            selectorOpen: false,
            newState: { runningSince: undefined }
        };
        if (state.runningSince) {
            effect.shouldLogSession = true;
        }
        return effect;
    }
}

