import type { AppEvent, AppTask } from "./models";
import { modernizeColor } from "../utils/colors";

export type HydratedEvent = AppEvent & {
    task?: AppTask;
    color?: string;
    /** The display name of the calendar this event belongs to. Computed at hydration time from
     *  remoteCollectionId; never stored on the event itself. */
    category?: string;
    /** Set by the expander; true when this is a virtual instance generated from an rrule (never stored). */
    isInstance?: boolean;
    /** Set by the expander; the local `id` of the master event this instance was generated from. */
    baseEventId?: string;
};

type Calendar = { id: string; summary: string; backgroundColor?: string; foregroundColor?: string; primary?: boolean };

function resolveEventCalendar(ev: AppEvent, calendars: Calendar[]): Calendar | undefined {
    const calId = ev.remoteCollectionId === "primary"
        ? (calendars.find((c) => c.primary)?.id ?? "primary")
        : ev.remoteCollectionId;

    return calId
        ? (calendars.find((c) => c.id === calId) ?? calendars.find((c) => c.primary) ?? calendars[0])
        : (calendars.find((c) => c.primary) ?? calendars[0]);
}

export function isEventAllDay(event: { startTime: string; endTime: string }): boolean {
    const YMD_LENGTH = 10;
    return event.startTime.length === YMD_LENGTH && event.endTime.length === YMD_LENGTH && !event.startTime.includes('T');
}

export function hydrateEvents(
    events: AppEvent[],
    tasks: AppTask[],
    calendars: Calendar[] = [],
): HydratedEvent[] {
    return events.map((ev) => {
        const cal = resolveEventCalendar(ev, calendars);
        const color = cal?.backgroundColor ? modernizeColor(cal.backgroundColor) : undefined;
        const category = cal?.summary;
        if (ev.taskId) {
            const task = tasks.find((t) => t.id === ev.taskId);
            const result: HydratedEvent = { ...ev, title: task ? task.title : "Unknown Task" };
            if (task !== undefined) result.task = task;
            if (color !== undefined) result.color = color;
            if (category !== undefined) result.category = category;
            return result;
        }
        const result: HydratedEvent = { ...ev, title: ev.title || "" };
        if (color !== undefined) result.color = color;
        if (category !== undefined) result.category = category;
        return result;
    });
}

import { describe, it, expect } from "vitest";
import { computeFilterDefaults } from "./filters";

describe("computeFilterDefaults", () => {
    it("returns empty defaults for no filters", () => {
        expect(computeFilterDefaults([])).toEqual({});
    });

    it('infers status from "is" filter', () => {
        const filters = [{ column: "status", operator: "is", value: "done" }];
        expect(computeFilterDefaults(filters)).toEqual({ status: "done" });
    });

    it('infers priority from "is" filter', () => {
        const filters = [{ column: "priority", operator: "is", value: 3 }];
        expect(computeFilterDefaults(filters)).toEqual({ priority: 3 });
    });

    it('picks fallback status when "is not" filter excludes todo', () => {
        const filters = [
            { column: "status", operator: "is not", value: "todo" },
        ];
        expect(computeFilterDefaults(filters)).toEqual({ status: "next-up" }); // Because 'next-up' is next in fallback list
    });

    it('picks fallback status when multiple "is not" filters exclude top choices', () => {
        const filters = [
            { column: "status", operator: "is not", value: "todo" },
            { column: "status", operator: "is not", value: "next-up" },
            { column: "status", operator: "is not", value: "doing" },
        ];
        expect(computeFilterDefaults(filters)).toEqual({ status: "done" });
    });

    it('picks fallback priority when "is not" excludes 1', () => {
        const filters = [{ column: "priority", operator: "is not", value: 1 }];
        expect(computeFilterDefaults(filters)).toEqual({ priority: 2 });
    });

    it('does not apply conflicting "is" requirements', () => {
        const filters = [
            { column: "status", operator: "is", value: "todo" },
            { column: "status", operator: "is", value: "done" },
        ];
        expect(computeFilterDefaults(filters)).toEqual({});
    });

    it("does not apply value if it is both required and excluded", () => {
        const filters = [
            { column: "status", operator: "is", value: "done" },
            { column: "status", operator: "is not", value: "done" },
        ];
        expect(computeFilterDefaults(filters)).toEqual({});
    });

    it("adds tags correctly and ignores excluded tags", () => {
        const filters = [
            { column: "tag", operator: "is", value: "bug" },
            { column: "tag", operator: "is", value: "feature" },
            { column: "tag", operator: "is not", value: "bug" },
            { column: "tag", operator: "is not", value: "urgent" },
        ];
        // "bug" is excluded, so only "feature" should be included
        expect(computeFilterDefaults(filters)).toEqual({ tags: ["feature"] });
    });

    it("handles array values for 'is' status filtering correctly", () => {
        const filters = [
            { column: "status", operator: "is", value: ["todo", "next-up"] },
        ];
        // When multiple statuses are requested, computeFilterDefaults doesn't apply a single status
        // since a single task can't have multiple statuses simultaneously.
        expect(computeFilterDefaults(filters)).toEqual({});
    });

    it("handles array values for 'is not' status filtering", () => {
        const filters = [
            { column: "status", operator: "is not", value: ["todo", "next-up", "doing"] },
        ];
        // Excludes everything before "done"
        expect(computeFilterDefaults(filters)).toEqual({ status: "done" });
    });

    it("handles array values for tag filtering", () => {
        const filters = [
            { column: "tag", operator: "is", value: ["bug", "urgent"] },
        ];
        // "bug" and "urgent" are both added to defaults
        expect(computeFilterDefaults(filters)).toEqual({ tags: ["bug", "urgent"] });
    });

    it("handles array values for tag exclusion", () => {
        const filters = [
            { column: "tag", operator: "is", value: ["bug", "feature", "ui"] },
            { column: "tag", operator: "is not", value: ["bug", "ui"] },
        ];
        // "bug" and "ui" are excluded, leaving only "feature"
        expect(computeFilterDefaults(filters)).toEqual({ tags: ["feature"] });
    });

    it("handles mixed single and array values for exclusion", () => {
        const filters = [
            { column: "status", operator: "is not", value: ["todo"] },
            { column: "status", operator: "is not", value: "next-up" },
        ];
        // "todo" and "next-up" are excluded, so fallback is "doing"
        expect(computeFilterDefaults(filters)).toEqual({ status: "doing" });
    });

    it("ignores empty array values", () => {
        const filters = [
            { column: "status", operator: "is", value: [] },
            { column: "priority", operator: "is not", value: [] },
        ];
        expect(computeFilterDefaults(filters)).toEqual({});
    });
});

import type { HydratedEvent } from "./events";
import type { AppFilter } from "./models";

export const DRAG_THRESHOLD_PX = 4;
export const MAX_RETRIES = 3;


function processFilterItem(f: AppFilter, req: Record<string, Set<string | number>>, excl: Record<string, Set<string | number>>) {
    if (!f.column) return;
    if (f.value === undefined || f.value === null || f.value === "") return;
    
    const values = Array.isArray(f.value) ? f.value : [f.value];
    if (values.length === 0) return;
    
    if (f.operator === "is not") {
        const colSet = excl[f.column] || new Set();
        excl[f.column] = colSet;
        for (const v of values) colSet.add(v);
    } else {
        const colSet = req[f.column] || new Set();
        req[f.column] = colSet;
        for (const v of values) colSet.add(v);
    }
}

function processFilters(filters: AppFilter[]) {
    const req: Record<string, Set<string | number>> = {};
    const excl: Record<string, Set<string | number>> = {};
    for (const f of filters) {
        processFilterItem(f, req, excl);
    }
    return { req, excl };
}

const FALLBACKS: Record<string, (string | number)[]> = {
    status: ["todo", "next-up", "doing", "done"],
    priority: [1, 2, MAX_RETRIES, DRAG_THRESHOLD_PX, 0],
};

function processSingleValueCol(
    col: string,
    reqCol: Set<string | number> | undefined,
    exclCol: Set<string | number> | undefined,
    defaults: Record<string, unknown>
) {
    if (reqCol?.size === 1) {
        const val = Array.from(reqCol)[0];
        if (val !== undefined && (!exclCol || !exclCol.has(val))) {
            defaults[col] = val;
        }
        return;
    }
    
    const fallbacks = FALLBACKS[col];
    if (exclCol && fallbacks) {
        for (const fallback of fallbacks) {
            if (!exclCol.has(fallback)) {
                defaults[col] = fallback;
                break;
            }
        }
    }
}

function processSingleValueCols(
    req: Record<string, Set<string | number>>,
    excl: Record<string, Set<string | number>>,
    defaults: Record<string, unknown>
) {
    const singleValueCols = ["status", "priority"];
    for (const col of singleValueCols) {
        processSingleValueCol(col, req[col], excl[col], defaults);
    }
}

export function computeFilterDefaults(filters: AppFilter[] = []) {
    const { req, excl } = processFilters(filters);
    const defaults: Record<string, unknown> = {};

    processSingleValueCols(req, excl, defaults);

    if (req["tag"]) {
        const validTags = Array.from(req["tag"]).filter(
            (t) => !excl["tag"] || !excl["tag"].has(t),
        );
        if (validTags.length > 0) {
            defaults["tags"] = validTags;
        }
    }

    return defaults;
}

export function filterEvents(
    evs: HydratedEvent[],
    filter?: AppFilter[]
): HydratedEvent[] {
    if (!filter || !Array.isArray(filter) || filter.length === 0) return evs;
    
    let filtered = evs;
    for (const f of filter) {
        if (!f.column || (!f.value && f.value !== 0)) continue;
        filtered = filtered.filter((e) => {
            let match = false;
            const values = Array.isArray(f.value) ? f.value : [f.value];
            if (values.length === 0) return true;

            if (f.column === "type") {
                match = values.includes(e.type);
            } else if (f.column === "tag") {
                const taskTags = e.task?.tags ?? [];
                const allTags = new Set(taskTags.map((t) =>
                    typeof t === "string" ? t.toLowerCase() : "",
                ));
                match = values.some(v => allTags.has(String(v).toLowerCase()));
            } else if (f.column === "taskStatus") {
                match = values.some(v => {
                    if (v === "none") return !e.task;
                    if (v === "done") return e.task?.status === "done";
                    if (v === "todo") return e.task?.status !== "done";
                    return false;
                });
            } else if (f.column === "category") {
                match = values.includes(e.category || "");
            }
            return f.operator === "is not" ? !match : match;
        });
    }
    return filtered;
}

export function sortEvents(evs: HydratedEvent[], sort?: string): HydratedEvent[] {
    if (!sort) return evs;
    const sorted = [...evs];
    sorted.sort((a, b) => {
        if (sort === "taskStatus") {
            const aDone = (a.task?.status === "done") ? 1 : 0;
            const bDone = (b.task?.status === "done") ? 1 : 0;
            if (aDone !== bDone) return aDone - bDone;
        }
        return (a.startTime || "").localeCompare(b.startTime || "");
    });
    return sorted;
}

export type YmdString = string; // Format: YYYY-MM-DD

export function isYmdString(s: unknown): s is YmdString {
    return typeof s === "string" && /^\d{4}-\d{2}-\d{2}$/.test(s);
}

export function isAppTaskStatus(s: unknown): s is AppTask["status"] {
    return typeof s === "string" && ["todo", "next-up", "doing", "done"].includes(s);
}

export interface AppTask {
    readonly id: string;
    readonly title: string;
    readonly status?: "todo" | "next-up" | "doing" | "done" | undefined;
    readonly priority?: number | undefined;
    readonly tags?: readonly string[] | undefined;
    readonly subtasks?: readonly { readonly done: boolean; readonly [key: string]: unknown }[] | undefined;
    readonly parent_task?: string | undefined;
    readonly dependencies?: readonly string[] | undefined;
    readonly est?: number | undefined;
    readonly added?: string | undefined;
    readonly canvasX?: number | undefined;
    readonly canvasY?: number | undefined;
    readonly onCanvas?: boolean | undefined;
    readonly remoteId?: string | undefined;
    readonly notes?: string | undefined;
    readonly tabs?: string | undefined;
    readonly due?: YmdString | undefined;
    readonly _deleted?: boolean | undefined;
    readonly updatedAt?: number | undefined;
    /** ETag fingerprint from Google API for optimistic concurrency control. */
    readonly etag?: string | undefined;
    readonly [key: string]: unknown;
}

/** Resolves to the union of keys whose type includes `undefined` (i.e. optional fields). */
export type OptionalKeysOf<T> = {
    [K in keyof T]-?: undefined extends T[K] ? K : never;
}[keyof T];

/**
 * Returns a fluent builder for producing an updated copy of `item`.
 * Use `.set(key, value)` to update a field and `.clear(key)` to remove an
 * optional field (key deleted from the object entirely — not set to `undefined`).
 * Call `.done()` to retrieve the final value.
 *
 * Works for any object with a string `id`. Generic — no AppTask-specific logic here.
 */
export function editing<T extends { readonly id: string }>(item: T): {
    set<K extends keyof T>(key: K, value: T[K]): ReturnType<typeof editing<T>>;
    clear(key: OptionalKeysOf<T>): ReturnType<typeof editing<T>>;
    done(): T;
} {
    return {
        set<K extends keyof T>(key: K, value: T[K]) {
            return editing<T>({ ...item, [key]: value });
        },
        clear(key: OptionalKeysOf<T>) {
            const { [key]: _dropped, ...rest } = item;
            // Safe: key is constrained to OptionalKeysOf<T>, meaning the cleared key
            // is already optional in T. The remaining spread therefore still satisfies T.
            // oxlint-disable-next-line consistent-type-assertions, no-unsafe-type-assertion
            return editing<T>(rest as T);
        },
        done: () => item,
    };
}

export interface AppFilter {
    readonly id?: string;
    readonly column: string;
    readonly operator: string;
    readonly value: string | number | readonly (string | number)[];
}

export interface AppEvent {
    // --- Identity ---
    readonly id: string;
    /** Stable Google Calendar event ID; absent until first sync. */
    readonly remoteId?: string | undefined;
    /** Which Google Calendar this belongs to (e.g. `"primary"` or a calendar ID). */
    readonly remoteCollectionId?: string | undefined;
    /** Links this event to an AppTask, turning it into a time-block for that task. */
    readonly taskId?: string | undefined;

    // --- Content ---
    readonly title: string;
    readonly description?: string | undefined;

    // --- Timing ---
    /** Floating local datetime `"YYYY-MM-DDThh:mm:ss"`, or date-only `"YYYY-MM-DD"` for all-day events. */
    readonly startTime: string;
    /** Same format as startTime. All-day is detected when both fields are 10-char date-only strings. */
    readonly endTime: string;
    readonly type: 'busy' | 'info' | 'log';

    // --- Recurrence (base event) ---
    /** RFC 5545 RRULE string defining the recurrence pattern. Only present on master events. */
    readonly rrule?: string | undefined;
    /** Slots to skip from the recurrence, stored in compact `YYYYMMDDTHHMMSS` format. */
    readonly exdates?: readonly string[] | undefined;

    // --- Recurrence (stored exception) ---
    /**
     * Local `id` of the master event this exception overrides.
     * Translated to the master's `remoteId` when pushing to GCal.
     */
    readonly recurringEventId?: string | undefined;
    /**
     * The generated slot start-time this exception replaces (`"YYYY-MM-DDThh:mm:ss"`).
     * Used by the expander to match and suppress the original instance.
     */
    readonly originalStartTime?: string | undefined;
    /** True when the exception was cancelled (deleted) rather than rescheduled. */
    readonly cancelled?: boolean | undefined;

    // --- Sync metadata ---
    /** Unix timestamp (ms) of last local write; drives push decisions in the sync engine. */
    readonly updatedAt?: number | undefined;
    /** Soft-delete flag; kept until the deletion is confirmed pushed to GCal. */
    readonly _deleted?: boolean | undefined;
    /** ETag fingerprint from Google API for optimistic concurrency control. */
    readonly etag?: string | undefined;

    readonly [key: string]: unknown;
}

export function toEventType(raw: string | undefined, fallback: AppEvent['type']): AppEvent['type'] {
    return (raw === "info" || raw === "busy" || raw === "log") ? raw : fallback;
}

export interface AppNote {
    readonly id: string;
    readonly title: string;
    readonly vault: string;
    readonly path: string;
}

