import { RRule } from "rrule";
import type { AppEvent } from "./models";
import type { HydratedEvent } from "./events";

export type RecurringMode = "instance" | "following" | "all";

export function expandEventsForView(
    baseEvents: AppEvent[],
    viewStartDate: Date,
    viewEndDate: Date,
): HydratedEvent[] {
    const flattenedInstances: HydratedEvent[] = [];

    baseEvents.forEach((event) => {
        if (!event.rrule) {
            flattenedInstances.push(event);
            return;
        }

        try {
            let ruleStr = event.rrule;
            if (!ruleStr.includes("DTSTART")) {
                const dtstart = event.startTime.replace(/[-:]/g, "");
                ruleStr = `DTSTART:${dtstart}\n${ruleStr.startsWith("RRULE:") ? ruleStr : "RRULE:" + ruleStr}`;
            }

            const rule = RRule.fromString(ruleStr);
            const viewStartUTC = new Date(Date.UTC(viewStartDate.getFullYear(), viewStartDate.getMonth(), viewStartDate.getDate()));
            const viewEndUTC = new Date(Date.UTC(viewEndDate.getFullYear(), viewEndDate.getMonth(), viewEndDate.getDate()));
            
            const generatedDates = rule.between(viewStartUTC, viewEndUTC, true);

            const baseStartDt = new Date(event.startTime);
            const baseEndDt = new Date(event.endTime);
            const durationMs = baseEndDt.getTime() - baseStartDt.getTime();

            generatedDates.forEach((date) => {
                const y = date.getUTCFullYear();
                const m = (date.getUTCMonth() + 1).toString().padStart(2, "0");
                const d = date.getUTCDate().toString().padStart(2, "0");
                const h = date.getUTCHours().toString().padStart(2, "0");
                const min = date.getUTCMinutes().toString().padStart(2, "0");
                const sec = date.getUTCSeconds().toString().padStart(2, "0");
                const instanceStartTimeStr = `${y}-${m}-${d}T${h}:${min}:${sec}`;

                const isExdate = event.exdates?.some((exdate) => {
                    // Google's exdate format is typically "YYYYMMDDTHHMMSSZ" or "YYYYMMDDTHHMMSS"
                    // Our instanceStartTimeStr is "YYYY-MM-DDTHH:MM:SS"
                    const compactInstanceStr = instanceStartTimeStr.replace(/[-:]/g, "");
                    return exdate.startsWith(compactInstanceStr);
                });

                if (isExdate) return;

                const exceptionOverride = baseEvents.find(
                    (e) =>
                        e.recurringEventId === event.id &&
                        e.originalStartTime === instanceStartTimeStr,
                );

                if (exceptionOverride) {
                    if (!exceptionOverride.cancelled) {
                        flattenedInstances.push(exceptionOverride);
                    }
                } else {
                    // newStartDt in local time so we can add duration and output correctly
                    const newStartDt = new Date(`${y}-${m}-${d}T${h}:${min}:${sec}`);
                    const newEndDt = new Date(newStartDt.getTime() + durationMs);

                    const ey = newEndDt.getFullYear();
                    const em = (newEndDt.getMonth() + 1).toString().padStart(2, "0");
                    const ed = newEndDt.getDate().toString().padStart(2, "0");
                    const eh = newEndDt.getHours().toString().padStart(2, "0");
                    const emin = newEndDt.getMinutes().toString().padStart(2, "0");
                    const esec = newEndDt.getSeconds().toString().padStart(2, "0");
                    const instanceEndTimeStr = `${ey}-${em}-${ed}T${eh}:${emin}:${esec}`;

                    flattenedInstances.push({
                        ...event,
                        id: `${event.id}_${date.getTime()}`,
                        startTime: instanceStartTimeStr,
                        endTime: instanceEndTimeStr,
                        isInstance: true,
                        baseEventId: event.id,
                    });
                }
            });
        } catch (e) {
            console.error(
                "Failed to parse RRULE for event",
                event.title || event.id,
                e,
            );
            flattenedInstances.push(event);
        }
    });

    return flattenedInstances;
}

function applyInstanceUpdate(events: AppEvent[], baseEvent: AppEvent, instanceEvent: HydratedEvent, updates: Partial<AppEvent>) {
    if (instanceEvent.recurringEventId) {
        return events.map(e => e.id === instanceEvent.id ? { ...e, ...updates } : e);
    }
    const compactStartTime = instanceEvent.startTime.replace(/[-:]/g, "");
    const newExdates = [...(baseEvent.exdates || []), compactStartTime];
    const overrideEvent: AppEvent = {
        ...baseEvent, ...updates,
        id: `e${Date.now()}_${crypto.randomUUID()}`,
        recurringEventId: baseEvent.id,
        originalStartTime: instanceEvent.startTime,
        rrule: undefined, exdates: undefined,
    };
    return [
        ...events.map((e) => (e.id === baseEvent.id ? { ...e, exdates: newExdates } : e)),
        overrideEvent
    ];
}

export function applyRecurringUpdate(
    events: AppEvent[],
    instanceEvent: HydratedEvent,
    mode: RecurringMode,
    updates: Partial<AppEvent>
): AppEvent[] {
    const baseId = instanceEvent.baseEventId || instanceEvent.id;
    const baseEvent = events.find((e) => e.id === baseId);
    if (!baseEvent) return events;

    if (!baseEvent.rrule && !baseEvent.recurringEventId) {
        return events.map((e) => (e.id === baseId ? { ...e, ...updates } : e));
    }

    if (mode === "instance") {
        return applyInstanceUpdate(events, baseEvent, instanceEvent, updates);
    }
    
    return events.map((e) => (e.id === baseId ? { ...e, ...updates } : e));
}

function applyInstanceDelete(events: AppEvent[], baseEvent: AppEvent, instanceEvent: HydratedEvent) {
    if (instanceEvent.recurringEventId) {
        return events.filter(e => e.id !== instanceEvent.id);
    }
    const compactStartTime = instanceEvent.startTime.replace(/[-:]/g, "");
    const newExdates = [...(baseEvent.exdates || []), compactStartTime];
    return events.map((e) => (e.id === baseEvent.id ? { ...e, exdates: newExdates } : e));
}

export function applyRecurringDelete(
    events: AppEvent[],
    instanceEvent: HydratedEvent,
    mode: RecurringMode
): AppEvent[] {
    const baseId = instanceEvent.baseEventId || instanceEvent.id;
    const baseEvent = events.find((e) => e.id === baseId);
    if (!baseEvent) return events;

    if (!baseEvent.rrule && !baseEvent.recurringEventId) {
        return events.filter((e) => e.id !== baseId);
    }

    if (mode === "instance") {
        return applyInstanceDelete(events, baseEvent, instanceEvent);
    }
    
    return events.filter((e) => e.id !== baseId && e.recurringEventId !== baseId);
}

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { fetchWithTimeout } from "./api";

describe("api.ts", () => {
    describe("fetchWithTimeout", () => {
        beforeEach(() => {
            vi.useFakeTimers();
        });

        afterEach(() => {
            vi.useRealTimers();
        });

        it("should abort fetch if timeout is reached", async () => {
            vi.stubGlobal(
                "fetch",
                vi.fn<(...args: never[]) => unknown>((_url: unknown, init: RequestInit) =>
                    new Promise((_resolve, reject) => {
                        if (init?.signal) {
                            init.signal.addEventListener("abort", () => {
                                const err = new Error("AbortError");
                                err.name = "AbortError";
                                reject(err);
                            });
                        }
                    })
                )
            );

            const resultPromise = fetchWithTimeout("https://example.com", {
                timeout: 1000,
            });

            // Fast forward timers and flush microtasks
            await vi.advanceTimersByTimeAsync(1500);

            const result = await resultPromise;
            expect(result.isErr()).toBe(true);
            expect(result._unsafeUnwrapErr()).toBeInstanceOf(Error);
            expect(result._unsafeUnwrapErr().message).toBe("Request timed out");
            expect(global.fetch).toHaveBeenCalledOnce();
        });
    });
});

import { ResultAsync } from "neverthrow";

export const API_TIMEOUT_MS = 15000;

export function fetchWithTimeout(
    resource: RequestInfo | URL,
    options: RequestInit & { timeout?: number } = {},
): ResultAsync<Response, Error> {
    const { timeout = API_TIMEOUT_MS, ...rest } = options;
    const controller = new AbortController();
    const id = setTimeout(() => controller.abort(), timeout);
    
    return ResultAsync.fromPromise(
        fetch(resource, {
            ...rest,
            signal: controller.signal,
        }).then((res) => {
            clearTimeout(id);
            return res;
        }),
        (error: unknown) => {
            clearTimeout(id);
            if (error instanceof Error && error.name === "AbortError") {
                return new Error("Request timed out", { cause: error });
            }
            return error instanceof Error ? error : new Error(String(error));
        }
    );
}

export const api = {
    clearAllData: async () => {
        const keysToRemove: string[] = [];
        for (let i = 0; i < localStorage.length; i++) {
            const key = localStorage.key(i);
            if (key?.startsWith("taskroot_")) {
                keysToRemove.push(key);
            }
        }
        keysToRemove.forEach((k) => localStorage.removeItem(k));
    }
};

import { editing } from "../domain/models";
import type { OptionalKeysOf } from "../domain/models";
import { Repository } from "./repository";
import type { SerializationError, QuotaExceededError } from "./errors";
import type { Result } from "neverthrow";

type TaskTransform<Item> = (item: Item) => Item;

interface EditorBuilder<Item extends { readonly id: string }> {
    set<K extends keyof Item>(key: K, value: Item[K]): EditorBuilder<Item>;
    clear(key: OptionalKeysOf<Item>): EditorBuilder<Item>;
    commit(): Result<Item[], SerializationError | QuotaExceededError | Error>;
}

function buildEditor<Item extends { readonly id: string }>(
    repo: ArrayRepository<Item>,
    id: string,
    target: Item,
): EditorBuilder<Item> {
    const builder = editing(target);

    return {
        set<K extends keyof Item>(key: K, value: Item[K]) {
            return buildEditor(repo, id, builder.set(key, value).done());
        },
        clear(key: OptionalKeysOf<Item>) {
            return buildEditor(repo, id, builder.clear(key).done());
        },
        commit() {
            const updated = builder.done();
            return repo.set(items => items.map(item => item.id === id ? updated : item));
        },
    };
}

function noOpEditor<Item extends { readonly id: string }>(
    repo: ArrayRepository<Item>,
    snapshot: Item[],
): EditorBuilder<Item> {
    return {
        set<K extends keyof Item>(_key: K, _value: Item[K]) { return this; },
        clear(_key: OptionalKeysOf<Item>) { return this; },
        commit() { return repo.set(snapshot); },
    };
}

export class ArrayRepository<Item extends { readonly id: string }>
    extends Repository<Item[]>
{
    edit(id: string): EditorBuilder<Item> {
        const allRes = this.get();
        const all = allRes.unwrapOr(this.initial);
        const target = all.find(item => item.id === id);
        if (!target) return noOpEditor(this, all);
        return buildEditor(this, id, target);
    }

    updateOne(id: string, transform: TaskTransform<Item>): Result<Item[], SerializationError | QuotaExceededError | Error> {
        return this.set(items => items.map(item => item.id === id ? transform(item) : item));
    }
}

