export function GlobalSyncLoading({ syncMessage, titleBar }: { syncMessage: string | null; titleBar?: React.ReactNode }) {
    if (window.location.search.includes("minitracker=true")) {
        return <></>;
    }
    return (
        <div className="app">
            {titleBar}
            <div style={{ display: "flex", flex: 1, justifyContent: "center", alignItems: "center", flexDirection: "column", background: "var(--bg)", color: "var(--fg)", fontFamily: "var(--sans)" }}>
            <div
                style={{
                    width: "40px",
                    height: "40px",
                    border: "3px solid var(--border)",
                    borderTopColor: "var(--accent)",
                    borderRadius: "50%",
                    animation: "spin 1s linear infinite",
                }}
            />
            <div
                style={{
                    marginTop: "16px",
                    color: "var(--fg-dim)",
                    fontSize: "0.9rem",
                }}
            >
                {syncMessage || "Syncing data..."}
            </div>
            <style>{`
          @keyframes spin {
            to { transform: rotate(360deg); }
          }
        `}</style>
            </div>
        </div>
    );
}

export function GlobalSync({ children, titleBar }: { children: React.ReactNode; titleBar?: React.ReactNode }) {
    const [, , tasksLoaded] = useTasks();
    const [, , eventsLoaded] = useEvents();
    const [settings] = useSettings();
    const initialSyncDone = React.useSyncExternalStore(
        (listener) => syncState.subscribe(listener),
        () => syncState.initialSyncComplete
    );
    const syncMessage = React.useSyncExternalStore(
        (listener) => syncState.subscribe(listener),
        () => syncState.getUiMessage()
    );
    const { notify } = useNotification();

    React.useEffect(() => {
        purgeOrphanedData(notify);
        poller.start();
    }, [settings, notify]);

    React.useEffect(() => {
        const checkNotifications = () => {
            if (syncState.error) {
                notify(`Sync error: ${syncState.error}`, "error");
                syncState.error = undefined;
            }
            if (syncState.info) {
                notify(syncState.info, "info");
                syncState.info = undefined;
            }
        };
        checkNotifications();
        const unsub = syncState.subscribe(checkNotifications);
        return unsub;
    }, [notify]);

    if (!tasksLoaded || !eventsLoaded || !initialSyncDone) {
        return <GlobalSyncLoading syncMessage={syncMessage} titleBar={titleBar} />;
    }

    return <>{children}</>;
}

type Listener = () => void;

class SyncStateStore {
    private _isPolling = false;
    private _isPushing = false;
    private _error: string | undefined = undefined;
    private _info: string | undefined = undefined;
    private _initialSyncComplete = false;
    private _nextSyncTime = 0;

    private _isOffline = false;

    private listeners = new Set<Listener>();

    subscribe(listener: Listener) {
        this.listeners.add(listener);
        return () => {
            this.listeners.delete(listener);
        };
    }

    private notify() {
        this.listeners.forEach((l) => l());
    }

    get isPolling() { return this._isPolling; }
    set isPolling(val: boolean) {
        if (this._isPolling !== val) {
            this._isPolling = val;
            this.notify();
        }
    }

    get isPushing() { return this._isPushing; }
    set isPushing(val: boolean) {
        if (this._isPushing !== val) {
            this._isPushing = val;
            this.notify();
        }
    }

    get isOffline() { return this._isOffline; }
    set isOffline(val: boolean) {
        if (this._isOffline !== val) {
            this._isOffline = val;
            this.notify();
        }
    }

    get error() { return this._error; }
    set error(val: string | undefined) {
        if (this._error !== val) {
            this._error = val;
            if (!val) this.isOffline = false;
            this.notify();
        }
    }

    checkConnectivity() {
        fetch('https://www.googleapis.com/robots.txt', { mode: 'no-cors', cache: 'no-store' })
            .then(() => { this.isOffline = false; return undefined; })
            .catch(() => { this.isOffline = true; return undefined; });
    }

    get info() { return this._info; }
    set info(val: string | undefined) {
        if (this._info !== val) {
            this._info = val;
            this.notify();
        }
    }

    get initialSyncComplete() { return this._initialSyncComplete; }
    set initialSyncComplete(val: boolean) {
        if (this._initialSyncComplete !== val) {
            this._initialSyncComplete = val;
            this.notify();
        }
    }

    get nextSyncTime() { return this._nextSyncTime; }
    set nextSyncTime(val: number) {
        if (this._nextSyncTime !== val) {
            this._nextSyncTime = val;
            this.notify();
        }
    }

    getUiMessage(): string {
        if (this._error) return "Sync failed";
        if (this._isPolling && this._isPushing) return "Syncing...";
        if (this._isPolling) return "Syncing...";
        if (this._isPushing) return "Saving...";
        return "Sync complete";
    }

    getUiStatus(): string {
        if (this._error) {
            return this._isOffline ? "signal_wifi_off" : "sync_problem";
        }
        if (this._isPolling || this._isPushing) return "syncing";
        return "sync";
    }
}

