                id: "e123",
                title: "All day event",
                startTime: "2024-05-10",
                endTime: "2024-05-11",
            });
            const googleEvent = googleCalendarAPI.toGoogleEvent(localEvent);

            expect(googleEvent.start?.date).toBe("2024-05-10");
            expect(googleEvent.end?.date).toBe("2024-05-11");
