// We suppress max-lines because this file was already over the limit before our changes, and we are just migrating it to neverthrow.
import { HTTP_GONE, HTTP_PRECONDITION_FAILED } from "../../utils/constants";
import { fetchWithRateLimitAndAuth } from "../google-api-utils";
import { toFloatingIso } from "../../utils/date-utils";
import { ConflictError, ApiError, toSyncError, type SyncError } from "../errors";
import type { AppEvent } from "../../domain/models";
import { toEventType } from "../../domain/models";
import { isEventAllDay } from "../../domain/events";
import type { IAuthManager } from "../auth/types";
import type { ICalendarAPI } from "./types";
import { ResultAsync, okAsync } from "neverthrow";
/// <reference types="gapi.client.calendar" />


export class GoogleCalendarAPI implements ICalendarAPI {
    private authManager: IAuthManager;
    constructor(authManager: IAuthManager) {
        this.authManager = authManager;
    }

    private fetchWithAuth(endpoint: string, options: RequestInit = {}) {
        return fetchWithRateLimitAndAuth(`https://www.googleapis.com/calendar/v3/${endpoint}`, this.authManager, options);
    }

    fetchEvents(timeMin: string, timeMax: string, calendarId = "primary"): ResultAsync<gapi.client.calendar.Event[] | undefined, SyncError> {
        return this.fetchWithAuth(`calendars/${encodeURIComponent(calendarId)}/events?timeMin=${timeMin}&timeMax=${timeMax}&singleEvents=false&maxResults=2500`)
            .andThen(res => 
                ResultAsync.fromPromise(
                    (async () => {
                        if (!res.ok) { console.warn(`Failed to fetch events for calendar ${calendarId}`); return undefined; }
                        const data: gapi.client.calendar.Events = await res.json();
                        return data.items || [];
                    })(),
                    e => toSyncError(e)
                )
            );
    }

    private mapCalendarItem(c: gapi.client.calendar.CalendarListEntry) {
        const hasAccessRole = c.accessRole !== undefined;
        const hasBackgroundColor = c.backgroundColor !== undefined;
        const hasForegroundColor = c.foregroundColor !== undefined;
        const hasPrimary = c.primary !== undefined;
        return {
            id: c.id ?? "",
            summary: c.summaryOverride || (c.summary ?? ""),
            ...(hasAccessRole ? { accessRole: c.accessRole } : {}),
            ...(hasBackgroundColor ? { backgroundColor: c.backgroundColor } : {}),
            ...(hasForegroundColor ? { foregroundColor: c.foregroundColor } : {}),
            ...(hasPrimary ? { primary: c.primary } : {})
        };
    }

    fetchCalendars(): ResultAsync<{id: string, summary: string, accessRole?: string, backgroundColor?: string, foregroundColor?: string, primary?: boolean}[], SyncError> {
        const def = [{ id: "primary", summary: "Primary Calendar", accessRole: "owner", primary: true }];
        if (!this.authManager.getToken()) return okAsync(def);
        return this.fetchWithAuth("users/me/calendarList")
            .andThen(res => 
                ResultAsync.fromPromise(
                    (async () => {
                        if (!res.ok) { console.warn(`Failed to fetch calendars`); return def; }
                        const data: gapi.client.calendar.CalendarList = await res.json();
                        const items = data.items || [];
                        const result: {id: string, summary: string, accessRole?: string, backgroundColor?: string, foregroundColor?: string, primary?: boolean}[] = [];
                        for (const c of items) {
                            const hasIdAndSummary = c.id && c.summary;
                            if (hasIdAndSummary) {
                                result.push(this.mapCalendarItem(c));
                            }
                        }
                        const hasResults = result.length > 0;
                        return hasResults ? result : def;
                    })(),
                    e => toSyncError(e)
                )
            );
    }

    createEvent(localEvent: AppEvent, options?: { baseEventRemoteId?: string, calendarId?: string }): ResultAsync<{ remoteId: string, calendarId: string }, SyncError> {
        const calendarId = options?.calendarId || "primary";
        return this.fetchWithAuth(`calendars/${encodeURIComponent(calendarId)}/events`, {
            method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(this.toGoogleEvent(localEvent, options?.baseEventRemoteId))
        }).andThen(res => 
            ResultAsync.fromPromise(
                (async () => {
                    if (!res.ok) throw new ApiError(`Failed to create event: ${res.status} ${await res.text()}`, res.status);
                    const data: { id?: string } = await res.json();
                    if (!data.id) throw new ApiError("Event created but no ID returned", res.status);
                    return { remoteId: data.id, calendarId };
                })(),
                e => toSyncError(e)
            )
        );
    }

    updateEvent(remoteId: string, localEvent: AppEvent, options?: { updatedFields?: (keyof AppEvent)[], baseEventRemoteId?: string, calendarId?: string }): ResultAsync<void, SyncError> {
        const calendarId = options?.calendarId || "primary";
        const headers: Record<string, string> = { "Content-Type": "application/json" };
        if (localEvent.etag) headers["If-Match"] = localEvent.etag;

        const fullPayload = this.toGoogleEvent(localEvent, options?.baseEventRemoteId);
        const payloadToSubmit = options?.updatedFields && options.updatedFields.length > 0
            ? buildPartialEventPayload(options.updatedFields, fullPayload)
            : fullPayload;

        return this.fetchWithAuth(`calendars/${encodeURIComponent(calendarId)}/events/${remoteId}`, {
            method: "PATCH", headers, body: JSON.stringify(payloadToSubmit)
        }).andThen(res => 
            ResultAsync.fromPromise(
                (async () => {
                    if (res.status === HTTP_PRECONDITION_FAILED) throw new ConflictError(`ETag conflict on event: ${localEvent.title}`);
                    if (!res.ok) throw new ApiError(`Failed to update event: ${res.status} ${await res.text()}`, res.status);
                })(),
                e => toSyncError(e)
            )
        );
    }

    moveEvent(remoteId: string, sourceCalendarId: string, destinationCalendarId: string): ResultAsync<void, SyncError> {
        return this.fetchWithAuth(`calendars/${encodeURIComponent(sourceCalendarId)}/events/${remoteId}/move?destination=${encodeURIComponent(destinationCalendarId)}`, {
            method: "POST"
        }).andThen(res => 
            ResultAsync.fromPromise(
                (async () => {
                    if (!res.ok && res.status !== HTTP_GONE) throw new ApiError(`Failed to move event: ${res.status} ${await res.text()}`, res.status);
                })(),
                e => toSyncError(e)
            )
        );
    }

    deleteEvent(remoteId: string, options?: { calendarId?: string }): ResultAsync<void, SyncError> {
        const calendarId = options?.calendarId || "primary";
        return this.fetchWithAuth(`calendars/${encodeURIComponent(calendarId)}/events/${remoteId}`, { method: "DELETE" })
            .andThen(res => 
                ResultAsync.fromPromise(
                    (async () => {
                        if (!res.ok) {
                            if (res.status === HTTP_GONE) return;
                            throw new ApiError(`Failed to delete event: ${res.status} ${await res.text()}`, res.status);
                        }
                    })(),
                    e => toSyncError(e)
                )
            );
    }

    toGoogleEvent(localEvent: AppEvent, baseEventRemoteId?: string): gapi.client.calendar.Event {
        const timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
        
        let startObj: gapi.client.calendar.EventDateTime;
        let endObj: gapi.client.calendar.EventDateTime;

        if (isEventAllDay(localEvent)) {
            startObj = { date: localEvent.startTime };
            endObj = { date: localEvent.endTime };
        } else {
            startObj = { dateTime: localEvent.startTime, timeZone };
            endObj = { dateTime: localEvent.endTime, timeZone };
        }

        return {
            summary: localEvent.title ?? "",
            start: startObj,
            end: endObj,
            description: localEvent.description ?? "",
            transparency: localEvent.type === "info" ? "transparent" : "opaque",
            extendedProperties: {
                private: {
                    taskrootEventId: localEvent.id,
                    ...(localEvent.taskId ? { taskId: localEvent.taskId } : {}),
                    type: localEvent.type ?? "",
                },
            },
            ...this.buildGoogleRecurrenceAndExceptions(localEvent, timeZone, baseEventRemoteId)
        };
    }

    private buildGoogleExdates(localEvent: AppEvent, timeZone: string, recurrence: string[]) {
        if (!localEvent.exdates) return;
        
        const isAllDay = isEventAllDay(localEvent);
        for (const exdate of localEvent.exdates) {
            if (isAllDay) {
                const hasTime = exdate.includes("T");
                const dateOnly = hasTime ? (exdate.split("T")[0] || exdate) : exdate;
                recurrence.push(`EXDATE;VALUE=DATE:${dateOnly}`);
            } else {
                recurrence.push(`EXDATE;TZID=${timeZone}:${exdate}`);
            }
        }
    }

    private buildGoogleRecurrenceAndExceptions(localEvent: AppEvent, timeZone: string, baseEventRemoteId?: string) {
        const recurrence: string[] = [];
        const hasRrule = !!localEvent.rrule;
        if (hasRrule) recurrence.push(`RRULE:${localEvent.rrule}`);
        
        this.buildGoogleExdates(localEvent, timeZone, recurrence);
        
        const result: Partial<gapi.client.calendar.Event> = {};
        const hasRecurrence = recurrence.length > 0;
        if (hasRecurrence) result.recurrence = recurrence;
        const hasBaseRemoteId = !!baseEventRemoteId;
        if (hasBaseRemoteId) result.recurringEventId = baseEventRemoteId;
        const hasOriginalStart = !!localEvent.originalStartTime;
        if (hasOriginalStart) {
            result.originalStartTime = { dateTime: localEvent.originalStartTime, timeZone };
        }
        return result;
    }

    toLocalEvent(googleEvent: gapi.client.calendar.Event, calendarId = "primary") {
        if (googleEvent.status === "cancelled") {
            return handleCancelledEvent(googleEvent);
        }
        const { startTime, endTime } = extractEventTime(googleEvent);
        const { taskId, id, type } = extractEventMetadata(googleEvent);
        const { rrule, exdates } = parseRecurrenceRule(googleEvent.recurrence);

        const rruleProps = rrule ? { rrule } : {};
        const exdatesProps = exdates ? { exdates } : {};
        const recurProps = googleEvent.recurringEventId ? { recurringEventId: googleEvent.recurringEventId } : {};
        const originalStartTime = googleEvent.originalStartTime?.dateTime || googleEvent.originalStartTime?.date;
        const origProps = originalStartTime ? { originalStartTime } : {};

        return {
            id, remoteId: googleEvent.id, remoteCollectionId: calendarId, taskId,
            title: googleEvent.summary ?? "", startTime, endTime, type,
            updatedAt: googleEvent.updated ? new Date(googleEvent.updated).getTime() : Date.now(),
            etag: googleEvent.etag,
            ...rruleProps,
            ...exdatesProps,
            ...recurProps,
            ...origProps
        };
    }
}

function extractEventTime(googleEvent: gapi.client.calendar.Event) {
    if (googleEvent.start?.dateTime) {
        return {
            startTime: toFloatingIso(new Date(googleEvent.start.dateTime)),
            endTime: toFloatingIso(new Date(googleEvent.end?.dateTime || googleEvent.start.dateTime))
        };
    }
    if (!googleEvent.start?.date) throw new Error("Google event missing time information");
    
    const startDate = googleEvent.start.date;
    const endDate = googleEvent.end?.date || startDate;
    return { startTime: startDate, endTime: endDate }; 
}

function applyTimeAndTitleUpdates(updatedFields: (keyof AppEvent)[], fullPayload: gapi.client.calendar.Event, partialPayload: Partial<gapi.client.calendar.Event>) {
    const hasTimeUpdate = updatedFields.includes("startTime") || updatedFields.includes("endTime");
    
    const summaryVal = fullPayload.summary;
    const incSummary = updatedFields.includes("title") && summaryVal !== undefined;
    if (incSummary) partialPayload.summary = summaryVal;

    const startVal = fullPayload.start;
    const incStart = hasTimeUpdate && startVal !== undefined;
    if (incStart) partialPayload.start = startVal;

    const endVal = fullPayload.end;
    const incEnd = hasTimeUpdate && endVal !== undefined;
    if (incEnd) partialPayload.end = endVal;
}

function applyMetadataUpdates(updatedFields: (keyof AppEvent)[], fullPayload: gapi.client.calendar.Event, partialPayload: Partial<gapi.client.calendar.Event>) {
    const hasTypeOrTaskUpdate = updatedFields.includes("type") || updatedFields.includes("taskId");
    
    const extPropsVal = fullPayload.extendedProperties;
    const incExtProps = hasTypeOrTaskUpdate && extPropsVal !== undefined;
    if (incExtProps) partialPayload.extendedProperties = extPropsVal;
    
    const transpVal = fullPayload.transparency;
    const incTransp = hasTypeOrTaskUpdate && transpVal !== undefined;
    if (incTransp) partialPayload.transparency = transpVal;
}

function applyRecurrenceUpdates(updatedFields: (keyof AppEvent)[], fullPayload: gapi.client.calendar.Event, partialPayload: Partial<gapi.client.calendar.Event>) {
    const hasRecurrenceUpdate = updatedFields.includes("rrule") || updatedFields.includes("exdates");
    
    const recVal = fullPayload.recurrence;
    const incRecurrence = hasRecurrenceUpdate && recVal !== undefined;
    if (incRecurrence) partialPayload.recurrence = recVal;
    
    const recurIdVal = fullPayload.recurringEventId;
    const incRecurringId = updatedFields.includes("recurringEventId") && recurIdVal !== undefined;
    if (incRecurringId) partialPayload.recurringEventId = recurIdVal;
    
    const origStartVal = fullPayload.originalStartTime;
    const incOriginalStart = updatedFields.includes("originalStartTime") && origStartVal !== undefined;
    if (incOriginalStart) partialPayload.originalStartTime = origStartVal;
}

function buildPartialEventPayload(updatedFields: (keyof AppEvent)[], fullPayload: gapi.client.calendar.Event) {
    const partialPayload: Partial<gapi.client.calendar.Event> = {};
    applyTimeAndTitleUpdates(updatedFields, fullPayload, partialPayload);
    applyMetadataUpdates(updatedFields, fullPayload, partialPayload);
    applyRecurrenceUpdates(updatedFields, fullPayload, partialPayload);
    return partialPayload;
}

function handleCancelledEvent(googleEvent: gapi.client.calendar.Event) {
    const privateProps = googleEvent.extendedProperties?.private;
    const id = (privateProps ? privateProps["taskrootEventId"] : undefined) || googleEvent.id;
    if (!id) throw new Error("Cancelled Google event missing ID");
    return {
        id,
        _deleted: true,
        updatedAt: googleEvent.updated ? new Date(googleEvent.updated).getTime() : 0,
    };
}

function getEventId(googleEvent: gapi.client.calendar.Event) {
    const priv = googleEvent.extendedProperties?.private;
    if (priv?.["taskrootEventId"]) return priv["taskrootEventId"];
    if (!googleEvent.id) throw new Error("Google event missing ID");
    return googleEvent.id;
}

function getEventTaskId(googleEvent: gapi.client.calendar.Event) {
    return googleEvent.extendedProperties?.private?.["taskId"];
}

function extractEventMetadata(googleEvent: gapi.client.calendar.Event) {
    const taskId = getEventTaskId(googleEvent);
    const id = getEventId(googleEvent);
    const defaultType: AppEvent['type'] = googleEvent.transparency === "transparent" ? "info" : "busy";
    const type = toEventType(googleEvent.extendedProperties?.private?.["type"], defaultType);
    return { taskId, id, type };
}

function parseRecurrenceRule(recurrence?: string[]): { rrule?: string, exdates?: string[] } {
    if (!recurrence) return {};
    const r = recurrence.find((ruleStr) => ruleStr.startsWith("RRULE:"));
    const rrule = r ? r.replace(/^RRULE:/i, "") : undefined;
    
    const exdates: string[] = [];
    for (const ruleStr of recurrence) {
        if (ruleStr.startsWith("EXDATE")) {
            const parts = ruleStr.split(":");
            if (parts.length > 1) {
                exdates.push(parts.slice(1).join(":"));
            }
        }
    }
    return { ...(rrule !== undefined ? { rrule } : {}), ...(exdates.length > 0 ? { exdates } : {}) };
}

import type { AppEvent } from "../../domain/models";
import { ResultAsync } from "neverthrow";
import type { SyncError } from "../errors";
/// <reference types="gapi.client.calendar" />

export interface ICalendarAPI {
    fetchEvents(timeMin: string, timeMax: string, calendarId?: string): ResultAsync<gapi.client.calendar.Event[] | undefined, SyncError>;
    fetchCalendars(): ResultAsync<{id: string, summary: string, accessRole?: string, backgroundColor?: string, foregroundColor?: string, primary?: boolean}[], SyncError>;
    createEvent(localEvent: AppEvent, options?: { baseEventRemoteId?: string, calendarId?: string }): ResultAsync<{ remoteId: string, calendarId: string }, SyncError>;
    updateEvent(remoteId: string, localEvent: AppEvent, options?: { updatedFields?: (keyof AppEvent)[], baseEventRemoteId?: string, calendarId?: string }): ResultAsync<void, SyncError>;
    moveEvent(remoteId: string, sourceCalendarId: string, destinationCalendarId: string): ResultAsync<void, SyncError>;
    deleteEvent(remoteId: string, options?: { calendarId?: string }): ResultAsync<void, SyncError>;
    toLocalEvent(remoteEvent: gapi.client.calendar.Event, calendarId?: string): AppEvent | { id: string; _deleted: boolean; updatedAt: number; };
}

import type { ISyncStrategy } from "./Synchronizer";
import type { ISyncEngineContext, SyncQueueItem } from "./types";
import { SyncAction, SyncType } from "./types";
import type { ICalendarAPI } from "../calendar-api/types";
import type { AppEvent } from "../../domain/models";
import { repos } from "../../store/repositories";
import { ResultAsync, okAsync } from "neverthrow";
import { resolveConflict } from "./conflict-resolver";
import { computeEventDeltaActions } from "./event-differ";
import { toSyncError, type SyncError } from "../errors";

export class EventSyncStrategy implements ISyncStrategy<AppEvent> {
    private context: ISyncEngineContext;
    private calendarAPI: ICalendarAPI;

    constructor(context: ISyncEngineContext, calendarAPI: ICalendarAPI) {
        this.context = context;
        this.calendarAPI = calendarAPI;
    }

    isSyncEnabled(): boolean {
        return this.context.getSettings().enableCalendarSync ?? true;
    }

    getLocalItems(): AppEvent[] {
        return repos.events.get().unwrapOr(repos.events.initial);
    }

    setLocalItems(items: AppEvent[]): void {
        repos.events.setFromRemote(items);
    }

    getSyncType(): SyncType {
        return SyncType.Event;
    }

    extractItem(q: SyncQueueItem): AppEvent | undefined {
        return q.type === SyncType.Event ? q.item : undefined;
    }

    updateOldMapSnapshot(items: AppEvent[]): void {
        this.context.updateOldEventsMap(items);
    }

    fetchRemoteItems(): ResultAsync<unknown[] | undefined, SyncError> {
        return ResultAsync.fromPromise(
            (async () => {
                const timeMin = new Date();
                timeMin.setMonth(timeMin.getMonth() - 1);
                const timeMax = new Date();
                timeMax.setMonth(timeMax.getMonth() + 2);

                const calendarsResult = await this.calendarAPI.fetchCalendars();
                if (calendarsResult.isErr()) throw calendarsResult.error;
                const calendars = calendarsResult.value;
                const prevCalendars = repos.calendars.get().unwrapOr(repos.calendars.initial);
                repos.calendars.setFromRemote(
                    calendars.map((c) => {
                        const prev = prevCalendars.find((p) => p.id === c.id);
                        return { ...c, active: prev ? prev.active : c.primary || false };
                    }),
                );

                const allRemoteEvents: Array<AppEvent | { id: string, _deleted: boolean, updatedAt: number }> = [];
                await Promise.all(
                    calendars.map(async (cal) => {
                        const remoteEventsResult = await this.calendarAPI.fetchEvents(
                            timeMin.toISOString(),
                            timeMax.toISOString(),
                            cal.id,
                        );
                        if (remoteEventsResult.isOk() && remoteEventsResult.value) {
                            allRemoteEvents.push(
                                ...remoteEventsResult.value.map((e: gapi.client.calendar.Event) =>
                                    this.calendarAPI.toLocalEvent(e, cal.id),
                                ),
                            );
                        } else if (remoteEventsResult.isErr()) {
                            console.error("Failed to fetch remote events", remoteEventsResult.error);
                        }
                    })
                );

                return allRemoteEvents;
            })(),
            e => toSyncError(e)
        );
    }

    processSingleRemoteItem(
        remote: AppEvent | { id: string, _deleted?: boolean, updatedAt?: number },
        _localItemsArray: AppEvent[],
        localItemsMap: Map<string, AppEvent>
    ): boolean {
        const existingLocalEvent = localItemsMap.get(remote.id);
        return resolveConflict(remote, existingLocalEvent, localItemsMap);
    }



    computeDelta(currentEvents: AppEvent[]) {
        const actions = computeEventDeltaActions(currentEvents, this.context.oldEventsMap);
        for (const action of actions) {
            this.context.pushQueue.push(action);
        }
        this.context.updateOldEventsMap(currentEvents);
    }

    private actionHandlers: Record<string, (item: SyncQueueItem) => Promise<void>> = {
        [SyncAction.Create]: async (taskOrEvent) => {
            if (taskOrEvent.type !== SyncType.Event) return;
            const targetCalendarId = taskOrEvent.item.remoteCollectionId || "primary";
            const eventsData = repos.events.get().unwrapOr(repos.events.initial);
            const baseEventRemoteId = taskOrEvent.item.recurringEventId ? eventsData.find(e => e.id === taskOrEvent.item.recurringEventId)?.remoteId : undefined;
            const resResult = await this.calendarAPI.createEvent(
                taskOrEvent.item,
                { 
                    ...(baseEventRemoteId !== undefined ? { baseEventRemoteId } : {}), 
                    calendarId: targetCalendarId 
                }
            );
            if (resResult.isErr()) throw resResult.error;
            const res = resResult.value;
            if (res) {
                const events = repos.events.get().unwrapOr(repos.events.initial);
                const idx = events.findIndex((e) => e.id === taskOrEvent.item.id);
                const e = events[idx];
                if (idx !== -1 && e) {
                    const updated = [...events];
                    updated[idx] = {
                        ...e,
                        remoteId: res.remoteId,
                        remoteCollectionId: res.calendarId,
                    };
                    repos.events.setFromRemote(updated);
                    this.context.updateOldEventsMap(updated);
                } else {
                    const deleteResult = await this.calendarAPI.deleteEvent(res.remoteId, { calendarId: res.calendarId });
                    if (deleteResult.isErr()) throw deleteResult.error;
                }
            }
        },
        [SyncAction.Update]: async (taskOrEvent) => {
            if (taskOrEvent.type !== SyncType.Event) return;
            const events = repos.events.get().unwrapOr(repos.events.initial);
            const currentEvent = events.find((e) => e.id === taskOrEvent.item.id);
            const gid = currentEvent?.remoteId || taskOrEvent.remoteId;

            if (gid) {
                const baseEventRemoteId = taskOrEvent.item.recurringEventId ? events.find(e => e.id === taskOrEvent.item.recurringEventId)?.remoteId : undefined;
                const updateResult = await this.calendarAPI.updateEvent(
                    gid,
                    taskOrEvent.item,
                    { 
                        ...(taskOrEvent.updatedFields !== undefined ? { updatedFields: taskOrEvent.updatedFields } : {}), 
                        ...(baseEventRemoteId !== undefined ? { baseEventRemoteId } : {}), 
                        ...(taskOrEvent.calendarId !== undefined ? { calendarId: taskOrEvent.calendarId } : {}) 
                    }
                );
                if (updateResult.isErr()) throw updateResult.error;
            }
        },
        [SyncAction.Delete]: async (taskOrEvent) => {
            if (taskOrEvent.type !== SyncType.Event) return;
            // Delete actions always have taskOrEvent.remoteId if they were queued correctly.
            // If deleted before Create finished, it's handled in the Create block.
            if (taskOrEvent.remoteId) {
                const deleteResult = await this.calendarAPI.deleteEvent(
                    taskOrEvent.remoteId,
                    taskOrEvent.calendarId ? { calendarId: taskOrEvent.calendarId } : undefined,
                );
                if (deleteResult.isErr()) throw deleteResult.error;
            }
        },
        [SyncAction.Move]: async (taskOrEvent) => {
            if (taskOrEvent.type !== SyncType.Event || !taskOrEvent.remoteId || !taskOrEvent.calendarId || !taskOrEvent.destinationCalendarId) return;
            const moveResult = await this.calendarAPI.moveEvent(
                taskOrEvent.remoteId,
                taskOrEvent.calendarId,
                taskOrEvent.destinationCalendarId
            );
            if (moveResult.isErr()) throw moveResult.error;
        }
    };

    processPushItem(taskOrEvent: SyncQueueItem): ResultAsync<void, SyncError> {
        if (taskOrEvent.type !== SyncType.Event) return okAsync(undefined);
        const handler = this.actionHandlers[taskOrEvent.action];
        if (handler) {
            return ResultAsync.fromPromise(
                handler(taskOrEvent),
                e => toSyncError(e)
            );
        }
        return okAsync(undefined);
    }
}

import { MS_PER_SECOND, MINUTES_IN_HOUR, STARTUP_ERROR_DELAY_MS } from "../../utils/constants";
import { syncState } from "../SyncState";
import type { Synchronizer } from "./Synchronizer";
import { Pusher } from "./Pusher";
import type { AppTask, AppEvent } from "../../domain/models";

export const MIN_POLL_INTERVAL_MINUTES = 5;


export class Poller {
    private pollInterval: ReturnType<typeof setInterval> | undefined = undefined;
    private taskSync: Synchronizer<AppTask>;
    private eventSync: Synchronizer<AppEvent>;
    private pusher: Pusher;
    private getSettings: () => Partial<import('../../store/settingsSchema').AppSettings>;
    private hasAuth: () => boolean;

    constructor(
        taskSync: Synchronizer<AppTask>,
        eventSync: Synchronizer<AppEvent>,
        pusher: Pusher,
        options: {
            getSettings: () => Partial<import('../../store/settingsSchema').AppSettings>;
            hasAuth: () => boolean;
        }
    ) {
        this.taskSync = taskSync;
        this.eventSync = eventSync;
        this.pusher = pusher;
        this.getSettings = options.getSettings;
        this.hasAuth = options.hasAuth;
    }

    start() {
        const offline = import.meta.env?.VITE_OFFLINE_MODE === "true";
        const settings = this.getSettings();
        if (offline || (settings.enableCalendarSync === false && settings.enableTasksSync === false))
            syncState.initialSyncComplete = true;

        if (this.pollInterval) return;

        if (this.hasAuth()) {
            void this.poll();
        } else if (!syncState.initialSyncComplete) {
            syncState.initialSyncComplete = true;
            if (!offline && (settings.enableCalendarSync !== false || settings.enableTasksSync !== false)) {
                setTimeout(() => {
                    syncState.error = "Sync is paused: No authorization token found. Please log out and log in again to authorize.";
                    syncState.checkConnectivity();
                }, STARTUP_ERROR_DELAY_MS);
            }
        }

        syncState.nextSyncTime = Date.now() + (settings.syncInterval || MIN_POLL_INTERVAL_MINUTES) * MINUTES_IN_HOUR * MS_PER_SECOND;
        this.pollInterval = setInterval(() => {
            if (Date.now() >= syncState.nextSyncTime)
                void this.poll();
        }, MS_PER_SECOND);

        window.addEventListener("online", () => {
            syncState.info = "Network reconnected. Forcing sync.";
            syncState.isPolling = false;
            this.forceSync();
        });
    }

    forceSync() {
        if (this.pollInterval)
            clearInterval(this.pollInterval);
        void this.poll();
        const settings = this.getSettings();
        syncState.nextSyncTime = Date.now() + (settings.syncInterval || MIN_POLL_INTERVAL_MINUTES) * MINUTES_IN_HOUR * MS_PER_SECOND;
        this.pollInterval = setInterval(() => {
            if (Date.now() >= syncState.nextSyncTime)
                void this.poll();
        }, MS_PER_SECOND);
    }

    private handlePollError(e: Error) {
        console.error("Poller poll error:", e);
        if (e.message === "Unauthorized") {
            syncState.error = "Failed to refresh session. You may need to log out and log back in.";
        } else {
            syncState.error = e.message || "Error during synchronization";
        }
        syncState.checkConnectivity();
    }

    async poll() {
        if (syncState.isPolling) return;
        syncState.isPolling = true;
        syncState.error = undefined;

        const taskResult = await this.taskSync.poll();
        if (taskResult.isErr()) {
            this.handlePollError(taskResult.error);
        } else {
            const eventResult = await this.eventSync.poll();
            if (eventResult.isErr()) {
                this.handlePollError(eventResult.error);
            } else {
                this.pusher.trigger();
            }
        }

        syncState.isPolling = false;
        const settings = this.getSettings();
        syncState.nextSyncTime = Date.now() + (settings.syncInterval || MIN_POLL_INTERVAL_MINUTES) * MINUTES_IN_HOUR * MS_PER_SECOND;
        if (!syncState.initialSyncComplete) {
            syncState.initialSyncComplete = true;
        }
    }
}

import { SyncQueue } from "./SyncQueue";
import type { Synchronizer } from "./Synchronizer";
import { SyncType } from "./types";
import { syncState } from "../SyncState";
import { ConflictError } from "../errors";
import type { AppTask, AppEvent } from "../../domain/models";
import type { SyncQueueItem } from "./types";

export class Pusher {
    private pushQueue = new SyncQueue();
    private synchronizers: Record<string, Synchronizer<{ id: string }>> = {};

    constructor(
        taskSync: Synchronizer<AppTask>,
        eventSync: Synchronizer<AppEvent>
    ) {
        this.synchronizers = {
            [SyncType.Task]: taskSync,
            [SyncType.Event]: eventSync,
        };
    }

    get queue() {
        return this.pushQueue;
    }

    trigger() {
        if (syncState.isPushing) return;
        void this.processPushQueue();
    }

    private handlePushError(e: unknown, taskOrEvent: SyncQueueItem): boolean {
        if (e instanceof ConflictError) {
            console.warn(`ETag conflict on push: ${e.message}. Dropping push to let poller resolve.`);
            this.pushQueue.remove(taskOrEvent);
            return false;
        }

        console.error("Push failed", e);
        if (e instanceof Error && (e.message.includes("403") || e.message.includes("404") || e.message.includes("400"))) {
            this.pushQueue.remove(taskOrEvent);
            const itemName = taskOrEvent.item.title || "Unknown item";
            syncState.error = `Sync ${taskOrEvent.action} item "${itemName}" discarded because of error: ${e.message}`;
            syncState.checkConnectivity();
            return false;
        }
        
        syncState.error = e instanceof Error ? e.message : "Error syncing item to Google.";
        syncState.checkConnectivity();
        return true;
    }

    private async processPushQueue() {
        if (this.pushQueue.length === 0) return;
        syncState.isPushing = true;

        while (this.pushQueue.length > 0) {
            const taskOrEvent = this.pushQueue.peek();
            if (!taskOrEvent) {
                this.pushQueue.shift();
                continue;
            }
            const sync = this.synchronizers[taskOrEvent.type];
            if (!sync || !sync.isSyncEnabled()) {
                this.pushQueue.remove(taskOrEvent);
                continue;
            }
            
            const result = await sync.processPushItem(taskOrEvent);
            if (result.isErr()) {
                const shouldBreak = this.handlePushError(result.error, taskOrEvent);
                if (shouldBreak) break;
            } else {
                this.pushQueue.remove(taskOrEvent);
            }
        }

        syncState.isPushing = false;
    }
}

import { describe, it, expect, beforeEach } from "vitest";
import { SyncQueue } from "./SyncQueue";
import { SyncAction, SyncType } from "./types";
import type { AppTask, AppEvent } from "../../domain/models";

describe("SyncQueue", () => {
    beforeEach(() => {
        localStorage.clear();
    });

    it("should push items normally", () => {
        const queue = new SyncQueue();
        const task: AppTask = { id: "1", title: "Task 1" };
        
        queue.push({
            type: SyncType.Task,
            action: SyncAction.Create,
            item: task
        });

        expect(queue.length).toBe(1);
        expect(queue.peek()?.action).toBe(SyncAction.Create);
    });

    it("should deduplicate Update actions for the same task", () => {
        const queue = new SyncQueue();
        const task1: AppTask = { id: "1", title: "Task 1" };
        const task1Updated: AppTask = { id: "1", title: "Task 1 Updated" };
        
        queue.push({
            type: SyncType.Task,
            action: SyncAction.Update,
            item: task1
        });

        // Push an update for the same task
        queue.push({
            type: SyncType.Task,
            action: SyncAction.Update,
            item: task1Updated
        });

        expect(queue.length).toBe(1);
        const items = queue.getItems();
        expect(items[0]?.item.title).toBe("Task 1 Updated");
    });

    it("should not deduplicate Update actions for different tasks", () => {
        const queue = new SyncQueue();
        const task1: AppTask = { id: "1", title: "Task 1" };
        const task2: AppTask = { id: "2", title: "Task 2" };
        
        queue.push({
            type: SyncType.Task,
            action: SyncAction.Update,
            item: task1
        });

        queue.push({
            type: SyncType.Task,
            action: SyncAction.Update,
            item: task2
        });

        expect(queue.length).toBe(2);
    });

    it("should merge Update action into pending Create", () => {
        const queue = new SyncQueue();
        const task: AppTask = { id: "1", title: "Task 1" };
        
        queue.push({
            type: SyncType.Task,
            action: SyncAction.Create,
            item: task
        });

        queue.push({
            type: SyncType.Task,
            action: SyncAction.Update,
            item: { ...task, title: "Task 1 Updated" }
        });

        expect(queue.length).toBe(1);
        const items = queue.getItems();
        expect(items[0]?.action).toBe(SyncAction.Create);
        expect(items[0]?.item.title).toBe("Task 1 Updated");
    });
    it("should handle Move+Update correctly (ensuring Update is pushed to end of queue)", () => {
        const queue = new SyncQueue();
        const eventItem: AppEvent = { 
            id: "1", 
            title: "Original Title", 
            type: "busy",
            startTime: "2023-10-10T16:40:00",
            endTime: "2023-10-10T18:20:00",
            updatedAt: 0
        };
        const eventUpdated: AppEvent = { ...eventItem, title: "New Title" };
        
        queue.push({
            type: SyncType.Event,
            action: SyncAction.Update,
            item: eventItem,
            remoteId: "g1",
            calendarId: "cal1"
        });

        queue.push({
            type: SyncType.Event,
            action: SyncAction.Move,
            item: eventItem,
            remoteId: "g1",
            calendarId: "cal1",
            destinationCalendarId: "cal2"
        });

        // The queue should now have [Update, Move]
        expect(queue.length).toBe(2);
        
        // Pushing a new Update
        queue.push({
            type: SyncType.Event,
            action: SyncAction.Update,
            item: eventUpdated,
            remoteId: "g1",
            calendarId: "cal2"
        });
        
        // The queue should now have [Move, Update] (Update pushed to the end)
        expect(queue.length).toBe(2);
        const items = queue.getItems();
        
        expect(items[0]?.action).toBe(SyncAction.Move);
        expect(items[0]?.item.title).toBe("New Title"); // Move payload updated
        
        expect(items[1]?.action).toBe(SyncAction.Update);
        expect(items[1]?.item.title).toBe("New Title"); // The new Update action
        expect(items[1]?.calendarId).toBe("cal2");
    });
});

import type { SyncQueueItem } from "./types";
import { SyncAction } from "./types";
import { Result, ok } from "neverthrow";

const safeGetItem = Result.fromThrowable(
    (key: string) => localStorage.getItem(key),
    (e) => e instanceof Error ? e : new Error(String(e))
);

const safeParse = Result.fromThrowable(
    JSON.parse,
    (e) => e instanceof Error ? e : new Error(String(e))
);

const safeStringify = Result.fromThrowable(
    JSON.stringify,
    (e) => e instanceof Error ? e : new Error(String(e))
);

const safeSetItem = Result.fromThrowable(
    (key: string, value: string) => localStorage.setItem(key, value),
    (e) => e instanceof Error ? e : new Error(String(e))
);

export class SyncQueue {
    private queue: SyncQueueItem[] = [];

    constructor() {
        this.load();
    }

    private load() {
        safeGetItem("taskroot_sync_queue")
            .andThen((saved) => (saved ? safeParse(saved) : ok(undefined)))
            .map((parsed) => {
                if (parsed) this.queue = parsed;
            })
            .mapErr((e) => {
                console.error("Failed to load SyncQueue from localStorage", e);
                this.queue = [];
            });
    }

    private save() {
        safeStringify(this.queue)
            .andThen((stringified) => safeSetItem("taskroot_sync_queue", stringified))
            .mapErr((e) => {
                console.error("Failed to save SyncQueue to localStorage", e);
            });
    }

    private handleUpdateTransition(transition: string, item: SyncQueueItem, indices: { create: number, update: number, move: number }) {
        if (transition === "create->update") {
            const q = this.queue[indices.create];
            if (q) q.item = item.item;
        } else if (transition === "update->update") {
            this.queue[indices.update] = item;
        } else if (transition === "move->update") {
            const q = this.queue[indices.move];
            if (q) q.item = item.item;
            this.queue.push(item);
        } else if (transition === "move+update->update") {
            const q = this.queue[indices.move];
            if (q) q.item = item.item;
            this.queue.splice(indices.update, 1);
            this.queue.push(item);
        } else if (transition === "delete->update") {
            console.warn("Attempted to update a deleted item. Ignoring.");
        }
    }

    private handleMoveTransition(transition: string, item: SyncQueueItem, indices: { create: number, update: number, move: number }) {
        if (transition === "create->move") {
            const q = this.queue[indices.create];
            if (q) q.item = item.item;
        } else if (transition === "update->move") {
            const q = this.queue[indices.update];
            if (q) q.item = item.item;
            this.queue.push(item);
        } else if (transition === "move->move") {
            this.queue[indices.move] = item;
        } else if (transition === "move+update->move") {
            const q = this.queue[indices.update];
            if (q) q.item = item.item;
            this.queue[indices.move] = item;
        } else if (transition === "delete->move") {
            console.warn("Attempted to move a deleted item. Ignoring.");
        }
    }

    private handleTransition(
        transition: string, 
        item: SyncQueueItem, 
        existingIndices: number[],
        indices: { create: number, update: number, move: number }
    ) {
        const removeAllExisting = () => {
            for (const idx of [...existingIndices].toSorted((a, b) => b - a)) {
                this.queue.splice(idx, 1);
            }
       };

        if (item.action === SyncAction.Create) {
            if (transition === "delete->create") {
                removeAllExisting();
                this.queue.push(item);
            } else {
                console.warn("Attempted to recreate an item that already exists in the queue.");
            }
        } else if (item.action === SyncAction.Update) {
            this.handleUpdateTransition(transition, item, indices);
        } else if (item.action === SyncAction.Move) {
            this.handleMoveTransition(transition, item, indices);
        } else if (item.action === SyncAction.Delete) {
            if (transition === "delete->delete") return;
            removeAllExisting();
            if (transition !== "create->delete" && item.remoteId) {
                this.queue.push(item);
            }
        }
    }

    private determineExistingState(indices: { create: number, update: number, move: number, delete: number }) {
        if (indices.create !== -1) return "create";
        if (indices.delete !== -1) return "delete";
        if (indices.update !== -1 && indices.move !== -1) return "move+update";
        if (indices.update !== -1) return "update";
        if (indices.move !== -1) return "move";
        return "";
    }

    private updateIndicesForExisting(i: number, action: SyncAction, existingIndices: number[], indices: { create: number, update: number, move: number, delete: number }) {
        existingIndices.push(i);
        switch (action) {
            case SyncAction.Create: indices.create = i; break;
            case SyncAction.Update: indices.update = i; break;
            case SyncAction.Move: indices.move = i; break;
            case SyncAction.Delete: indices.delete = i; break;
        }
    }

    private getExistingIndicesAndStates(item: SyncQueueItem) {
        const existingIndices: number[] = [];
        const indices = { create: -1, update: -1, move: -1, delete: -1 };
        
        for (let i = 0; i < this.queue.length; i++) {
            const q = this.queue[i];
            if (!q) continue;
            if (q.type === item.type && q.item?.id === item.item?.id) {
                this.updateIndicesForExisting(i, q.action, existingIndices, indices);
            }
        }
        return { existingIndices, indices };
    }

    push(item: SyncQueueItem) {
        const { existingIndices, indices } = this.getExistingIndicesAndStates(item);

        if (existingIndices.length === 0) {
            if (item.action === SyncAction.Delete && !item.remoteId) {
                return;
            }
            this.queue.push(item);
            this.save();
            return;
        }

        const existingState = this.determineExistingState(indices);
        const transition = `${existingState}->${item.action}`;
        this.handleTransition(transition, item, existingIndices, indices);
        this.save();
    }

    shift(): SyncQueueItem | undefined {
        const item = this.queue.shift();
        if (item !== undefined) {
            this.save();
        }
        return item;
    }

    remove(item: SyncQueueItem) {
        const index = this.queue.indexOf(item);
        if (index !== -1) {
            this.queue.splice(index, 1);
            this.save();
        }
    }

    peek(): SyncQueueItem | undefined {
        return this.queue.length > 0 ? this.queue[0] : undefined;
    }

    get length(): number {
        return this.queue.length;
    }

    getItems(): SyncQueueItem[] {
        return [...this.queue];
    }

    clear() {
        this.queue = [];
        this.save();
    }
}

import type { ISyncEngineContext, SyncQueueItem } from "./types";
import { SyncAction, SyncType } from "./types";
import { ResultAsync, okAsync } from "neverthrow";
import { toSyncError, type SyncError } from "../errors";

export interface ISyncStrategy<T extends { id: string; remoteId?: string | undefined; updatedAt?: number | undefined }> {
    isSyncEnabled(): boolean;
    getLocalItems(): T[];
    setLocalItems(items: T[]): void;
    getSyncType(): SyncType;
    updateOldMapSnapshot(items: T[]): void;
    fetchRemoteItems(): ResultAsync<unknown[] | undefined, SyncError>;
    processSingleRemoteItem(remote: unknown, localItemsArray: T[], localItemsMap: Map<string, T>): boolean;
    computeDelta(currentItems: T[]): void;
    processPushItem(item: SyncQueueItem): ResultAsync<void, SyncError>;
    extractItem(q: SyncQueueItem): T | undefined;
}

export class Synchronizer<T extends { id: string; remoteId?: string | undefined; updatedAt?: number | undefined }> {
    protected context: ISyncEngineContext;
    private strategy: ISyncStrategy<T>;

    constructor(context: ISyncEngineContext, strategy: ISyncStrategy<T>) {
        this.context = context;
        this.strategy = strategy;
    }

    isSyncEnabled(): boolean {
        return this.strategy.isSyncEnabled();
    }

    poll(): ResultAsync<void, SyncError> {
        if (!this.isSyncEnabled()) return okAsync(undefined);

        return ResultAsync.fromPromise(
            (async () => {
                const localItems = this.strategy.getLocalItems();
                this.strategy.updateOldMapSnapshot(localItems);
                
                const remoteItemsResult = await this.strategy.fetchRemoteItems();
                if (remoteItemsResult.isErr()) throw remoteItemsResult.error;
                const remoteItems = remoteItemsResult.value;
                if (!remoteItems) return;

                let updated = false;
                const localItemsMap = new Map<string, T>(localItems.map((item) => [item.id, item]));

                for (const remote of remoteItems) {
                    if (this.strategy.processSingleRemoteItem(remote, localItems, localItemsMap)) {
                        updated = true;
                    }
                }

                if (this.applyOptimisticOverlay(localItemsMap)) {
                    updated = true;
                }

                if (updated) {
                    const newItems = Array.from(localItemsMap.values());
                    this.strategy.setLocalItems(newItems);
                    this.strategy.updateOldMapSnapshot(newItems);
                }
            })(),
            (e) => toSyncError(e)
        );
    }

    protected applyOptimisticOverlay(localItemsMap: Map<string, T>): boolean {
        let updated = false;
        for (const q of this.context.pushQueue.getItems()) {
            if (this.processQueueItem(q, localItemsMap)) {
                updated = true;
            }
        }
        return updated;
    }

    private processQueueItem(q: SyncQueueItem, localItemsMap: Map<string, T>): boolean {
        if (q.type !== this.strategy.getSyncType()) return false;
        
        if (q.action === SyncAction.Delete) {
            return this.applyQueueDelete(q, localItemsMap);
        } else if ((q.action === SyncAction.Update || q.action === SyncAction.Create || q.action === SyncAction.Move) && q.item?.id) {
            return this.applyQueueUpsert(q, localItemsMap);
        }
        return false;
    }

    private applyQueueDelete(q: SyncQueueItem, localItemsMap: Map<string, T>): boolean {
        let updated = false;
        if (q.item?.id) {
            localItemsMap.delete(q.item.id);
            updated = true;
        }
        if (q.remoteId) {
            for (const [key, item] of Array.from(localItemsMap.entries())) {
                if (item.remoteId === q.remoteId) {
                    localItemsMap.delete(key);
                    updated = true;
                }
            }
        }
        return updated;
    }

    private applyQueueUpsert(q: SyncQueueItem, localItemsMap: Map<string, T>): boolean {
        const existing = localItemsMap.get(q.item.id);
        if ((q.action === SyncAction.Update || q.action === SyncAction.Move) && q.updatedFields && existing) {
            const partialUpdate: Partial<T> = {};
            for (const field of q.updatedFields) {
                Object.defineProperty(partialUpdate, field, {
                    value: Reflect.get(q.item, field),
                    enumerable: true,
                    writable: true,
                    configurable: true,
                });
            }
            Object.defineProperty(partialUpdate, "updatedAt", {
                value: Math.max(q.item.updatedAt || 0, existing.updatedAt || 0),
                enumerable: true,
                writable: true,
                configurable: true,
            });
            localItemsMap.set(q.item.id, { ...existing, ...partialUpdate });
        } else {
            const extracted = this.strategy.extractItem(q);
            if (extracted) {
                localItemsMap.set(q.item.id, extracted);
            }
        }
        return true;
    }

    computeDelta(currentItems: T[]) {
        this.strategy.computeDelta(currentItems);
    }

    processPushItem(item: SyncQueueItem): ResultAsync<void, SyncError> {
        return this.strategy.processPushItem(item);
    }
}

import type { ISyncStrategy } from "./Synchronizer";
import type { ISyncEngineContext, SyncQueueItem } from "./types";
import { SyncAction, SyncType } from "./types";
import type { ITasksAPI } from "../task-api/types";
import type { AppTask } from "../../domain/models";
import { repos } from "../../store/repositories";
import { resolveConflict } from "./conflict-resolver";
import { computeTaskDeltaActions } from "./task-differ";
import { ResultAsync, okAsync } from "neverthrow";
import { toSyncError, type SyncError } from "../errors";

export class TaskSyncStrategy implements ISyncStrategy<AppTask> {
    private context: ISyncEngineContext;
    private tasksAPI: ITasksAPI;

    constructor(context: ISyncEngineContext, tasksAPI: ITasksAPI) {
        this.context = context;
        this.tasksAPI = tasksAPI;
    }

    isSyncEnabled(): boolean {
        return this.context.getSettings().enableTasksSync ?? true;
    }

    getLocalItems(): AppTask[] {
        return repos.tasks.get().unwrapOr(repos.tasks.initial);
    }

    setLocalItems(items: AppTask[]): void {
        repos.tasks.setFromRemote(items);
    }

    getSyncType(): SyncType {
        return SyncType.Task;
    }

    extractItem(q: SyncQueueItem): AppTask | undefined {
        return q.type === SyncType.Task ? q.item : undefined;
    }

    updateOldMapSnapshot(items: AppTask[]): void {
        this.context.updateOldTasksMap(items);
    }

    fetchRemoteItems(): ResultAsync<unknown[] | undefined, SyncError> {
        return this.tasksAPI.fetchTasks();
    }

    processSingleRemoteItem(
        remote: gapi.client.tasks.Task,
        _localItemsArray: AppTask[],
        localItemsMap: Map<string, AppTask>
    ): boolean {
        let localId: string | undefined = undefined;
        const match = remote.notes?.match(
            /Taskroot Task ID: (t[0-9a-zA-Z-]+)/,
        );
        if (match) {
            localId = match[1];
        } else {
            for (const t of Array.from(localItemsMap.values())) {
                if (t.remoteId === remote.id) {
                    localId = t.id;
                    break;
                }
            }
        }

        const existingLocalTask = localId ? localItemsMap.get(localId) : undefined;
        const standardizedRemote = this.tasksAPI.toLocalTask(
            remote,
            existingLocalTask,
        );

        return resolveConflict(standardizedRemote, existingLocalTask, localItemsMap);
    }



    computeDelta(currentTasks: AppTask[]) {
        const actions = computeTaskDeltaActions(currentTasks, this.context.oldTasksMap);
        for (const action of actions) {
            this.context.pushQueue.push(action);
        }
        this.context.updateOldTasksMap(currentTasks);
    }

    private actionHandlers: Record<string, (item: SyncQueueItem) => Promise<void>> = {
        [SyncAction.Create]: async (taskOrEvent) => {
            if (taskOrEvent.type !== SyncType.Task) return;
            const gidResult = await this.tasksAPI.createTask(taskOrEvent.item);
            if (gidResult.isErr()) throw gidResult.error;
            const gid = gidResult.value;
            if (gid) {
                const tasks = repos.tasks.get().unwrapOr(repos.tasks.initial);
                const idx = tasks.findIndex((t) => t.id === taskOrEvent.item.id);
                const t = tasks[idx];
                if (idx !== -1 && t) {
                    const updated = [...tasks];
                    updated[idx] = { ...t, remoteId: gid };
                    repos.tasks.setFromRemote(updated);
                    this.context.updateOldTasksMap(updated);
                } else {
                    const deleteResult = await this.tasksAPI.deleteTask(gid);
                    if (deleteResult.isErr()) throw deleteResult.error;
                }
            }
        },
        [SyncAction.Update]: async (taskOrEvent) => {
            if (taskOrEvent.type !== SyncType.Task) return;
            const tasks = repos.tasks.get().unwrapOr(repos.tasks.initial);
            const currentTask = tasks.find((t) => t.id === taskOrEvent.item.id);
            const gid = currentTask?.remoteId || taskOrEvent.remoteId;

            if (gid) {
                const updateResult = await this.tasksAPI.updateTask(gid, taskOrEvent.item, taskOrEvent.updatedFields);
                if (updateResult.isErr()) throw updateResult.error;
            }
        },
        [SyncAction.Delete]: async (taskOrEvent) => {
            if (taskOrEvent.type !== SyncType.Task) return;
            // If the item doesn't exist locally, tasks.find will be undefined.
            // If deleted locally, we rely on taskOrEvent.remoteId from the queue.
            const gid = taskOrEvent.remoteId;
            
            if (gid) {
                const deleteResult = await this.tasksAPI.deleteTask(gid);
                if (deleteResult.isErr()) throw deleteResult.error;
            }
        }
    };

    processPushItem(taskOrEvent: SyncQueueItem): ResultAsync<void, SyncError> {
        if (taskOrEvent.type !== SyncType.Task) return okAsync(undefined);
        const handler = this.actionHandlers[taskOrEvent.action];
        if (handler) {
            return ResultAsync.fromPromise(
                handler(taskOrEvent),
                e => toSyncError(e)
            );
        }
        return okAsync(undefined);
    }
}

/**
 * These tests exercise the calendar list merging logic that lives inside
 * EventSyncStrategy.fetchRemoteItems().  That logic is responsible for keeping
 * the local `calendars` store in sync with whatever Google Calendar reports.
 *
 * The merge contract:
 *   - Remote is authoritative for: id, summary, accessRole, backgroundColor,
 *     foregroundColor, primary
 *   - Local is authoritative for: active  (the user's visibility toggle)
 *   - Calendars absent from the remote response are dropped from the local store
 *   - New remote calendars default to active: true
 */

import { describe, it, expect } from "vitest";
import type { CalendarData } from "../../store/repositories";

// ---------------------------------------------------------------------------
// Pure extraction of the merge algorithm from EventSyncStrategy.fetchRemoteItems
// ---------------------------------------------------------------------------

type RemoteCalendar = Omit<CalendarData, "active">;

function mergeCalendars(
    remoteList: RemoteCalendar[],
    prevLocal: CalendarData[]
): CalendarData[] {
    return remoteList.map((c) => {
        const prev = prevLocal.find((pc) => pc.id === c.id);
        return {
            id: c.id,
            summary: c.summary,
            ...(c.accessRole !== undefined ? { accessRole: c.accessRole } : {}),
            active: prev ? prev.active : true,
            ...(c.backgroundColor !== undefined ? { backgroundColor: c.backgroundColor } : {}),
            ...(c.foregroundColor !== undefined ? { foregroundColor: c.foregroundColor } : {}),
            ...(c.primary !== undefined ? { primary: c.primary } : {}),
        };
    });
}

// ---------------------------------------------------------------------------
// Baseline
// ---------------------------------------------------------------------------

describe("mergeCalendars — baseline", () => {
    it("returns all remote calendars when local store is empty", () => {
        const remote: RemoteCalendar[] = [
            { id: "c1", summary: "Primary", primary: true },
            { id: "c2", summary: "Work" },
        ];

        const result = mergeCalendars(remote, []);

        expect(result).toHaveLength(2);
        expect(result.every((c) => c.active)).toBe(true);
    });

    it("maps id, summary, accessRole, backgroundColor, foregroundColor, primary from remote", () => {
        const remote: RemoteCalendar[] = [
            {
                id: "c1",
                summary: "Work",
                accessRole: "owner",
                backgroundColor: "#4285f4",
                foregroundColor: "#ffffff",
                primary: true,
            },
        ];

        const [result] = mergeCalendars(remote, []);

        expect(result?.id).toBe("c1");
        expect(result?.summary).toBe("Work");
        expect(result?.accessRole).toBe("owner");
        expect(result?.backgroundColor).toBe("#4285f4");
        expect(result?.foregroundColor).toBe("#ffffff");
        expect(result?.primary).toBe(true);
    });
});

// ---------------------------------------------------------------------------
// Calendar renamed on Google side
// ---------------------------------------------------------------------------

describe("mergeCalendars — remote rename", () => {
    it("updates summary from remote, preserving the active flag", () => {
        const prev: CalendarData[] = [{ id: "c1", summary: "Old Name", active: true }];
        const remote: RemoteCalendar[] = [{ id: "c1", summary: "New Name" }];

        const [result] = mergeCalendars(remote, prev);

        expect(result?.summary).toBe("New Name");
        expect(result?.active).toBe(true);
    });

    it("preserves active: false when a calendar is renamed remotely", () => {
        const prev: CalendarData[] = [{ id: "c1", summary: "Old Name", active: false }];
        const remote: RemoteCalendar[] = [{ id: "c1", summary: "New Name" }];

        const [result] = mergeCalendars(remote, prev);

        expect(result?.summary).toBe("New Name");
        expect(result?.active).toBe(false);
    });

    it("handles simultaneous rename from remote: remote summary always wins", () => {
        // If the user also edits the local calendars store (e.g. future feature),
        // the next poll should overwrite with remote truth.
        const prev: CalendarData[] = [{ id: "c1", summary: "Local Name", active: true }];
        const remote: RemoteCalendar[] = [{ id: "c1", summary: "Remote Name" }];

        const [result] = mergeCalendars(remote, prev);

        expect(result?.summary).toBe("Remote Name");
    });
});

// ---------------------------------------------------------------------------
// Calendar color changed on Google side
// ---------------------------------------------------------------------------

describe("mergeCalendars — remote color change", () => {
    it("picks up new backgroundColor from remote", () => {
        const prev: CalendarData[] = [
            { id: "c1", summary: "Work", active: true, backgroundColor: "#old" },
        ];
        const remote: RemoteCalendar[] = [
            { id: "c1", summary: "Work", backgroundColor: "#4285f4" },
        ];

        const [result] = mergeCalendars(remote, prev);

        expect(result?.backgroundColor).toBe("#4285f4");
    });

    it("picks up new foregroundColor from remote", () => {
        const prev: CalendarData[] = [
            { id: "c1", summary: "Work", active: true, foregroundColor: "#old" },
        ];
        const remote: RemoteCalendar[] = [
            { id: "c1", summary: "Work", foregroundColor: "#ffffff" },
        ];

        const [result] = mergeCalendars(remote, prev);

        expect(result?.foregroundColor).toBe("#ffffff");
    });

    it("clears color if remote omits it (calendar has no color configured)", () => {
        const prev: CalendarData[] = [
            { id: "c1", summary: "Work", active: true, backgroundColor: "#old" },
        ];
        const remote: RemoteCalendar[] = [{ id: "c1", summary: "Work" }];

        const [result] = mergeCalendars(remote, prev);

        expect(result?.backgroundColor).toBeUndefined();
    });
});

// ---------------------------------------------------------------------------
// Calendar deleted on Google side
// ---------------------------------------------------------------------------

describe("mergeCalendars — remote deletion", () => {
    it("drops a calendar that is no longer in the remote list", () => {
        const prev: CalendarData[] = [
            { id: "c1", summary: "Primary", active: true, primary: true },
            { id: "c2", summary: "Work", active: true },
        ];
        const remote: RemoteCalendar[] = [{ id: "c1", summary: "Primary", primary: true }];

        const result = mergeCalendars(remote, prev);

        expect(result).toHaveLength(1);
        expect(result[0]?.id).toBe("c1");
    });

    it("drops multiple deleted calendars in one pass", () => {
        const prev: CalendarData[] = [
            { id: "c1", summary: "A", active: true },
            { id: "c2", summary: "B", active: true },
            { id: "c3", summary: "C", active: true },
        ];
        const remote: RemoteCalendar[] = [{ id: "c2", summary: "B" }];

        const result = mergeCalendars(remote, prev);

        expect(result).toHaveLength(1);
        expect(result[0]?.id).toBe("c2");
    });

    it("results in empty list if remote returns no calendars", () => {
        const prev: CalendarData[] = [{ id: "c1", summary: "Work", active: true }];

        const result = mergeCalendars([], prev);

        expect(result).toHaveLength(0);
    });
});

// ---------------------------------------------------------------------------
// New calendar created on Google side
// ---------------------------------------------------------------------------

describe("mergeCalendars — remote addition", () => {
    it("adds new calendar with active: true", () => {
        const prev: CalendarData[] = [{ id: "c1", summary: "Primary", active: true }];
        const remote: RemoteCalendar[] = [
