import { SyncType, SyncAction } from "./types";
import type { SyncQueueItem } from "./types";
import type { AppEvent } from "../../domain/models";

function getTargetCalendarId(currentEvent: AppEvent, oldEvent: AppEvent): string {
    return currentEvent.remoteCollectionId || oldEvent.remoteCollectionId || "primary";
}

function handleCreation(currentEvent: AppEvent, actions: SyncQueueItem[]) {
    const isValid = !currentEvent.remoteId && currentEvent.title && currentEvent.title.trim() !== "";
    if (isValid)
        actions.push({ type: SyncType.Event, action: SyncAction.Create, item: currentEvent });
}

function getUpdatedFields(currentEvent: AppEvent, oldEvent: AppEvent): (keyof AppEvent)[] {
    const updatedFields: (keyof AppEvent)[] = [];
    for (const k of Object.keys(currentEvent) as (keyof AppEvent)[]) {
        const isIgnored = k === "updatedAt" || k === "etag";
        if (isIgnored) continue;
        
        const isChanged = JSON.stringify(currentEvent[k]) !== JSON.stringify(oldEvent[k]);
        if (isChanged) {
            updatedFields.push(k);
        }
    }
    return updatedFields;
}

function handleUpdateOrMove(
    currentEvent: AppEvent,
    oldEvent: AppEvent,
    actions: SyncQueueItem[]
) {
    const isNewer = currentEvent.updatedAt && oldEvent.updatedAt && currentEvent.updatedAt > oldEvent.updatedAt;
    if (!isNewer) return;

    const targetCalendarId = getTargetCalendarId(currentEvent, oldEvent);
    const isCalendarChange = oldEvent.remoteCollectionId && oldEvent.remoteCollectionId !== targetCalendarId;
    const hasValidTitle = currentEvent.title && currentEvent.title.trim() !== "";

    const updatedFields = getUpdatedFields(currentEvent, oldEvent);

    if (isCalendarChange && oldEvent.remoteId) {
        actions.push({
            type: SyncType.Event,
            action: SyncAction.Move,
            item: currentEvent,
            remoteId: oldEvent.remoteId,
            calendarId: oldEvent.remoteCollectionId,
            destinationCalendarId: targetCalendarId,
            updatedFields
        });

        if (hasValidTitle) {
            actions.push({
                type: SyncType.Event,
                action: SyncAction.Update,
                item: currentEvent,
                remoteId: oldEvent.remoteId,
                calendarId: targetCalendarId,
                updatedFields
            });
        }
        return;
    }

    if (hasValidTitle) {
        const hasRemoteId = currentEvent.remoteId !== undefined;
        actions.push({
            type: SyncType.Event,
            action: SyncAction.Update,
            item: currentEvent,
            ...(hasRemoteId ? { remoteId: currentEvent.remoteId } : {}),
            calendarId: targetCalendarId,
            updatedFields
        });
    }
}

function processSingleEventDelta(
    currentEvent: AppEvent,
    oldEvent: AppEvent | undefined,
    actions: SyncQueueItem[]
) {
    if (currentEvent.type === "log") return;

    if (!oldEvent) {
        handleCreation(currentEvent, actions);
    } else {
        handleUpdateOrMove(currentEvent, oldEvent, actions);
    }
}

export function computeEventDeltaActions(
    currentEvents: AppEvent[],
    oldEventsMap: Map<string, AppEvent>
): SyncQueueItem[] {
    const actions: SyncQueueItem[] = [];
    const currentEventsMap = new Map(currentEvents.map((e) => [e.id, e]));

    for (const event of currentEvents)
        processSingleEventDelta(event, oldEventsMap.get(event.id), actions);

    for (const [id, oldEvent] of oldEventsMap.entries()) {
        if (oldEvent.type === "log") continue;
        if (!currentEventsMap.has(id)) {
            actions.push({
                type: SyncType.Event,
                action: SyncAction.Delete,
                item: oldEvent,
                ...(oldEvent.remoteId !== undefined ? { remoteId: oldEvent.remoteId } : {}),
                calendarId: oldEvent.remoteCollectionId || "primary",
            });
        }
    }

    return actions;
}

import { describe, it, expect, vi, beforeEach } from "vitest";
import { Synchronizer } from "./Synchronizer";
import { EventSyncStrategy } from "./EventSyncStrategy";
import { SyncQueue } from "./SyncQueue";

import type { ISyncEngineContext } from "./types";
import { SyncType, SyncAction } from "./types";
import type { AppEvent, AppTask } from "../../domain/models";
import { DEFAULT_SETTINGS } from "../../store/settingsSchema";
import { FakeCalendarAPI } from "../calendar-api/FakeCalendarAPI";
import { repos } from "../../store/repositories";

describe("Event Sync Engine - Edge Cases (Partial Payload & Merging)", () => {
    let mockContext: ISyncEngineContext;
    let pushQueue: SyncQueue;
    let calendarAPI: FakeCalendarAPI;
    let synchronizer: Synchronizer<AppEvent>;

    beforeEach(() => {
        localStorage.clear();
        pushQueue = new SyncQueue();
        
        mockContext = {
            oldTasksMap: new Map(),
            oldEventsMap: new Map(),
            updateOldTasksMap: vi.fn<(tasks: AppTask[]) => void>(),
            updateOldEventsMap: vi.fn<(events: AppEvent[]) => void>((events: AppEvent[]) => {
                mockContext.oldEventsMap = new Map(events.map(e => [e.id, e]));
            }),
            getSettings: () => ({ ...DEFAULT_SETTINGS, enableCalendarSync: true }),
            pushQueue,
            notifyError: vi.fn<(msg: string) => void>(),
            updateStatus: vi.fn<(problem?: boolean, isSyncing?: boolean) => void>()
        };

        calendarAPI = new FakeCalendarAPI();
        const strategy = new EventSyncStrategy(mockContext, calendarAPI);
        synchronizer = new Synchronizer(mockContext, strategy);
    });

    it("should merge local title edits with remote time edits correctly", async () => {
        // 1. Initial state (synced)
        const t0 = 1000;
        const initialEvent: AppEvent = {
            id: "e1",
            remoteId: "g1",
            remoteCollectionId: "primary",
            title: "Original Title",
            startTime: "2024-01-01T10:00:00",
            endTime: "2024-01-01T11:00:00",
            updatedAt: t0,
            etag: "v1",
            type: "busy"
        };
        repos.events.setFromRemote([initialEvent]);
        mockContext.updateOldEventsMap([initialEvent]);

        // 2. User edits title locally at t1
        const t1 = 2000;
        const localEditedEvent: AppEvent = {
            ...initialEvent,
            title: "Edited Local Title",
            updatedAt: t1
        };
        // The differ would push an update to the queue
        pushQueue.push({
            type: SyncType.Event,
            action: SyncAction.Update,
            item: localEditedEvent,
            remoteId: "g1",
            calendarId: "primary",
            updatedFields: ["title"]
        });

        // 3. Concurrently, someone edits the time remotely at t2
        const t2 = 3000;
        calendarAPI.seedRemoteEvents([{
            id: "g1",
            summary: "Original Title", // Title was not edited remotely
            start: { dateTime: "2024-01-01T12:00:00.000Z" }, // Time WAS edited remotely
            end: { dateTime: "2024-01-01T13:00:00.000Z" },
            extendedProperties: { private: { taskrootEventId: "e1" } },
            updated: new Date(t2).toISOString(),
            etag: "v2"
        }], "primary");

        // 4. Run sync
        await synchronizer.poll();

        // 5. Verify the merged result
        const localEvents = repos.events.get().unwrapOr([]);
        expect(localEvents).toHaveLength(1);
        
        const mergedEvent = localEvents[0];
        
        // The title should be the local edit
        expect(mergedEvent?.title).toBe("Edited Local Title");
        
        // The time should be the remote edit
        // (Note: the mock might parse ISO differently than our floating time, but we test the merging mechanism)
        expect(mergedEvent?.startTime).toBeDefined();
        expect(mergedEvent?.endTime).toBeDefined();
        expect(mergedEvent?.etag).toBe("v2"); // Should have updated to the remote etag
        expect(mergedEvent?.updatedAt).toBeGreaterThanOrEqual(t2);
    });

    it("should merge local status edits with remote notes edits correctly", async () => {
        // 1. Initial state (synced)
        const t0 = 1000;
        const initialEvent: AppEvent = {
            id: "e2",
            remoteId: "g2",
            remoteCollectionId: "primary",
            title: "Event 2",
            description: "Original Notes\nTaskroot Event ID: e2",
            startTime: "2024-01-01T10:00:00",
            endTime: "2024-01-01T11:00:00",
            updatedAt: t0,
            etag: "v1",
            type: "busy"
        };
        repos.events.setFromRemote([initialEvent]);
        mockContext.updateOldEventsMap([initialEvent]);

        // 2. User edits description locally at t1
        const t1 = 2000;
        const localEditedEvent: AppEvent = {
            ...initialEvent,
            description: "Edited Notes\nTaskroot Event ID: e2",
            updatedAt: t1
        };
        
        pushQueue.push({
            type: SyncType.Event,
            action: SyncAction.Update,
            item: localEditedEvent,
            remoteId: "g2",
            calendarId: "primary",
            updatedFields: ["description"]
        });

        // 3. Concurrently, someone edits the time remotely at t2
        const t2 = 3000;
        calendarAPI.seedRemoteEvents([{
            id: "g2",
            summary: "Event 2",
            description: "Original Notes\nTaskroot Event ID: e2",
            start: { dateTime: "2024-01-01T15:00:00" }, // Provide local time directly to avoid timezone shift
            end: { dateTime: "2024-01-01T16:00:00" },
            extendedProperties: { private: { taskrootEventId: "e2" } },
            updated: new Date(t2).toISOString(),
            etag: "v2"
        }], "primary");

        // 4. Poller runs.
        await synchronizer.poll();

        const resultingEvents = repos.events.get().unwrapOr([]);
        expect(resultingEvents).toHaveLength(1);
        const finalEvent = resultingEvents[0];

        expect(finalEvent?.description).toBe("Edited Notes\nTaskroot Event ID: e2");
        expect(finalEvent?.startTime).toBe("2024-01-01T15:00:00");
    });
});

