import React, {
    createContext,
    useState,
    useCallback,
    useEffect,
} from "react";

const DEBOUNCE_DELAY_MS = 600;
const ID_RADIX = 36;
const ID_SUBSTR_START = 2;
const ID_LENGTH = 9;
const NOTIFICATION_TIMEOUT_MS = 5000;
const NOTIFICATION_FLASH_DURATION_MS = 150;



export type NotificationType = "info" | "error" | "success";

interface NotificationData {
    id: string;
    message: string;
    type: NotificationType;
    exiting: boolean;
}

interface NotificationContextType {
    notify: (message: string, type?: NotificationType) => void;
}

export const NotificationContext = createContext<NotificationContextType>({
    notify: () => {},
});



export function useNotification() {
    return React.useContext(NotificationContext);
}

export function NotificationProvider({
    children,
}: {
    children: React.ReactNode;
}) {
    const [notifications, setNotifications] = useState<NotificationData[]>([]);

    const dismiss = useCallback((id: string) => {
        setNotifications((prev) =>
            prev.map((n) => (n.id === id ? { ...n, exiting: true } : n)),
        );

        // Remove from DOM after exit animation completes
        setTimeout(() => {
            setNotifications((prev) => prev.filter((n) => n.id !== id));
        }, DEBOUNCE_DELAY_MS);
    }, []);

    const notify = useCallback(
        (message: string, type: NotificationType = "info") => {
            const id = Math.random().toString(ID_RADIX).substr(ID_SUBSTR_START, ID_LENGTH);
            setNotifications((prev) => [
                ...prev,
                { id, message, type, exiting: false },
            ]);
        },
        [],
    );

    const contextValue = React.useMemo(() => ({ notify }), [notify]);
    
    return (
        <NotificationContext.Provider value={contextValue}>
            {children}
            <div
                style={{
                    position: "fixed",
                    bottom: "24px",
                    right: "24px",
                    display: "flex",
                    flexDirection: "column",
                    alignItems: "flex-end",
                    gap: "12px",
                    zIndex: 9999,
                    pointerEvents: "none", // Let clicks pass through to the app
                }}
            >
                {notifications.map((n) => (
                    <NotificationItem
                        key={n.id}
                        notification={n}
                        onDismiss={() => dismiss(n.id)}
                    />
                ))}
            </div>
        </NotificationContext.Provider>
    );
}

const getColors = (type: NotificationType) => {
    switch (type) {
        case "error":
            return {
                bg: "rgba(220, 38, 38, 0.8)",
                border: "rgba(248, 113, 113, 0.5)",
            };
        case "success":
            return {
                bg: "rgba(22, 163, 74, 0.8)",
                border: "rgba(74, 222, 128, 0.5)",
            };
        default:
            return {
                bg: "rgba(30, 41, 59, 0.8)",
                border: "rgba(71, 85, 105, 0.5)",
            };
    }
};

function NotificationItem({
    notification,
    onDismiss,
}: {
    notification: NotificationData;
    onDismiss: () => void;
}) {
    useEffect(() => {
        if (notification.type !== "error") {
            const timer = setTimeout(() => {
                onDismiss();
            }, NOTIFICATION_TIMEOUT_MS);
            return () => clearTimeout(timer);
        }
        return undefined;
    }, [notification.type, onDismiss]);

    const colors = getColors(notification.type);

    const handleClick = async () => {
        try {
            await navigator.clipboard.writeText(notification.message);
            // Briefly flash the background to indicate successful copy
            const el = document.getElementById(
                `notif-${notification.id}`,
            );
            if (el) {
                const oldBg = el.style.background;
                el.style.background = "rgba(255, 255, 255, 0.2)";
                setTimeout(() => {
                    el.style.background = oldBg;
                }, NOTIFICATION_FLASH_DURATION_MS);
            }
        } catch (err) {
            console.error("Failed to copy notification:", err);
        }
    };

    return (
        <div
            id={`notif-${notification.id}`}
            role="alert"
            style={{
                fontFamily: "inherit",
                textAlign: "left",
                background: colors.bg,
                color: "#ffffff",
                padding: "12px 20px",
                borderRadius: "8px",
                fontSize: "0.95rem",
                fontWeight: 500,
                boxShadow:
                    "0 10px 25px -5px rgba(0, 0, 0, 0.3), 0 8px 10px -6px rgba(0, 0, 0, 0.2)",
                border: `1px solid ${colors.border}`,
                backdropFilter: "blur(8px)",
                WebkitBackdropFilter: "blur(8px)",
                pointerEvents: "auto", // Allow interacting with the notification if needed
                transition: "background 0.15s ease",
                animation: notification.exiting
                    ? "notify-fade-out-left 0.5s ease forwards"
                    : "notify-slide-in-right 0.5s cubic-bezier(0.16, 1, 0.3, 1) forwards",
                maxWidth: "350px",
                wordBreak: "break-word",
                overflow: "hidden",
            }}
        >
            <button
                onClick={handleClick}
                onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault();
                        void handleClick();
                    }
                }}
                title="Click to copy"
                style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    gap: "12px",
                    width: "100%",
                    outline: "none",
                    cursor: "pointer",
                    background: "transparent",
                    border: "none",
                    color: "inherit",
                    padding: 0,
                    fontFamily: "inherit",
                    fontSize: "inherit",
                    textAlign: "left"
                }}
            >
            <span style={{ flex: 1 }}>{notification.message}</span>
            <button
                onClick={(e) => {
                    e.stopPropagation();
                    onDismiss();
                }}
                style={{
                    background: "transparent",
                    border: "none",
                    color: "currentColor",
                    cursor: "pointer",
                    padding: "4px",
