import { describe, it, expect } from "vitest";
import { parseSigils } from "./sigil-parser";

describe("sigil-parser", () => {
    it("extracts priority", () => {
        expect(parseSigils("hello .").properties.priority).toBe(1);
        expect(parseSigils("hello .").cleanTitle).toBe("hello");

        expect(parseSigils("hello ..").properties.priority).toBe(0);
        expect(parseSigils("hello !").properties.priority).toBe(2);
        expect(parseSigils("hello !!").properties.priority).toBe(3);
        expect(parseSigils("hello !!!").properties.priority).toBe(4);
        expect(parseSigils("hello !!!!!").properties.priority).toBe(4);
        
        expect(parseSigils("hello p0").properties.priority).toBe(0);
        expect(parseSigils("hello p4").properties.priority).toBe(4);
    });

    it("respects word boundaries", () => {
        expect(parseSigils("hello.world").properties.priority).toBeUndefined();
        expect(parseSigils("wow!!").cleanTitle).toBe("wow!!"); // Wait, should it parse "wow!!"? The user said "sigils must be either at the start of the string or preceded by whitespace, and followed by whitespace or end-of-string. That's what stops "get milk!!" (excited, not priority) from misparsing."
        expect(parseSigils("get milk!!").properties.priority).toBeUndefined();
        expect(parseSigils("get milk !!").properties.priority).toBe(3);
        expect(parseSigils("get milk !!").cleanTitle).toBe("get milk");
    });

    it("extracts tags", () => {
        const res = parseSigils("buy milk #groceries #urgent");
        expect(res.properties.tags).toEqual(["groceries", "urgent"]);
        expect(res.cleanTitle).toBe("buy milk");
    });

    it("extracts duration", () => {
        expect(parseSigils("do something 1h").properties.duration).toBe(60);
        expect(parseSigils("do something 1hr").properties.duration).toBe(60);
        expect(parseSigils("do something 7m").properties.duration).toBe(7);
        expect(parseSigils("do something for 8m").properties.duration).toBe(8);
        expect(parseSigils("do something in 1h").properties.duration).toBe(60);
        expect(parseSigils("do something for 1h").cleanTitle).toBe("do something");
    });

    it("extracts day and time", () => {
        let res = parseSigils("meeting mon 4pm");
        expect(res.properties.day).toBe("mon");
        expect(res.properties.time).toBe("4pm");
        expect(res.cleanTitle).toBe("meeting");

        res = parseSigils("meeting tom 4pm");
        expect(res.properties.day).toBe("tom");
        expect(res.properties.time).toBe("4pm");
        
        res = parseSigils("meeting 4pm tom");
        expect(res.properties.day).toBe("tom");
        expect(res.properties.time).toBe("4pm");
    });

    it("handles multiple sigils mixed", () => {
        const res = parseSigils("#tag develop taskroot !! tom fri 5pm in 14m");
        expect(res.properties.tags).toEqual(["tag"]);
        expect(res.properties.priority).toBe(3);
        // "tom" and "fri" might both try to set day, usually last one wins or they combine. Let's say last one wins or we combine. "fri" is a day.
        // Wait, "tom" and "fri" are both day sigils.
        expect(res.properties.time).toBe("5pm");
        expect(res.properties.duration).toBe(14);
    });

    it("preserves tokens for highlighting", () => {
        const res = parseSigils("test !! #tag");
        expect(res.tokens).toEqual([
            { type: "text", text: "test " },
            { type: "sigil", text: "!!" },
            { type: "text", text: " " },
            { type: "sigil", text: "#tag" }
        ]);
    });
});

import { MINUTES_IN_HOUR, MS_IN_DAY, DAYS_IN_WEEK } from "./date-utils";

export interface ParsedProperties {
    priority?: number;
    day?: string;
    time?: string;
    duration?: number;
    tags?: string[];
}

export interface Token {
    type: "text" | "sigil";
    text: string;
}

export interface ParseResult {
    cleanTitle: string;
    properties: ParsedProperties;
    tokens: Token[];
}

export function getDueDateFromSigil(day: string, now: Date = new Date()): string {
    const d = day.toLowerCase();
    const today = new Date(now.getTime());
    let addDays = 0;
    
    if (d === 'tom' || d === 'tomorrow') addDays = 1;
    else if (d === 'overmorrow') addDays = 2;
    else {
        const days = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
        const targetIdx = days.indexOf(d);
        if (targetIdx !== -1) {
            const currentIdx = today.getDay();
            addDays = targetIdx - currentIdx;
            if (addDays <= 0) addDays += DAYS_IN_WEEK; // Move to next week if the day has already passed this week
        }
    }
    
    const target = new Date(today.getTime() + addDays * MS_IN_DAY);
    return `${target.getFullYear()}-${(target.getMonth()+1).toString().padStart(2, '0')}-${target.getDate().toString().padStart(2, '0')}`;
}

const PRIORITY_REGEX = /^(?:\.\.|p0|\.|p1|!|p2|!!|p3|!{3,}|p4)$/i;
const DAY_REGEX = /^(?:mon|tue|wed|thu|fri|sat|sun|tom|tomorrow|overmorrow)$/i;
const TIME_REGEX = /^\d{1,2}(?::\d{2})?(?:am|pm)$/i;
const DURATION_REGEX = /^(?:for|in)?\s*(\d+)(h|hr|m)$/i;
const TAG_REGEX = /^#([\w-]+)$/i;

function getPriorityValue(sigil: string): number | undefined {
    const s = sigil.toLowerCase();
    if (s === ".." || s === "p0") return 0;
    if (s === "." || s === "p1") return 1;
    /* eslint-disable no-magic-numbers */
    if (s === "!" || s === "p2") return 2;
    /* eslint-disable no-magic-numbers */
    if (s === "!!" || s === "p3") return 3;
    /* eslint-disable no-magic-numbers */
    if (s.startsWith("!!!") || s === "p4") return 4;
    return 1; // Default priority if unrecognized sigil
}

function processToken(part: string, properties: ParsedProperties): boolean {
    if (PRIORITY_REGEX.test(part)) {
        const val = getPriorityValue(part);
        if (val !== undefined) properties.priority = val;
        return true;
    } else if (DAY_REGEX.test(part)) {
        properties.day = part.toLowerCase();
        return true;
    } else if (TIME_REGEX.test(part)) {
        properties.time = part.toLowerCase();
        return true;
    } else if (DURATION_REGEX.test(part)) {
        const m = part.match(DURATION_REGEX);
        if (m?.[1] && m?.[2]) {
            const val = parseInt(m[1], 10);
            const unit = m[2].toLowerCase();
            properties.duration = unit.startsWith("h") ? val * MINUTES_IN_HOUR : val;
            return true;
        }
    } else if (TAG_REGEX.test(part)) {
        const m = part.match(TAG_REGEX);
        if (m?.[1]) {
            if (!properties.tags) properties.tags = [];
            properties.tags.push(m[1]);
            return true;
        }
    }
    return false;
}

function mergeTextTokens(tokens: Token[]): string {
    return tokens
        .filter(t => t.type === "text")
        .map(t => t.text)
        .join("")
        .replace(/\s+/g, " ")
        .trim();
}

function mergeAdjacentTokens(tokens: Token[]): Token[] {
    const mergedTokens: Token[] = [];
    for (const t of tokens) {
        if (mergedTokens.length > 0 && mergedTokens[mergedTokens.length - 1]?.type === t.type) {
            const lastToken = mergedTokens[mergedTokens.length - 1];
            if (lastToken) lastToken.text += t.text;
        } else {
            mergedTokens.push({ ...t });
        }
    }
    return mergedTokens;
}

function processDurationSigil(parts: string[], i: number, properties: ParsedProperties, tokens: Token[]): boolean {
    const part = parts[i];
    if (!part) return false;
    if (i + 2 < parts.length && (part.toLowerCase() === "for" || part.toLowerCase() === "in")) {
        const nextSpace = parts[i+1] || "";
        const nextWord = parts[i+2] || "";
        const combined = part + nextSpace + nextWord;
        const durMatch = combined.match(DURATION_REGEX);
        if (durMatch?.[0] === combined && durMatch[1] && durMatch[2]) {
            const val = parseInt(durMatch[1], 10);
            const unit = durMatch[2].toLowerCase();
            properties.duration = unit.startsWith("h") ? val * MINUTES_IN_HOUR : val;
            tokens.push({ type: "sigil", text: combined });
            return true;
        }
    }
    return false;
}

export function parseSigils(title: string): ParseResult {
    const properties: ParsedProperties = {};
    const tokens: Token[] = [];
    const parts = title.split(/(\s+)/);
    
    for (let i = 0; i < parts.length; i++) {
        const part = parts[i];
        if (part === undefined) continue;
        if (part.trim() === "") {
            tokens.push({ type: "text", text: part });
            continue;
        }
        
        if (processDurationSigil(parts, i, properties, tokens)) {
            i += 2;
            continue;
        }

        if (processToken(part, properties)) {
            tokens.push({ type: "sigil", text: part });
        } else {
            tokens.push({ type: "text", text: part });
        }
    }
    
    const cleanTitle = mergeTextTokens(tokens);
    const mergedTokens = mergeAdjacentTokens(tokens);

    return { cleanTitle, properties, tokens: mergedTokens };
}

