import type { AppTask, AppEvent } from "../../../core/domain/models";
import { ymd } from "../../../core/store/data";
import { MS_IN_HOUR } from "../../../core/utils/date-utils";

export function sortTasksForSelection(
    pendingTasks: AppTask[],
    events: AppEvent[],
    searchQuery: string
): AppTask[] {
    const todayStr = ymd(new Date());
    const now = new Date();
    const nowMs = now.getTime();
    
    let filtered = pendingTasks;
    if (searchQuery.trim()) {
        const q = searchQuery.toLowerCase();
        filtered = filtered.filter((t) => (t.title || "").toLowerCase().includes(q));
    }

    const safeEvents = events || [];

    return filtered.toSorted((a, b) => {
        const aEvents = safeEvents.filter(
            (e) => e.taskId === a.id && (e.startTime.startsWith(todayStr) || e.endTime.startsWith(todayStr))
        );
        const bEvents = safeEvents.filter(
            (e) => e.taskId === b.id && (e.startTime.startsWith(todayStr) || e.endTime.startsWith(todayStr))
        );

        const aThisHour = aEvents.some(
            (e) => {
                const s = new Date(e.startTime).getTime();
                const en = new Date(e.endTime).getTime();
                return s <= nowMs && (en >= nowMs || s + MS_IN_HOUR >= nowMs);
            }
        );
        const bThisHour = bEvents.some(
            (e) => {
                const s = new Date(e.startTime).getTime();
                const en = new Date(e.endTime).getTime();
                return s <= nowMs && (en >= nowMs || s + MS_IN_HOUR >= nowMs);
            }
        );

        if (aThisHour !== bThisHour) return aThisHour ? -1 : 1;

        const aToday = aEvents.length > 0 || a.due === todayStr;
        const bToday = bEvents.length > 0 || b.due === todayStr;

        if (aToday !== bToday) return aToday ? -1 : 1;

        return (a.title || "").localeCompare(b.title || "");
    });
}

import React from "react";
import type { AppTask } from "../../../core/domain/models";

interface UseTaskSelectorKeyboardProps {
    sortedTasks: AppTask[];
    selectedIndex: number;
    setSelectedIndex: React.Dispatch<React.SetStateAction<number>>;
    setSearchQuery: (query: string) => void;
    startWithTask: (taskId: string) => void;
}

export function useTaskSelectorKeyboard({
    sortedTasks,
    selectedIndex,
    setSelectedIndex,
    setSearchQuery,
    startWithTask,
}: UseTaskSelectorKeyboardProps) {
    const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
        if (e.key === "Enter" && sortedTasks.length > 0) {
            startWithTask(sortedTasks[selectedIndex]?.id || sortedTasks[0]?.id || "");
        } else if (e.key === "Escape") {
            setSearchQuery("");
            e.stopPropagation();
        } else if (e.key === "ArrowDown") {
            e.preventDefault();
            if (sortedTasks.length > 0) {
                setSelectedIndex((prev) => (prev + 1) % sortedTasks.length);
                void import("cuelume").then(({ play }) => play("tick"));
            }
        } else if (e.key === "ArrowUp") {
            e.preventDefault();
            if (sortedTasks.length > 0) {
                setSelectedIndex((prev) => (prev - 1 + sortedTasks.length) % sortedTasks.length);
                void import("cuelume").then(({ play }) => play("tick"));
            }
        }
    };

    return handleKeyDown;
}

export const OPACITY_MUTED = 0.6;

export const OPACITY_FAINT = 0.18;

export const COMPACT_EVENT_HEIGHT_PX = 40;

import React from "react";
import { toFloatingIso, ISO_HM_END } from "../../../core/utils/date-utils";
import { useDistractions, useDistractionStatuses, useDistractionColumns } from "../../../core/store/hooks";
import type { DistractionRow, DistractionStatus, DistractionColumn } from "../../../core/store/repositories";
import { DLogRow } from "./row";
import type { EditingCell } from "./types";
import { colIcon, hexAlpha } from "./utils";






const TRAILING_ACTION_COL_WIDTH = 40;
const MIN_COLUMN_WIDTH = 80;
const ID_RADIX = 36;
const ID_SUFFIX_LENGTH = -4;
const OPACITY_BG = 0.18;
const OPACITY_BORDER = 0.6;

// Distraction log — Notion-like table.
// Resizable columns, inline cell editing, custom status types.

export function DistractionLog() {
    const [rows, setRows] = useDistractions();
    const [statuses, setStatuses] = useDistractionStatuses();
    const [columns, setColumns] = useDistractionColumns();
    const [editingCell, setEditingCell] = React.useState<EditingCell>();
    const [statusEditor, setStatusEditor] = React.useState<string>(); // rowId

    const totalWidth = columns.reduce((sum: number, c: DistractionColumn) => sum + c.width, 0) + TRAILING_ACTION_COL_WIDTH; // for trailing action col

    const updateRow = (id: string, patch: Partial<DistractionRow>) => {
        setRows((rs: DistractionRow[]) => rs.map((r) => (r.id === id ? { ...r, ...patch } : r)));
    };
    const deleteRow = (id: string) => {
        setRows((rs: DistractionRow[]) => rs.filter((r) => r.id !== id));
    };
    const addRow = () => {
        const now = new Date();
        const created = toFloatingIso(now).slice(0, ISO_HM_END);
        const id = `d${Date.now()}`;
        setRows((rs: DistractionRow[]) => [
            ...rs,
            { id, name: "", status: statuses[0]?.id || "", created },
        ]);
        setEditingCell({ rowId: id, colId: "name" });
    };
    const resizeCol = (colId: string, startWidth: number, startX: number) => (e: React.PointerEvent<HTMLSpanElement>) => {
        e.preventDefault();
        const onMove = (ev: PointerEvent) => {
            const dx = ev.clientX - startX;
            const newW = Math.max(MIN_COLUMN_WIDTH, startWidth + dx);
            setColumns((cs: DistractionColumn[]) =>
                cs.map((c) => (c.id === colId ? { ...c, width: newW } : c)),
            );
        };
        const onUp = () => {
            window.removeEventListener("pointermove", onMove);
            window.removeEventListener("pointerup", onUp);
        };
        window.addEventListener("pointermove", onMove);
        window.addEventListener("pointerup", onUp);
    };

    const addStatus = (label: string, color: string) => {
        if (!label) return undefined;
        const id =
            label.toLowerCase().replace(/\s+/g, "-") +
            "-" +
            Date.now().toString(ID_RADIX).slice(ID_SUFFIX_LENGTH);
        setStatuses((ss: DistractionStatus[]) => [...ss, { id, label, color }]);
        return id;
    };

    return (
        <div className="dlog">
            <div className="dlog-scroll">
                <div className="dlog-table" style={{ minWidth: totalWidth }}>
                    {/* Header row */}
                    <div className="dlog-row dlog-row-head">
                        {columns.map((col: DistractionColumn) => (
                            <div
                                key={col.id}
                                className="dlog-cell dlog-cell-head"
                                style={{ width: col.width }}
                            >
                                <span className="dlog-cell-head-icon">
                                    {colIcon(col.type)}
                                </span>
                                <span className="dlog-cell-head-label">
                                    {col.label}
                                </span>
                                <span
                                    className="dlog-col-resize"
                                    onPointerDown={(e) =>
                                        resizeCol(
                                            col.id,
                                            col.width,
                                            e.clientX,
                                        )(e)
                                    }
                                    title="Drag to resize"
                                >
                                    │
                                </span>
                            </div>
                        ))}
                        <div className="dlog-cell dlog-cell-head dlog-cell-actions">
                            <span className="dim">·</span>
                        </div>
                    </div>

                    {/* Data rows */}
                    {rows.length === 0 && (
                        <div className="dlog-row dlog-row-empty">
                            <span className="dim">
                                no distractions logged. nice.
                            </span>
                        </div>
                    )}
                    {rows.map((row: DistractionRow) => (
                        <DLogRow
                            key={row.id}
                            row={row}
                            columns={columns}
                            statuses={statuses}
                            {...(editingCell !== undefined ? { editingCell } : {})}
                            setEditingCell={setEditingCell}
                            {...(statusEditor !== undefined ? { statusEditor } : {})}
                            setStatusEditor={setStatusEditor}
                            updateRow={updateRow}
                            deleteRow={deleteRow}
                            addStatus={addStatus}
                        />
                    ))}

                    {/* Add row */}
                    <button className="dlog-row dlog-row-add" onClick={addRow}>
                        <span className="dlog-add-icon">+</span>
                        <span className="dlog-add-label">add distraction</span>
                    </button>
                </div>
            </div>

            <div className="dlog-foot">
                <span className="dim">
                    {rows.length} {rows.length === 1 ? "row" : "rows"}
                </span>
                <span className="dlog-foot-sep">·</span>
                {statuses.map((s: DistractionStatus) => (
                    <span key={s.id} className="dlog-foot-stat">
                        <span
                            className="status-chip"
                            style={{
                                background: hexAlpha(s.color, OPACITY_BG),
                                color: s.color,
                                borderColor: hexAlpha(s.color, OPACITY_BORDER),
                            }}
                        >
                            {s.label}
                        </span>
                        <span className="dim">
                            {" "}
                            {rows.filter((r: DistractionRow) => r["status"] === s.id).length}
                        </span>
                    </span>
                ))}
                <span className="dlog-foot-spacer" />
                <span className="dim">tip: drag column edges to resize</span>
            </div>
        </div>
    );
}

import type { DistractionRow, DistractionColumn, DistractionStatus } from "../../../core/store/repositories";
import type { EditingCell } from "./types";
import { formatDateTime } from "./utils";
import { StatusCell } from "./status-cell";

export interface DLogRowProps {
    row: DistractionRow;
    columns: DistractionColumn[];
    statuses: DistractionStatus[];
    editingCell?: EditingCell;
    setEditingCell: (cell?: EditingCell) => void;
    statusEditor?: string;
    setStatusEditor: (id?: string) => void;
    updateRow: (id: string, patch: Partial<DistractionRow>) => void;
    deleteRow: (id: string) => void;
    addStatus: (label: string, color: string) => string | undefined;
}

export function DLogRow({
    row,
    columns,
    statuses,
    editingCell,
    setEditingCell,
    statusEditor,
    setStatusEditor,
    updateRow,
    deleteRow,
    addStatus,
}: DLogRowProps) {
    return (
        <div className="dlog-row">
            {columns.map((col: DistractionColumn) => {
                const isEditing =
                    editingCell?.rowId === row.id &&
                    editingCell?.colId === col.id;
                return (
                    <DLogCell
                        key={col.id}
                        col={col}
                        row={row}
                        isEditing={isEditing}
                        setEditingCell={setEditingCell}
                        {...(statusEditor !== undefined ? { statusEditor } : {})}
                        setStatusEditor={setStatusEditor}
                        updateRow={updateRow}
                        statuses={statuses}
                        addStatus={addStatus}
                    />
                );
            })}
            <div className="dlog-cell dlog-cell-actions">
                <button
                    className="dlog-row-x"
                    onClick={(e) => {
                        e.stopPropagation();
                        deleteRow(row.id);
                    }}
                    title="Delete row"
                >
                    ×
                </button>
            </div>
        </div>
    );
}

export interface DLogCellProps {
    col: DistractionColumn;
    row: DistractionRow;
    isEditing: boolean;
    setEditingCell: (cell?: EditingCell) => void;
    statusEditor?: string;
    setStatusEditor: (id?: string) => void;
    updateRow: (id: string, patch: Partial<DistractionRow>) => void;
    statuses: DistractionStatus[];
    addStatus: (label: string, color: string) => string | undefined;
}

function DLogCell({
    col,
    row,
    isEditing,
    setEditingCell,
    statusEditor,
    setStatusEditor,
    updateRow,
    statuses,
    addStatus,
}: DLogCellProps) {
    const val = typeof row[col.id] === "string" ? String(row[col.id]) : undefined;
    return (
        <button
            type="button"
            className={`dlog-cell dlog-cell-${col.type} ${isEditing ? "is-editing" : ""}`}
            style={{ width: col.width, border: "none", background: "none", font: "inherit", color: "inherit", padding: 0, textAlign: "left", cursor: "text" }}
            onClick={() => {
                if (col.type === "text")
                    setEditingCell({ rowId: row.id, colId: col.id });
                else if (col.type === "status")
                    setStatusEditor(row.id);
            }}
        >
            {col.type === "text" && (
                <DLogTextCell 
                    {...(val !== undefined ? { val } : {})}
                    isEditing={isEditing} 
                    rowId={row.id} 
                    colId={col.id} 
                    updateRow={updateRow} 
                    setEditingCell={setEditingCell} 
                />
            )}
            {col.type === "status" && (
                <StatusCell
                    {...(val !== undefined ? { value: val } : {})}
                    statuses={statuses}
                    open={statusEditor === row.id}
                    onClose={() => setStatusEditor(undefined)}
                    onChange={(v: string) => {
                        updateRow(row.id, { [col.id]: v });
                        setStatusEditor(undefined);
                    }}
                    onAdd={(label: string, color: string) => {
                        const newId = addStatus(label, color);
                        if (newId) updateRow(row.id, { [col.id]: newId });
                    }}
                />
            )}
            {col.type === "datetime" && (
                <span className="dlog-datetime">
                    {formatDateTime(val)}
                </span>
            )}
        </button>
    );
}

function DLogTextCell({ 
    val, 
    isEditing, 
    rowId, 
    colId, 
    updateRow, 
    setEditingCell 
}: { 
    val?: string, 
    isEditing: boolean, 
    rowId: string, 
    colId: string, 
    updateRow: (id: string, patch: Partial<DistractionRow>) => void, 
    setEditingCell: (cell?: EditingCell) => void 
}) {
    if (isEditing) {
        return (
            <input
                ref={(r) => { if (r) r.focus(); }}
                className="dlog-cell-input"
                defaultValue={val || ""}
                onBlur={(e) => {
                    updateRow(rowId, { [colId]: e.target.value });
                    setEditingCell(undefined);
                }}
                onKeyDown={(e) => {
                    if (e.key === "Enter" && e.currentTarget instanceof HTMLElement) {
                        e.currentTarget.blur();
                    }
                    if (e.key === "Escape" && e.currentTarget instanceof HTMLElement) {
                        e.currentTarget.blur();
                        setEditingCell(undefined);
                    }
                }}
            />
        );
    }
    return val ? <>{val}</> : <span className="dim">click to edit</span>;
}

import React from "react";
import type { DistractionStatus } from "../../../core/store/repositories";
import { hexAlpha } from "./utils";

const OPACITY_SELECTED_BG = 0.22;
const OPACITY_BG = 0.18;
const OPACITY_BORDER = 0.6;



export interface StatusCellProps {
    value?: string;
    statuses: DistractionStatus[];
    open: boolean;
    onClose: () => void;
    onChange: (v: string) => void;
    onAdd: (label: string, color: string) => void;
}

export function StatusCell({
    value,
    statuses,
    open,
    onClose,
    onChange,
    onAdd,
}: StatusCellProps) {
    const current = statuses.find((s) => s.id === value);
    const popRef = React.useRef<HTMLDivElement>(null);
    const [addingStatus, setAddingStatus] = React.useState(false);
    const [newLabel, setNewLabel] = React.useState("");
    const [newColor, setNewColor] = React.useState("var(--tag-purple)");

    React.useEffect(() => {
        if (!open) return undefined;
        const onDoc = (e: PointerEvent) => {
            if (popRef.current && !(e.target instanceof Node && popRef.current.contains(e.target))) onClose();
        };
        setTimeout(() => document.addEventListener("pointerdown", onDoc), 0);
        return () => document.removeEventListener("pointerdown", onDoc);
    }, [open, onClose]);

    return (
        <>
            <span
                className="status-chip"
                style={
                    current
                        ? {
                              background: hexAlpha(current.color, OPACITY_BG),
                              color: current.color,
                              borderColor: hexAlpha(current.color, OPACITY_BORDER),
                          }
                        : { color: "var(--fg-dim)" }
                }
            >
                {current ? current.label : <span className="dim">select…</span>}
            </span>
            {open && (
                <div
                    className="dlog-status-pop"
                    ref={popRef}
                    role="presentation"
                    onPointerDown={(e) => e.stopPropagation()}
                >
                    {statuses.map((s: DistractionStatus) => (
                        <button
                            key={s.id}
                            className="dlog-status-opt"
                            onClick={() => onChange(s.id)}
                        >
                            <span
                                className="status-chip"
                                style={{
                                    background: hexAlpha(s.color, OPACITY_BG),
                                    color: s.color,
                                    borderColor: hexAlpha(s.color, OPACITY_BORDER),
                                }}
                            >
                                {s.label}
                            </span>
                        </button>
                    ))}
                    <div className="dlog-status-sep">─ ─ ─ ─ ─ ─ ─ ─ ─</div>
                    {addingStatus ? (
                        <div className="dlog-status-new">
                            <input
                                ref={(r) => { if (r && addingStatus) r.focus(); }}
                                className="dlog-status-new-input"
                                placeholder="status name…"
                                value={newLabel}
                                onChange={(e) => setNewLabel(e.target.value)}
                                onKeyDown={(e) => {
                                    if (e.key === "Enter") {
                                        onAdd(newLabel.trim(), newColor);
                                        setNewLabel("");
                                        setAddingStatus(false);
                                    } else if (e.key === "Escape") {
                                        setAddingStatus(false);
                                        setNewLabel("");
                                    }
                                }}
                            />
                            <div className="dlog-status-colors">
                                {[
                                    "var(--tag-red)",
                                    "var(--tag-yellow)",
