import { MONTHS } from "../../../core/store/data";

export const MAX_DISPLAY_ITEMS = 6;
export const DRAG_THRESHOLD_PX = 4;
const HEX_R_START = 0;
const HEX_R_END = 2;
const HEX_G_START = 2;
const HEX_G_END = 4;
const HEX_B_START = 4;
const HEX_B_END = 6;


export function colIcon(type: string) {
    return ({ text: "A", status: "◐", datetime: "◷" })[type] || "·";
}

export function formatDateTime(s?: string) {
    if (!s) return "";
    const [date, time] = s.split("T");
    if (!date) return "";
    const [, m, d] = date.split("-");
    if (!m || !d) return "";
    return `${MONTHS[parseInt(m, 10) - 1]?.toLowerCase() || ""} ${parseInt(d, 10)} · ${time || ""}`;
}

export function hexAlpha(hex: string, alpha: number) {
    const h = hex.replace("#", "");
    const r = parseInt(h.slice(HEX_R_START, HEX_R_END), 16);
    const g = parseInt(h.slice(HEX_G_START, HEX_G_END), 16);
    const b = parseInt(h.slice(HEX_B_START, HEX_B_END), 16);
    return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

import React from "react";
import { durationLabel } from "../../core/store/data";
import { useTasks } from "../../core/store/hooks";
import { type AppTask, isAppTaskStatus } from "../../core/domain/models";

// Kanban board — pulls tasks from the shared store, drag between columns to change status.

const KANBAN_COLUMNS = [
    { id: "todo", label: "todo", dim: false },
    { id: "next-up", label: "next up", dim: false },
    { id: "doing", label: "active", accent: true },
    { id: "done", label: "done", dim: true },
];

const DRAG_START_THRESHOLD_PX = 5;
const GHOST_OFFSET_X = 12;
const GHOST_OFFSET_Y = 6;

export function Kanban() {
    const [tasks, setTasks] = useTasks();
    const [drag, setDrag] = React.useState<{ taskId: string; x: number; y: number; overCol?: string }>();

    const onTaskDown = (task: AppTask) => (e: React.PointerEvent<HTMLDivElement>) => {
        if (e.button !== 0) return;
        e.preventDefault();
        const start = { x: e.clientX, y: e.clientY };
        let active = false;
        const move = (ev: PointerEvent) => {
            if (
                !active &&
                Math.hypot(ev.clientX - start.x, ev.clientY - start.y) < DRAG_START_THRESHOLD_PX
            )
                return;
            active = true;
            const el = document.elementFromPoint(ev.clientX, ev.clientY);
            const colEl = el instanceof Element ? el.closest("[data-kanban-col]") : undefined;
            const overCol = colEl instanceof HTMLElement ? colEl.dataset?.["kanbanCol"] : undefined;
            setDrag({
                taskId: task.id,
                x: ev.clientX,
                y: ev.clientY,
                ...(overCol !== undefined ? { overCol } : {})
            });
        };
        const up = (ev: PointerEvent) => {
            window.removeEventListener("pointermove", move);
            window.removeEventListener("pointerup", up);
            if (active) {
                const el = document.elementFromPoint(ev.clientX, ev.clientY);
                const colEl = el instanceof Element ? el.closest("[data-kanban-col]") : undefined;
                const newStatus = colEl instanceof HTMLElement ? colEl.dataset["kanbanCol"] : undefined;
                if (
                    newStatus !== task.status &&
                    isAppTaskStatus(newStatus)
                ) {
                    setTasks((ts: AppTask[]) =>
                        ts.map((t) =>
                            t.id === task.id
                                ? {
                                      ...t,
                                      status: newStatus,
                                  }
                                : t,
                        ),
                    );
                }
            }
            setDrag(undefined);
        };
        window.addEventListener("pointermove", move);
        window.addEventListener("pointerup", up);
    };

    return (
        <div className="kanban">
            <div className="kanban-cols">
                {KANBAN_COLUMNS.map((col) => {
                    const colTasks = tasks.filter((t) => t.status === col.id);
                    const isOver = drag?.overCol === col.id;
                    return (
                        <div
                            key={col.id}
                            data-kanban-col={col.id}
                            className={`kanban-col ${col.accent ? "is-accent" : ""} ${col.dim ? "is-dim" : ""} ${isOver ? "is-drag-over" : ""}`}
                        >
                            <header className="kanban-col-hd">
                                <span className="bracket">
                                    {col.accent ? "▸" : "◇"}
                                </span>
                                <span className="kanban-col-name">
                                    {col.label}
                                </span>
                                <span className="kanban-col-count">
                                    {colTasks.length}
                                </span>
                            </header>
                            <div className="kanban-col-body">
                                {colTasks.length === 0 ? (
                                    <div className="kanban-col-empty">
                                        <span className="dim">
                                            {isOver ? "▸ drop here" : "—"}
                                        </span>
                                    </div>
                                ) : (
                                    colTasks.map((task) => (
                                        <KanbanCard
                                            key={task.id}
                                            task={task}
                                            onPointerDown={onTaskDown(task)}
                                            dragging={drag?.taskId === task.id}
                                        />
                                    ))
                                )}
                            </div>
                        </div>
                    );
                })}
            </div>

            {drag && (
                <div
                    className="kanban-ghost"
                    style={{ left: drag.x + GHOST_OFFSET_X, top: drag.y - GHOST_OFFSET_Y }}
                >
                    <div
                        className={`task-circle pri-bg-${tasks.find((t) => t.id === drag.taskId)?.priority}`}
                    />
                    <span className="kanban-ghost-title">
                        {tasks.find((t) => t.id === drag.taskId)?.title}
                    </span>
                </div>
            )}
        </div>
    );
}

function KanbanCard({ task, onPointerDown, dragging }: { task: AppTask; onPointerDown: (e: React.PointerEvent<HTMLDivElement>) => void; dragging: boolean }) {
    return (
        <div
            className={`kanban-card ${dragging ? "is-dragging" : ""}`}
            onPointerDown={onPointerDown}
        >
            <div className="kanban-card-line1">
                <div className={`task-circle pri-bg-${task.priority}`} />
                <span className="kanban-card-title">{task.title}</span>
            </div>
            <div className="kanban-card-line2">
                <span className="meta-est">{durationLabel(task.est || 0)}</span>
                {task.tags && task.tags.length > 0 && (
                    <>
                        <span className="meta-sep">·</span>
                        <span className="meta-tag">#{task.tags[0]}</span>
                        {task.tags.length > 1 && (
                            <span className="dim">+{task.tags.length - 1}</span>
                        )}
                    </>
                )}
                {task.subtasks && task.subtasks.length > 0 && (
                    <>
                        <span className="meta-sep">·</span>
                        <span className="meta-subtasks">
                            ☐{task.subtasks.filter((s) => s.done).length}/
                            {task.subtasks.length}
                        </span>
                    </>
                )}
            </div>
        </div>
    );
}

import React from "react";
