function RestChecklist({ state }: { state: ReturnType<typeof useRestChecklistState> }) {
    return (
        <ol className="rest-list">
            {state.items.map((item) => (
                <li
                    key={item.id}
                    className={`rest-item ${state.checked[item.id] ? "is-checked" : ""}`}
