import { MS_PER_SECOND } from "../../../core/utils/constants";
import { expect, test, describe } from "vitest";
import { CLOCK_STRATEGIES } from "../../../core/domain/clock-strategies";
import { createWorkSessionEvent } from "../../../core/domain/clock-strategies/utils";
import type { ReadonlyStopwatchContext } from "../../../core/domain/clock-strategies/types";


function createMockContext(overrides: Partial<ReadonlyStopwatchContext>): ReadonlyStopwatchContext {
    return {
        currentMs: 0,
        running: false,
        isPristine: true,
        state: { runningSince: undefined, elapsed: 0, isBreak: false, breakAllowedMs: 0, breakStartedAt: undefined, breakSoundPlayed: false },

        allowNoTask: false,
        settings: {},
        ...overrides
    };
}

describe("createWorkSessionEvent", () => {
    test("ignores sessions less than 1 minute", () => {
        const ev = createWorkSessionEvent(MS_PER_SECOND, MS_PER_SECOND * 2, "task1", "counter");
        expect(ev).toBeUndefined();
    });

    test("logs sessions 1 minute or longer", () => {
        const ev = createWorkSessionEvent(MS_PER_SECOND, 62000, "task1", "counter");
        expect(ev).not.toBeUndefined();
        expect(ev?.taskId).toBe("task1");
        expect(ev?.["clockStyle"]).toBe("counter");
    });
});

describe("CounterClockStrategy", () => {
    const strategy = CLOCK_STRATEGIES["counter"];

    test("requiresAnimationLoop when running", () => {
        if (!strategy) throw new Error();
        expect(
            strategy.requiresAnimationLoop(createMockContext({ running: true, state: { runningSince: 123, elapsed: 0, isBreak: false, breakAllowedMs: 0, breakStartedAt: undefined, breakSoundPlayed: false } })),
        ).toBe(true);
        expect(
            strategy.requiresAnimationLoop(createMockContext({ running: false, state: { runningSince: undefined, elapsed: 0, isBreak: false, breakAllowedMs: 0, breakStartedAt: undefined, breakSoundPlayed: false } })),
        ).toBe(false);
    });

    test("calculateToggle toggles state", () => {
        if (!strategy) throw new Error();
        // Start
        const effect1 = strategy.calculateToggle(createMockContext({
            isPristine: true,
            activeTask: { id: "t1", title: "Task" },
        }));
        expect(effect1.newState?.runningSince).toBeTypeOf("number");

        // Stop
        const effect2 = strategy.calculateToggle(createMockContext({
            isPristine: false,
            running: true,
            state: { elapsed: 1000, runningSince: 1000, isBreak: false, breakAllowedMs: 0, breakStartedAt: undefined, breakSoundPlayed: false },
            activeTask: { id: "t1", title: "Task" },
        }));
        expect(effect2.newState?.runningSince).toBeUndefined();
    });
});

describe("FlowtimeClockStrategy", () => {
    const strategy = CLOCK_STRATEGIES["flowtime"];

    test("calculateToggle prevents pause during break", () => {
        if (!strategy) throw new Error();
        const effect = strategy.calculateToggle(createMockContext({
            isPristine: false,
            running: false,
            state: { elapsed: 100, runningSince: undefined, isBreak: true, breakAllowedMs: 0, breakStartedAt: 0, breakSoundPlayed: false },
        }));
        expect(effect.newState).toBeUndefined(); // Should return no state modifications
    });
});

describe("GuzeyClockStrategy", () => {
    const strategy = CLOCK_STRATEGIES["guzey"];

    test("requiresAnimationLoop is true", () => {
        if (!strategy) throw new Error();
        expect(strategy.requiresAnimationLoop(createMockContext({ running: true, state: { runningSince: 1000, elapsed: 0, isBreak: false, breakAllowedMs: 0, breakStartedAt: undefined, breakSoundPlayed: false } }))).toBe(true);
    });
});

import { useState, useEffect, useRef } from "react";
import { useEvents, useStopwatch } from "../../../core/store/hooks";
import { TaskSelector } from "../TaskSelector";
import { useStopwatchKeyboard } from "./useStopwatchKeyboard";
import { ActiveTaskDisplay } from "./ActiveTaskDisplay";
import { useStopwatchEngine } from "./useStopwatchEngine";
import type { ReadonlyStopwatchContext } from "../../../core/domain/clock-strategies/types";
import type { ClockStrategy } from "../../../core/domain/clock-strategies/ClockStrategy";

function StopwatchDisplay({
    context,
    strategy,
    toggle,
}: {
    context: ReadonlyStopwatchContext;
    strategy: ClockStrategy;
    toggle: () => void;
}) {
    const [, setTick] = useState(0);

    // While running, request animation frame to update display tick
    useEffect(() => {
        let raf: number;
        const loop = () => {
            setTick((t) => t + 1);
            raf = requestAnimationFrame(loop);
        };
        if (strategy.requiresAnimationLoop(context)) {
            raf = requestAnimationFrame(loop);
        }
        return () => {
            if (raf) cancelAnimationFrame(raf);
        };
    }, [strategy, context.state.runningSince, context.state.isBreak, context]);

    // Recalculate display data on every tick or context change
    const dynamicCurrentMs =
        context.state.elapsed +
        (context.running && !context.state.isBreak ? Date.now() - (context.state.runningSince || 0) : 0);
    
    const displayContext = { ...context, currentMs: dynamicCurrentMs };
    const data = strategy.getDisplayData(displayContext);

    return (
        <button
            type="button"
            aria-label="Toggle stopwatch"
            className={`stopwatch-display ${context.running ? "is-running" : ""} ${context.isPristine ? "is-pristine" : ""}`}
            onClick={toggle}
            title="Click to start/stop"
            style={{ color: data.color || "inherit" }}
        >
            <span className={`sw-digits sw-m ${data.secondaryText ? "col" : "row"}`}>
                {data.showPlayIcon ? (
                    <svg
                        width="0.8em"
                        height="0.8em"
                        viewBox="0 0 24 24"
                        fill="currentColor"
                        xmlns="http://www.w3.org/2000/svg"
                        className="sw-play-icon"
                    >
                        <path d="M8 5v14l11-7z" />
                    </svg>
                ) : (
                    <>
                        {data.secondaryText && (
                            <span className="sw-secondary-text">{data.secondaryText}</span>
                        )}
                        <span className={`sw-primary-text ${data.secondaryText ? "has-secondary" : ""}`}>
                            {data.primaryText}
                        </span>
                    </>
                )}
            </span>
        </button>
    );
}

export function Stopwatch({ onBreakStatusChange }: { onBreakStatusChange?: (status: boolean) => void }) {
    const [selectorOpen, setSelectorOpen] = useState(false);
    const [events] = useEvents();

    const {
        state,
        running,
        allowNoTask,
        activeTask,
        settings,
        tasks,
        strategy,
        context,
        actions
    } = useStopwatchEngine(setSelectorOpen);

    const [, setRealStopwatchState] = useStopwatch();

    const audioRef = useRef<HTMLAudioElement | null>(null);
    if (!audioRef.current) {
        audioRef.current = new Audio("/wine-glass-alarm.ogg");
    }

    useEffect(() => {
        if (!activeTask && !allowNoTask) {
            setSelectorOpen(true);
        }
    }, [activeTask, allowNoTask]);

    useEffect(() => {
        let interval: NodeJS.Timeout;
        if (state.isBreak && state.breakStartedAt && !state.breakSoundPlayed) {
            const ONE_SECOND_MS = 1000;
            interval = setInterval(() => {
                if (state.breakStartedAt && Date.now() - state.breakStartedAt >= state.breakAllowedMs) {
                    audioRef.current
                        ?.play()
                        .catch((e) => console.error("Sound play failed", e));
                    setRealStopwatchState((s) => ({ ...s, breakSoundPlayed: true }));
                }
            }, ONE_SECOND_MS);
        }
        return () => {
            if (interval) clearInterval(interval);
        };
    }, [state.isBreak, state.breakStartedAt, state.breakAllowedMs, state.breakSoundPlayed, setRealStopwatchState]);

    const displayData = strategy.getDisplayData(context);
    useEffect(() => {
        if (onBreakStatusChange && displayData.isBreak !== undefined) {
            onBreakStatusChange(displayData.isBreak);
        }
    }, [displayData.isBreak, onBreakStatusChange]);

    useStopwatchKeyboard({ selectorOpen, setSelectorOpen, actions, ...(activeTask !== undefined ? { activeTask } : {}), allowNoTask });

    return (
        <section className="stopwatch-hero">
            <div className="stopwatch-stage" style={{ position: "relative" }}>
                <StopwatchDisplay context={context} strategy={strategy} toggle={actions.toggle} />

                { (running || settings.clockStyle === "guzey" || state.isBreak) && (activeTask || allowNoTask) && (
                    <ActiveTaskDisplay
                        {...(activeTask !== undefined ? { activeTask } : {})}
                        setSelectorOpen={setSelectorOpen}
                    />
                )}

                <TaskSelector
                    selectorOpen={selectorOpen}
                    setSelectorOpen={setSelectorOpen}
                    tasks={tasks || []}
                    events={events || []}
                    {...(activeTask !== undefined ? { activeTask } : {})}
                    allowNoTask={allowNoTask}
                    startWithTask={actions.startWithTask}
                />
            </div>
        </section>
    );
}

import React, { useCallback } from "react";
import { useTasks, useStopwatch, useTimeLogs, useSettings } from "../../../core/store/hooks";
import { CLOCK_STRATEGIES } from "../../../core/domain/clock-strategies";
import type { AppTask } from "../../../core/domain/models";
import type { ReadonlyStopwatchContext, ClockActionEffect } from "../../../core/domain/clock-strategies/types";
import { createWorkSessionEvent } from "../../../core/domain/clock-strategies/utils";
export const MIN_POLL_INTERVAL_MINUTES = 5;

const updateTaskStatus = (ts: AppTask[], taskId: string): AppTask[] => 
    ts.map(t => t.id === taskId ? { ...t, status: "doing" } : t.status === "doing" ? { ...t, status: "todo" } : t);

export function useStopwatchEngine(setSelectorOpen: (val: boolean) => void) {
    const [state, setState] = useStopwatch();
    const [tasks, setTasks] = useTasks();
    const [settings] = useSettings();
    const [, setTimeLogs] = useTimeLogs();

    const strategy = CLOCK_STRATEGIES[settings.clockStyle || "counter"] || CLOCK_STRATEGIES["counter"];
    if (!strategy) throw new Error("Missing clock strategy");

    const running = state.runningSince !== undefined;
    const currentMs = state.elapsed + (running && !state.isBreak ? Date.now() - (state.runningSince || 0) : 0);
    const isPristine = currentMs === 0 && !running && !state.isBreak;
    const activeTask = tasks?.find((t: AppTask) => t.status === "doing");
    const allowNoTask = settings.allowStopwatchWithoutTask || false;

    const context: ReadonlyStopwatchContext = React.useMemo(() => ({
        state,
        currentMs,
        isPristine,
        running,
        ...(activeTask !== undefined ? { activeTask } : {}),
        allowNoTask,
        settings
    }), [state, currentMs, isPristine, running, activeTask, allowNoTask, settings]);

    const applyEffect = useCallback((effect: ClockActionEffect) => {
        if (effect.shouldLogSession && state.runningSince) {
            const ev = createWorkSessionEvent(
                state.runningSince,
                Date.now(),
                activeTask?.id,
                settings.clockStyle || "counter"
            );
            if (ev) {
                setTimeLogs((logs) => [...(logs || []), ev]);
            }
        }
        if (effect.newState) {
            setState((s) => ({ ...s, ...effect.newState }));
        }
        if (effect.selectorOpen !== undefined) {
            setSelectorOpen(effect.selectorOpen);
        }
    }, [state, activeTask, settings, setTimeLogs, setState, setSelectorOpen]);

    const toggle = useCallback(() => {
        const effect = strategy.calculateToggle(context);
        applyEffect(effect);
    }, [strategy, context, applyEffect]);

    const reset = useCallback(() => {
        const effect = strategy.calculateReset(context);
        applyEffect(effect);
    }, [strategy, context, applyEffect]);

    const startWithTask = useCallback((taskId: string) => {
        setTasks((ts: AppTask[]) => updateTaskStatus(ts, taskId));
        applyEffect(strategy.calculateTaskSelected(context));
    }, [strategy, context, applyEffect, setTasks]);

    const startBreak = useCallback(() => {
        if (strategy.calculateStartBreak) applyEffect(strategy.calculateStartBreak(context));
    }, [strategy, context, applyEffect]);

    return {
        state,
        currentMs,
        isPristine,
        running,
        activeTask,
        allowNoTask,
        settings,
        tasks,
        strategy,
        context,
        actions: { toggle, reset, startWithTask, startBreak }
    };
}

import { useEffect } from "react";
import type { AppTask } from "../../../core/domain/models";

export interface StopwatchActions {
    toggle: () => void;
    reset: () => void;
    startBreak: () => void;
}

const isInputTarget = (target: EventTarget | null) => {
    return target instanceof Element && target.matches(
        "input:not(.task-search-input), textarea, [contenteditable]",
    );
};

export interface StopwatchKeyboardOptions {
    selectorOpen: boolean;
    setSelectorOpen: (val: boolean | ((prev: boolean) => boolean)) => void;
    actions: StopwatchActions;
    activeTask?: AppTask;
    allowNoTask: boolean;
}

export function useStopwatchKeyboard(options: StopwatchKeyboardOptions) {
    const { selectorOpen, setSelectorOpen, actions, activeTask, allowNoTask } = options;
    useEffect(() => {
        const onKey = (e: KeyboardEvent) => {
            if (isInputTarget(e.target)) return;

            const isModifier = e.metaKey || e.ctrlKey;

            switch (e.code) {
                case "Space":
                    if (!selectorOpen) {
                        e.preventDefault();
                        actions.toggle();
                    }
                    break;
                case "KeyR":
                    if (isModifier) {
                        e.preventDefault();
                        actions.reset();
                    }
                    break;
                case "Enter":
                    if (isModifier) {
                        e.preventDefault();
                        setSelectorOpen((prev: boolean) => !prev);
                    }
                    break;
                case "Escape":
                    if (selectorOpen && (activeTask || allowNoTask)) {
                        e.preventDefault();
                        setSelectorOpen(false);
                    }
                    break;
            }
        };

        const pressed = new Set<string>();
        const handleDown = (e: KeyboardEvent) => {
            if (isInputTarget(e.target)) return;
            pressed.add(e.code);
            if (pressed.has("ShiftLeft") && pressed.has("ShiftRight")) {
                e.preventDefault();
                actions.startBreak();
            }
        };
        const handleUp = (e: KeyboardEvent) => {
            pressed.delete(e.code);
        };

        window.addEventListener("keydown", handleDown);
        window.addEventListener("keyup", handleUp);
        window.addEventListener("keydown", onKey);
        return () => {
            window.removeEventListener("keydown", handleDown);
            window.removeEventListener("keyup", handleUp);
            window.removeEventListener("keydown", onKey);
        };
    }, [selectorOpen, activeTask, allowNoTask, actions, setSelectorOpen]);
}

import React from "react";
import type { AppNote } from "../../core/domain/models";

import { useNotes, useTips } from "../../core/store/hooks";

const TIP_DURATION_MS = 2200;

// Tips list + Notes (Obsidian placeholder)

export function TipsList() {
    const [tips, setTips] = useTips();
    const [adding, setAdding] = React.useState(false);
    const [draft, setDraft] = React.useState("");

    const add = () => {
        const t = draft.trim();
        if (!t) {
            setAdding(false);
            return;
        }
        setTips((ts) => [...ts, t]);
        setDraft("");
        setAdding(false);
    };

    return (
        <ul className="tips-list">
            {tips.map((tip, i) => (
                <li key={tip} className="tips-row">
                    <span className="tips-bullet">·</span>
                    <span className="tips-text">{tip}</span>
                    <button
                        className="tips-x"
                        onClick={() =>
                            setTips((ts) => ts.filter((_, j) => j !== i))
                        }
                        title="Remove"
                    >
                        ×
                    </button>
                </li>
            ))}
            <li className="tips-row tips-row-add">
                <span className="tips-bullet">+</span>
                {adding ? (
                    <input
                        ref={(r) => { if (r && adding) r.focus(); }}
                        className="tips-input"
                        placeholder="add a tip…"
                        value={draft}
                        onChange={(e) => setDraft(e.target.value)}
                        onBlur={add}
                        onKeyDown={(e) => {
                            if (e.key === "Enter") add();
                            if (e.key === "Escape") {
                                setAdding(false);
                                setDraft("");
                            }
                        }}
                    />
                ) : (
                    <button
                        className="tips-add-btn"
                        onClick={() => setAdding(true)}
                    >
                        add a tip
                    </button>
                )}
            </li>
        </ul>
    );
}

export function NotesList() {
    const [notes, setNotes] = useNotes();
    const [toast, setToast] = React.useState<string>();
    const [adding, setAdding] = React.useState(false);
    const [draft, setDraft] = React.useState("");

    const openInObsidian = (note: AppNote) => {
        // Mocked — would normally fire obsidian:// deep link
        setToast(`would open obsidian://${note.vault}/${note.path}`);
        setTimeout(() => setToast(undefined), TIP_DURATION_MS);
    };
    const remove = (id: string) => setNotes((ns) => ns.filter((n) => n.id !== id));
    const addNote = () => {
        const title = draft.trim();
        if (!title) {
            setAdding(false);
            return;
        }
        const id = `n${Date.now()}`;
        setNotes((ns) => [
            ...ns,
            {
                id,
                title,
                vault: "work",
                path: `${title.toLowerCase().replace(/\s+/g, "-")}.md`,
            },
        ]);
        setDraft("");
        setAdding(false);
    };

    return (
        <div className="notes">
            <ul className="notes-list">
                {notes.map((n) => (
                    <li key={n.id} className="notes-row">
                        <button
                            className="notes-link"
                            onClick={() => openInObsidian(n)}
                        >
                            <span className="notes-icon">◈</span>
                            <span className="notes-title">{n.title}</span>
                            <span className="notes-path">
                                obsidian://{n.vault}/{n.path}
                            </span>
                            <span className="notes-arrow">↗</span>
                        </button>
                        <button
                            className="notes-x"
                            onClick={() => remove(n.id)}
                            title="Remove"
                        >
                            ×
                        </button>
                    </li>
                ))}
                <li className="notes-row notes-row-add">
                    {adding ? (
                        <div
                            style={{
                                display: "flex",
                                width: "100%",
                                alignItems: "center",
                                padding: "6px 4px",
                                gap: "10px",
                            }}
                        >
                            <span className="notes-icon">+</span>
                            <input
                                ref={(r) => { if (r && adding) r.focus(); }}
                                className="tips-input"
                                placeholder="note title…"
                                value={draft}
                                onChange={(e) => setDraft(e.target.value)}
                                onBlur={addNote}
                                onKeyDown={(e) => {
                                    if (e.key === "Enter") addNote();
                                    if (e.key === "Escape") {
                                        setAdding(false);
                                        setDraft("");
                                    }
                                }}
                            />
                        </div>
                    ) : (
                        <button
                            className="notes-add-btn"
                            onClick={() => setAdding(true)}
                        >
                            <span className="notes-icon">+</span> add note
                        </button>
                    )}
                </li>
            </ul>
            {toast && (
                <div className="notes-toast">
                    <span className="bracket">▸</span> {toast}
                    <span className="dim">
                        {" "}
                        (placeholder — not actually opening)
                    </span>
                </div>
            )}
        </div>
    );
}

import Markdown from 'react-markdown';
import { useLocation, Link } from 'react-router-dom';
import { useMemo } from 'react';

const docs: Record<string, string> = import.meta.glob('../../../docs/*.md', { query: '?raw', import: 'default', eager: true });

function LinkRenderer({ href, children, ...rest }: React.AnchorHTMLAttributes<HTMLAnchorElement>) {
    if (href?.startsWith('./')) {
        return <Link to={`/docs/${href.replace('./', '')}`} {...rest}>{children}</Link>;
    }
    if (href?.startsWith('/docs/')) {
        return <Link to={href} {...rest}>{children}</Link>;
    }
    return <a href={href} target="_blank" rel="noreferrer" {...rest}>{children}</a>;
}

export function DocsScreen() {
    const location = useLocation();

    const currentDoc = useMemo(() => {
        let path = location.pathname.replace('/docs', '');
        if (path.startsWith('/')) path = path.slice(1);
        if (!path) path = 'index.md';
        
        const key = `../../../docs/${path}`;
        if (typeof docs[key] === "string") {
            return docs[key];
        }
        return `# 404\nDocument not found.`;
    }, [location.pathname]);

    return (
        <div
            className="main"
            style={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                padding: "2rem",
                overflowY: "auto",
                color: "var(--fg)",
            }}
        >
            <div style={{ maxWidth: "800px", width: "100%", fontSize: "1.1rem", lineHeight: "1.6" }}>
                <Markdown
                    components={{
                        a: LinkRenderer
                    }}
                >
                    {currentDoc}
                </Markdown>
            </div>
        </div>
    );
}

import { useTasks, useTaskQuery, useTaskFilters, useTaskSort } from "../../core/store/hooks";
import { TaskListPane } from "../../components/tasklist";
import { SplitPane } from "../../components/split-pane";
import { TaskCanvas } from "./TaskCanvas";
import type { AppTask } from "../../core/domain/models";

import { DRAG_THRESHOLD_PX, ANIMATION_DELAY_MS, GRAPH_NODE_WIDTH_PX } from "./constants";

export function GraphScreen() {
    const [tasks, setTasks] = useTasks();

    const [query, setQuery] = useTaskQuery();
    const [filters, setFilters] = useTaskFilters();
    const [sort, setSort] = useTaskSort();

    const moveFilteredToCanvas = () => {
        let xs = tasks;
        for (const f of filters) {
            if (!f.column || (!f.value && f.value !== 0)) continue;
            xs = xs.filter((t: AppTask) => {
                let match = false;
                const values = Array.isArray(f.value) ? f.value : [f.value];
                if (values.length === 0) return true;
                
                if (f.column === "status") match = values.includes(t.status || "");
                else if (f.column === "priority")
                    match = values.includes(t.priority || 0) || values.includes(String(t.priority));
                else if (f.column === "tag")
                    match = values.some(v => (t.tags || []).includes(String(v)));
                return f.operator === "is not" ? !match : match;
            });
        }
        if (query.trim()) {
            const q = query.toLowerCase();
            xs = xs.filter(
                (t: AppTask) =>
                    t.title.toLowerCase().includes(q) ||
                    (t.tags || []).some((tag) => tag.toLowerCase().includes(q)),
            );
        }

        const idsToMove = new Set(xs.map((t: AppTask) => t.id));

        setTasks((prev: AppTask[]) => {
            let layoutIndex = 0;
            return prev.map((t: AppTask) => {
                if (!idsToMove.has(t.id) || t.onCanvas)
                    return t;

                const newT = {
                    ...t,
                    onCanvas: true,
                    canvasX: (layoutIndex % DRAG_THRESHOLD_PX) * GRAPH_NODE_WIDTH_PX,
                    canvasY: Math.floor(layoutIndex / DRAG_THRESHOLD_PX) * ANIMATION_DELAY_MS,
                };
                layoutIndex++;
                return newT;
            });
        });
    };

    const footer = (
        <div
            style={{
                padding: "12px",
                borderTop: "1px solid var(--border)",
                background: "var(--bg-surface)",
            }}
        >
            <button
                onClick={moveFilteredToCanvas}
                style={{
                    width: "100%",
                    padding: "8px",
                    background: "var(--accent)",
                    color: "var(--bg)",
                    border: "none",
                    borderRadius: "4px",
                    cursor: "pointer",
                    fontWeight: "bold",
                }}
            >
                Move to canvas
            </button>
        </div>
    );

    return (
        <>
            <main className="main">
                <SplitPane
                    direction="horizontal"
                    defaultSize={360}
                    minSize={200}
                    snapThreshold={50}
                >
                    <TaskListPane
                        tasks={tasks}
                        setTasks={setTasks}
                        filters={filters}
                        setFilters={setFilters}
                        sort={sort}
                        setSort={setSort}
                        query={query}
                        setQuery={setQuery}
                        onDragStart={() => {}}
                        onAddTask={(defaults: Partial<AppTask> = {}) => {
                            const id = `t${Date.now()}`;
                            setTasks((ts: AppTask[]) => [
                                {
                                    id,
                                    title: "New Task",
                                    status: "todo",
                                    priority: 1,
                                    tags: [],
                                    subtasks: [],
                                    parent_task: undefined,
                                    dependencies: [],
                                    est: 60,
                                    added: new Date().toISOString(),
                                    ...defaults,
                                },
                                ...ts,
                            ]);
                        }}
                        onDeleteTask={(id: string) =>
                            setTasks((ts: AppTask[]) => ts.filter((t) => t.id !== id))
                        }
                        footer={footer}
                    />
                    <div
                        className="right-pane"
                        style={{
                            position: "relative",
                            width: "100%",
                            height: "100%",
                        }}
                    >
                        <TaskCanvas tasks={tasks} setTasks={setTasks} />
                    </div>
                </SplitPane>
            </main>
        </>
    );
}

import {
    ReactFlow,
    MiniMap,
    Controls,
    Background,
    useReactFlow,
    ReactFlowProvider,
} from "@xyflow/react";
import "@xyflow/react/dist/style.css";
import type { AppTask as Task } from "../../core/domain/models";
import { TaskNodeComponent } from "./TaskNode";
import { useTaskGraphElements } from "./use-task-graph-elements";
import { useTaskCanvasActions } from "./use-task-canvas-actions";

type TaskCanvasProps = {
    tasks: Task[];
    setTasks: (updater: (prev: Task[]) => Task[]) => void;
};

const nodeTypes = {
    taskNode: TaskNodeComponent,
};

function TaskCanvasInner({ tasks, setTasks }: TaskCanvasProps) {
    const { screenToFlowPosition } = useReactFlow();

    const { nodes, edges } = useTaskGraphElements(tasks);
    const {
        onNodesChange,
        isValidConnection,
        onConnect,
        onNodesDelete,
        onEdgesDelete,
        onDoubleClick,
    } = useTaskCanvasActions(setTasks, screenToFlowPosition);

    return (
        <div
            style={{
                position: "absolute",
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
            }}
            onDoubleClick={onDoubleClick}
        >
            <ReactFlow
                nodes={nodes}
                edges={edges}
                onNodesChange={onNodesChange}
                onNodesDelete={onNodesDelete}
                onEdgesDelete={onEdgesDelete}
                onConnect={onConnect}
                isValidConnection={isValidConnection}
                nodeTypes={nodeTypes}
                fitView
                colorMode="dark"
            >
                <Background />
                <Controls />
                <MiniMap />
            </ReactFlow>
        </div>
    );
}

export function TaskCanvas(props: TaskCanvasProps) {
    return (
        <ReactFlowProvider>
            <TaskCanvasInner {...props} />
        </ReactFlowProvider>
    );
}

import { Handle, Position } from "@xyflow/react";
import type { AppTask as Task } from "../../core/domain/models";
import { OPACITY_MUTED } from "./constants";




export interface TaskNodeProps {
    data: { task: Task; [key: string]: unknown };
    id: string;
}

export const TaskNodeComponent = ({ data }: TaskNodeProps) => {
    const task = data.task;

    return (
        <div
            className={`task-canvas-node ${task.status === "done" ? "is-done" : ""}`}
            style={{
                background: "var(--bg-surface)",
                border: "1px solid var(--border)",
                borderRadius: "8px",
                padding: "12px",
                minWidth: "200px",
                boxShadow: "0 4px 6px rgba(0,0,0,0.1)",
                position: "relative",
                opacity: task.status === "done" ? OPACITY_MUTED : 1,
            }}
        >
            {/* Top Target Handle: Parent connection */}
            <Handle
                type="target"
                position={Position.Top}
                id="parent"
                style={{ background: "var(--accent)" }}
            />

            {/* Left Target Handle: Dependency connection (This task requires the source task) */}
            <Handle
                type="target"
                position={Position.Left}
                id="dependency"
                style={{ background: "#d9866b" }}
            />

            <div
                style={{
                    display: "flex",
                    alignItems: "center",
                    gap: "8px",
                    marginBottom: "8px",
                }}
            >
                <span className={`pri pri-${task.priority}`}>●</span>
                <strong style={{ color: "var(--fg)" }}>{task.title}</strong>
            </div>

            <div style={{ display: "flex", gap: "8px", flexWrap: "wrap" }}>
                {task.status && (
                    <span
                        className={`status-pill status-${task.status.replace("-", "")}`}
                    >
                        {task.status}
                    </span>
                )}
            </div>

            {/* Bottom Source Handle: Subtask connection (Connects to a child task's Top) */}
            <Handle
                type="source"
                position={Position.Bottom}
                id="child"
                style={{ background: "var(--accent)" }}
            />

            {/* Right Source Handle: Dependent connection (Connects to a dependent task's Left) */}
            <Handle
                type="source"
                position={Position.Right}
                id="dependent"
                style={{ background: "#d9866b" }}
            />
        </div>
    );
};

export const OPACITY_MUTED = 0.6;

export const ANIMATION_DELAY_MS = 150;

export const DRAG_THRESHOLD_PX = 4;

export const GRAPH_NODE_WIDTH_PX = 250;

import { useCallback } from "react";
import type { Connection, Edge, Node, NodeChange } from "@xyflow/react";
import type { AppTask as Task } from "../../core/domain/models";

const applyConnection = (prev: Task[], connection: Connection | Edge): Task[] => 
    prev.map(t => {
        if (connection.target === t.id && connection.targetHandle === "parent" && connection.sourceHandle === "child") return { ...t, parent_task: connection.source };
        if (connection.target === t.id && connection.targetHandle === "dependency" && connection.sourceHandle === "dependent") {
            const deps = t.dependencies || [];
            if (!deps.includes(connection.source)) return { ...t, dependencies: [...deps, connection.source] };
        }
        return t;
    });

const applyEdgeDeletions = (prev: Task[], deletedEdges: Edge[]): Task[] => {
    let updated = [...prev];
    for (const edge of deletedEdges) {
        if (edge.targetHandle === "parent" && edge.sourceHandle === "child") updated = updated.map(t => t.id === edge.target ? { ...t, parent_task: undefined } : t);
        if (edge.targetHandle === "dependency" && edge.sourceHandle === "dependent") updated = updated.map(t => t.id === edge.target ? { ...t, dependencies: (t.dependencies || []).filter(dep => dep !== edge.source) } : t);
    }
    return updated;
};

const createDefaultCanvasTask = (id: string, position: {x: number, y: number}): Task => ({
    id, title: "New Task", status: "todo", priority: 1, tags: [], subtasks: [], 
    parent_task: undefined, dependencies: [], est: 60, added: new Date().toISOString(), 
    onCanvas: true, canvasX: position.x, canvasY: position.y
});

export function useTaskCanvasActions(
    setTasks: (updater: (prev: Task[]) => Task[]) => void,
    screenToFlowPosition: (position: { x: number; y: number }) => { x: number; y: number }
) {
    const onNodesChange = useCallback((changes: NodeChange[]) => {
        const positionUpdates = new Map<string, {x: number, y: number}>();
        for (const change of changes) {
            if (change.type === "position" && change.position) positionUpdates.set(change.id, change.position);
        }
        if (positionUpdates.size === 0) return;
        setTasks(prev => prev.map(t => {
            const pos = positionUpdates.get(t.id);
            return pos ? { ...t, canvasX: pos.x, canvasY: pos.y } : t;
        }));
    }, [setTasks]);

    const isValidConnection = useCallback((connection: Connection | Edge) => 
        (connection.sourceHandle === "child" && connection.targetHandle === "parent") ||
        (connection.sourceHandle === "dependent" && connection.targetHandle === "dependency"), []);

    const onConnect = useCallback((connection: Connection) => {
        if (isValidConnection(connection)) setTasks(prev => applyConnection(prev, connection));
    }, [setTasks, isValidConnection]);

    const onNodesDelete = useCallback((deletedNodes: Node[]) => {
        const deletedNodeIds = new Set(deletedNodes.map((n) => n.id));
        setTasks(prev => prev.map(t => deletedNodeIds.has(t.id) ? { ...t, onCanvas: false } : t));
    }, [setTasks]);

    const onEdgesDelete = useCallback((deletedEdges: Edge[]) => {
        setTasks(prev => applyEdgeDeletions(prev, deletedEdges));
    }, [setTasks]);

    const onDoubleClick = useCallback((e: React.MouseEvent) => {
        if (!(e.target instanceof HTMLElement) || e.target.closest(".react-flow__node")) return;
        const position = screenToFlowPosition({ x: e.clientX, y: e.clientY });
        setTasks(ts => [...ts, createDefaultCanvasTask(`t${Date.now()}`, position)]);
    }, [setTasks, screenToFlowPosition]);

    return {
        onNodesChange,
        isValidConnection,
        onConnect,
        onNodesDelete,
        onEdgesDelete,
        onDoubleClick,
    };
}

import { useMemo } from "react";
import type { Edge, Node } from "@xyflow/react";
import type { AppTask as Task } from "../../core/domain/models";

export function useTaskGraphElements(tasks: Task[]) {
    const canvasTasks = useMemo(() => tasks.filter((t) => t.onCanvas), [tasks]);

    const nodes: Node[] = useMemo(() => {
        return canvasTasks.map((t) => ({
            id: t.id,
            type: "taskNode",
            position: { x: t.canvasX || 0, y: t.canvasY || 0 },
            data: { task: t },
        }));
    }, [canvasTasks]);

    const edges: Edge[] = useMemo(() => {
        const newEdges: Edge[] = [];

        // Create edges from tasks data
        for (const t of canvasTasks) {
            if (
                t.parent_task &&
                canvasTasks.some((ct) => ct.id === t.parent_task)
            ) {
                newEdges.push({
                    id: `e-${t.parent_task}-child-${t.id}`,
                    source: t.parent_task,
                    sourceHandle: "child",
                    target: t.id,
                    targetHandle: "parent",
                    animated: true,
                    style: { stroke: "var(--accent)" },
                });
            }

            if (!t.dependencies) continue;

            for (const depId of t.dependencies) {
                if (canvasTasks.some((ct) => ct.id === depId)) {
                    newEdges.push({
                        id: `e-${depId}-dependent-${t.id}`,
                        source: depId,
                        sourceHandle: "dependent",
                        target: t.id,
                        targetHandle: "dependency",
                        style: { stroke: "#d9866b" },
                    });
                }
            }
        }

        return newEdges;
    }, [canvasTasks]);

    return { nodes, edges };
}

import React, { useState, useEffect, useRef } from 'react';
import type { AppTask, AppEvent } from '../../core/domain/models';
import { search } from './search';
import { parseCommands } from './commandParser';
import type { CommandOption } from './commandParser';
import { parseSigils } from '../../core/utils/sigil-parser';

import './launcher.css';

const staticCommands: CommandOption[] = [
    { id: 'docs', label: 'Help, Info, Docs', action: 'NAVIGATE', payload: { route: 'docs' }, static: true },
    { id: 'plan', label: 'Plan', action: 'NAVIGATE', payload: { route: 'plan' }, static: true },
    { id: 'do', label: 'Do', action: 'NAVIGATE', payload: { route: 'do' }, static: true },
    { id: 'minitracker', label: 'Reset Mini Tracker', action: 'RESET_MINITRACKER', static: true },
];

const navAliases = [
    { label: 'docs', id: 'docs' }, { label: 'help', id: 'docs' }, { label: 'info', id: 'docs' },
    { label: 'plan', id: 'plan' }, { label: 'do', id: 'do' },
    { label: 'minitracker', id: 'minitracker' }, { label: 'tracker', id: 'minitracker' }, { label: 'timer', id: 'minitracker' }, { label: 'clock', id: 'minitracker' }
];

const executeCommand = (cmd: CommandOption) => {
    if (window.electronAPI) {
        window.electronAPI.executeLauncherCommand(cmd);
        window.electronAPI.hideLauncher();
    }
};

const MAX_RESULTS = 10;

export function LauncherScreen() {
    const [query, setQuery] = useState('');
    const [tasks, setTasks] = useState<AppTask[]>([]);
    const [events, setEvents] = useState<AppEvent[]>([]);
    const [selectedIndex, setSelectedIndex] = useState(0);
    const inputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        const api = window.electronAPI;
        if (api?.onLauncherDataUpdate) {
            api.onLauncherDataUpdate((data) => {
                if (data && typeof data === 'object') {
                    const newTasks = Reflect.get(data, 'tasks');
                    if (Array.isArray(newTasks)) {
                        setTasks(newTasks.filter((obj): obj is AppTask => 
                            typeof obj === 'object' && obj !== null && 
                            typeof Reflect.get(obj, 'id') === 'string' && 
                            typeof Reflect.get(obj, 'title') === 'string' && 
                            typeof Reflect.get(obj, 'status') === 'string'
                        ));
                    }
                    const newEvents = Reflect.get(data, 'events');
                    if (Array.isArray(newEvents)) {
                        setEvents(newEvents.filter((obj): obj is AppEvent => 
                            typeof obj === 'object' && obj !== null && 
                            typeof Reflect.get(obj, 'id') === 'string' && 
                            typeof Reflect.get(obj, 'title') === 'string' && 
                            typeof Reflect.get(obj, 'startTime') === 'string' && 
                            typeof Reflect.get(obj, 'endTime') === 'string'
                        ));
                    }
                }
            });
        }
        if (inputRef.current) {
            inputRef.current.focus();
        }
    }, []);

    // Combine static search with parsed commands
    const parsed = parseCommands(query, tasks, events);

    // Fuzzy search over static and tasks/events shortcuts
    const searchedStatic: CommandOption[] = [];
    if (query.trim() === '') {
        // No query, show top default suggestions
    } else {
        const matchedAliases = search(query, navAliases);
        const addedIds = new Set<string>();
        matchedAliases.forEach(alias => {
            if (!addedIds.has(alias.id)) {
                const cmd = staticCommands.find(c => c.id === alias.id);
                if (cmd) {
                    searchedStatic.push(cmd);
                    addedIds.add(alias.id);
                }
            }
        });
    }

    const options = [...parsed, ...searchedStatic];

    useEffect(() => {
        setSelectedIndex(0);
        
        if (window.electronAPI?.resizeLauncher) {
            const container = document.querySelector('.launcher-container');
            if (container) {
                // Ensure DOM has updated
                setTimeout(() => {
                    if (!container) return;
                    const h = container.getBoundingClientRect().height;
                    window.electronAPI?.resizeLauncher(Math.ceil(h));
                }, 0);
            }
        }
    }, [query, options.length]);

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'ArrowDown') {
            e.preventDefault();
            setSelectedIndex((prev) => (prev + 1) % Math.max(options.length, 1));
        } else if (e.key === 'ArrowUp') {
            e.preventDefault();
            setSelectedIndex((prev) => (prev - 1 + Math.max(options.length, 1)) % Math.max(options.length, 1));
        } else if (e.key === 'Enter') {
            e.preventDefault();
            if (options[selectedIndex]) {
                executeCommand(options[selectedIndex]);
            }
        } else if (e.key === 'Escape') {
            e.preventDefault();
            window.electronAPI?.hideLauncher();
        }
    };

    return (
        <div className="launcher-container" data-launcher="true">
            <div className="launcher-input-row" style={{ position: "relative" }}>
                <div
                    className="launcher-input"
                    style={{
                        position: "absolute",
                        top: 0,
                        left: 0,
                        right: 0,
                        bottom: 0,
                        color: "transparent",
                        pointerEvents: "none",
                        whiteSpace: "pre-wrap",
                        overflow: "hidden",
                        border: "none",
                        background: "transparent",
                        margin: 0,
                        wordBreak: "break-word",
                    }}
                >
                    {parseSigils(query).tokens.map((t) => {
                        return <span key={crypto.randomUUID()} style={t.type === "sigil" ? { backgroundColor: "rgba(255, 75, 75, 0.4)", borderRadius: "3px" } : {}}>{t.text}</span>;
                    })}
                </div>
                <input
                    ref={inputRef}
                    type="text"
                    value={query}
                    onChange={(e) => setQuery(e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder="Search or command..."
                    className="launcher-input"
                    spellCheck={false}
                    style={{ background: "transparent", position: "relative" }}
                />
            </div>
            <div className="launcher-results" style={{ display: options.length > 0 ? 'block' : 'none' }}>
                {options.slice(0, MAX_RESULTS).map((opt, i) => (
                    <button
                        key={`${opt.id}-${opt.label}`}
                        className={`launcher-row ${i === selectedIndex ? 'selected' : ''}`}
                        onClick={() => executeCommand(opt)}
                    >
                        {opt.label}
                    </button>
                ))}
            </div>
        </div>
    );
}

import type { AppTask, AppEvent } from '../../core/domain/models';
import { toFloatingIso } from '../../core/utils/date-utils';

const MAX_EVENTS_TO_SHOW = 10;
const HH_MM_LENGTH = 5;

export interface CommandOption {
    id: string;
    label: string;
    action: string;
    payload?: Record<string, string>;
    static?: boolean;
}

type CommandHandler = (arg: string, tasks: AppTask[], events: AppEvent[]) => CommandOption[];

const commandHandlers: Record<string, CommandHandler> = {
    plan: (arg, tasks, events) => {
        if (!arg) return [];
        const cmds: CommandOption[] = [{
            id: `plan-task-new`,
            label: `Plan new task: ${arg}`,
            action: 'PLAN_TASK',
            payload: { taskName: arg }
        }];

        tasks.filter(t => t.title.toLowerCase().includes(arg)).forEach(t => {
            cmds.push({
                id: `plan-task-${t.id}`,
                label: `Plan existing task: ${t.title}`,
                action: 'PLAN_TASK_EXISTING',
                payload: { taskId: t.id }
            });
        });
        
        events.filter(e => e.title.toLowerCase().includes(arg)).forEach(e => {
            cmds.push({
                id: `plan-event-exist-${e.id}`,
                label: `Event already exists: ${e.title}`,
                action: 'DO_NOTHING',
            });
        });

        return cmds;
    },

    do: (arg, tasks, events) => {
        if (!arg) return [];
        const cmds: CommandOption[] = [{
            id: `do-task-new`,
            label: `Do new task: ${arg}`,
            action: 'DO_TASK',
            payload: { taskName: arg }
        }];

        tasks.filter(t => t.title.toLowerCase().includes(arg)).forEach(t => {
            cmds.push({
                id: `do-task-${t.id}`,
                label: `Do existing task: ${t.title}`,
                action: 'DO_TASK_EXISTING',
                payload: { taskId: t.id }
            });
        });

        events.filter(e => e.title.toLowerCase().includes(arg)).forEach(e => {
            cmds.push({
                id: `do-event-exist-${e.id}`,
                label: `Event already exists: ${e.title}`,
                action: 'DO_NOTHING',
            });
        });

        return cmds;
    },

    add: (arg, tasks, events) => {
        if (!arg) return [];
        const cmds: CommandOption[] = [{
            id: `add-task-new`,
            label: `Add new task: ${arg}`,
            action: 'ADD_TASK',
            payload: { taskName: arg }
        }];
        
        tasks.filter(t => t.title.toLowerCase().includes(arg)).forEach(t => {
            cmds.push({
                id: `add-task-exist-${t.id}`,
                label: `Task already exists: ${t.title}`,
                action: 'DO_NOTHING',
            });
        });
        
        events.filter(e => e.title.toLowerCase().includes(arg)).forEach(e => {
            cmds.push({
                id: `add-event-exist-${e.id}`,
                label: `Event already exists: ${e.title}`,
                action: 'DO_NOTHING',
            });
        });

        return cmds;
    },

    sked: (_arg, _tasks, events) => {
        const cmds: CommandOption[] = [];
        const nowIso = toFloatingIso(new Date());
        
        const upcoming = events
            .filter(e => e.endTime >= nowIso)
            .toSorted((a, b) => a.startTime.localeCompare(b.startTime))
            .slice(0, MAX_EVENTS_TO_SHOW);
            
        upcoming.forEach(e => {
            const timeStr = e.startTime.includes('T') ? e.startTime.split('T')[1]?.substring(0, HH_MM_LENGTH) : 'All day';
            cmds.push({
                id: `sked-event-${e.id}`,
                label: `[${timeStr}] ${e.title}`,
                action: 'DO_NOTHING'
            });
        });
        
        if (upcoming.length === 0) {
            cmds.push({
                id: 'sked-none',
                label: 'No upcoming events',
                action: 'DO_NOTHING'
            });
        }
        
        return cmds;
    }
};

export function parseCommands(
    query: string,
    tasks: AppTask[],
    events: AppEvent[] = []
): CommandOption[] {
    const q = query.trim().toLowerCase();
    if (!q) return [];

    const [cmd, ...rest] = q.split(' ');
    if (!cmd) return [];
    const arg = rest.join(' ');

    const handler = commandHandlers[cmd];
    return handler ? handler(arg, tasks, events) : [];
}

