import * as React from "react";

import type { AppFilter } from "../../../core/domain/models";

export type Filter = AppFilter;

export interface Column {
    id: string;
    label: string;
}

export interface SortOption {
    id: string;
    label: string;
}

export interface FilterSortButtonsProps {
    filters: Filter[];
    setFilters: React.Dispatch<React.SetStateAction<Filter[]>>;
    sort: string;
    setSort: (sort: string) => void;
    columns: Column[];
    getValuesForColumn: (columnId: string) => string[];
    sortOptions?: SortOption[];
    align?: "left" | "right";
}

import { useState, useCallback } from "react";

export const ANIMATION_DELAY_MS = 150;


export function useAnimatedMenu(closeDelay = ANIMATION_DELAY_MS) {
    const [isOpen, setIsOpen] = useState(false);
    const [isClosing, setIsClosing] = useState(false);

    const close = useCallback(() => {
        setIsClosing(true);
        setTimeout(() => {
            setIsOpen(false);
            setIsClosing(false);
        }, closeDelay);
    }, [closeDelay]);

    const open = useCallback(() => {
        setIsOpen(true);
    }, []);

    const toggle = useCallback(() => {
        if (isOpen) {
            close();
        } else {
            open();
        }
    }, [isOpen, close, open]);

    return { isOpen, isClosing, open, close, toggle };
}

import type { Filter, Column } from "./types";
import type { Dispatch, SetStateAction } from "react";

export function useFilterActions(filters: Filter[], setFilters: Dispatch<SetStateAction<Filter[]>>, columns: Column[], getValuesForColumn: (c: string) => string[]) {
    const addFilter = () => {
        const firstCol = columns[0]?.id || "";
        const firstVal = [getValuesForColumn(firstCol)[0] || ""];
        setFilters([
            ...filters,
            {
                id: Date.now().toString(),
                column: firstCol,
                operator: "is",
                value: firstVal,
            },
        ]);
    };

    const updateFilter = (id: string, updates: Partial<Filter>) => {
        setFilters((fs) =>
            fs.map((f) => {
                if (f.id !== id) return f;
                const nf = { ...f, ...updates };
                if (updates.column && updates.column !== f.column) {
                    nf.value = [getValuesForColumn(updates.column)[0] || ""];
                }
                return nf;
            }),
        );
    };

    const removeFilter = (id: string) => {
        setFilters((fs) => fs.filter((f) => f.id !== id));
    };

    return { addFilter, updateFilter, removeFilter };
}

