import { MINUTES_IN_HOUR } from "../../core/utils/constants";
import { MS_IN_MINUTE, toFloatingIso } from "../../core/utils/date-utils";
import React, { useState, useRef } from 'react';
import { useEvents, useCalendars } from "../../core/store/hooks";
import type { AppTask, AppEvent } from "../../core/domain/models";
import { ymd } from "../../core/store/data";
import { resolveDropTarget } from "./drag-utils";

import { applyRecurringUpdate, type RecurringMode } from "../../core/domain/rrule-utils";
import type { PlanDragState } from "./drag-helpers";
import type { InspectorState } from "../../components/inspector-pane";

export const MIN_POLL_INTERVAL_MINUTES = 5;
export const ID_LENGTH = 9;

export const canEditEvent = (ev: AppEvent | undefined, calendars: readonly {id: string, accessRole?: string}[]) => {
    if (!ev) return true;
    const cal = calendars.find(c => c.id === (ev.remoteCollectionId || "primary"));
    return !cal || (cal.accessRole !== "reader" && cal.accessRole !== "freeBusyReader");
};

export const setupPointerDrag = (
    e: React.PointerEvent | React.MouseEvent,
    onMove: (ev: PointerEvent | MouseEvent) => void,
    onDrop: (active: boolean) => void
) => {
    const start = { x: e.clientX, y: e.clientY };
    let active = false;
    const move = (ev: PointerEvent | MouseEvent) => {
        if (!active && Math.hypot(ev.clientX - start.x, ev.clientY - start.y) >= MIN_POLL_INTERVAL_MINUTES) active = true;
        if (active) onMove(ev);
    };
    const up = () => {
        window.removeEventListener("pointermove", move);
        window.removeEventListener("pointerup", up);
        onDrop(active);
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
};

function getIsoFromMinutes(dateStr: string, minutes: number) {
    const dt = new Date(`${dateStr}T00:00:00`);
    const dt2 = new Date(dt.getTime() + minutes * MS_IN_MINUTE);
    return toFloatingIso(dt2);
}

function getNextDayStr(dateStr: string) {
    const dt = new Date(`${dateStr}T00:00:00`);
    dt.setDate(dt.getDate() + 1);
    return ymd(dt);
}

export function useDragAndDrop(
    timelineDate: Date,
    setInspectorState: React.Dispatch<React.SetStateAction<InspectorState | undefined>>,
    createEvent: (task: AppTask, overrides: Partial<AppEvent>) => void,
    interceptRecurringAction: (event: AppEvent, actionType: "edit" | "delete", updates: Partial<AppEvent> | undefined, execute: (mode: RecurringMode) => void) => void
) {
    const [, setEvents] = useEvents();
    const [calendars] = useCalendars();
    
    const [dragState, setDragState] = useState<PlanDragState>();
    const dragRef = useRef<PlanDragState | undefined>(undefined);
    dragRef.current = dragState;

    const onTaskDragStart = (e: React.PointerEvent | React.MouseEvent, task: AppTask) => {
        e.preventDefault();
        setupPointerDrag(e, (ev) => {
            const target = resolveDropTarget(document.elementFromPoint(ev.clientX, ev.clientY) || undefined, ev.clientY, task.est || MINUTES_IN_HOUR);
            setDragState({ task, pointerX: ev.clientX, pointerY: ev.clientY, ...(target !== undefined ? { target } : {}) });
        }, (active) => {
            if (!active) return setInspectorState({ type: "task", id: task.id });
            const ds = dragRef.current;
            if (ds?.target?.kind === "grid-day" && ds.target.date) {
                const dStr = ds.target.date;
                createEvent(task, { startTime: dStr, endTime: getNextDayStr(dStr) });
            } else if (ds?.target?.kind === "day-time" && ds.target.minute !== undefined) {
                const dStr = ymd(timelineDate);
                createEvent(task, { startTime: getIsoFromMinutes(dStr, ds.target.minute), endTime: getIsoFromMinutes(dStr, ds.target.minute + (task.est || MINUTES_IN_HOUR)) });
            }
            setDragState(undefined);
        });
    };

    const onEventDragStart = (e: React.PointerEvent | React.MouseEvent, eventToMove: AppEvent, task?: AppTask) => {
        if (!canEditEvent(eventToMove, calendars)) {
            e.preventDefault();
            e.stopPropagation();
            return setInspectorState({ type: "event", id: eventToMove.id });
        }
        e.preventDefault();
        e.stopPropagation();

        const getDurMins = () => {
            return (new Date(eventToMove.endTime).getTime() - new Date(eventToMove.startTime).getTime()) / MS_IN_MINUTE;
        };

        setupPointerDrag(e, (ev) => {
            const target = resolveDropTarget(document.elementFromPoint(ev.clientX, ev.clientY) || undefined, ev.clientY, task?.est || getDurMins());
            setDragState({ event: eventToMove, ...(task !== undefined ? { task } : {}), pointerX: ev.clientX, pointerY: ev.clientY, ...(target !== undefined ? { target } : {}) });
        }, (active) => {
            if (!active) return setInspectorState({ type: "event", id: eventToMove.id });
            const ds = dragRef.current;
            if (ds?.target?.kind === "grid-day" && ds.target.date) {
                const dropDate = ds.target.date;
                const updates = { startTime: dropDate, endTime: getNextDayStr(dropDate) };
                interceptRecurringAction(eventToMove, "edit", updates, (mode) => {
                    setEvents(prev => applyRecurringUpdate(prev, eventToMove, mode, updates));
                });
            } else if (ds?.target?.kind === "day-time" && ds.target.minute !== undefined) {
                const duration = getDurMins();
                const dropMinute = ds.target.minute;
                const dStr = ymd(timelineDate);
                const updates = { startTime: getIsoFromMinutes(dStr, dropMinute), endTime: getIsoFromMinutes(dStr, dropMinute + duration) };
                interceptRecurringAction(eventToMove, "edit", updates, (mode) => {
                    setEvents(prev => applyRecurringUpdate(prev, eventToMove, mode, updates));
                });
            }
            setDragState(undefined);
        });
    };

    return { onTaskDragStart, onEventDragStart, dragState, setDragState };
}

import { MINUTES_IN_HOUR } from "../../core/utils/constants";
import React from 'react';
import { useTasks, useEvents, useSettings, useCalendars } from "../../core/store/hooks";
import type { AppTask, AppEvent } from "../../core/domain/models";
import { ymd } from "../../core/store/data";
import type { InspectorState } from "../../components/inspector-pane";
import { addDays, MS_IN_MINUTE, toFloatingIso } from "../../core/utils/date-utils";
import { applyRecurringUpdate, type RecurringMode } from "../../core/domain/rrule-utils";

export const MAX_DISPLAY_ITEMS = 6;
export const ID_LENGTH = 9;
const ID_RADIX = 36;
const ID_SUBSTR_START = 2;
const ID_SUBSTR_END = 8;

const generateEventId = () => `e${Date.now()}-${Math.random().toString(ID_RADIX).slice(ID_SUBSTR_START, ID_SUBSTR_END)}`;

const createDefaultTask = (defaults: Partial<AppTask>, defaultDuration: number): AppTask => ({
    id: `t${Date.now()}`, title: "", status: "todo", priority: 1, tags: [], subtasks: [],
    est: defaultDuration || 0, added: new Date().toISOString(), ...defaults
});

const createDefaultEvent = (date: Date, startMins: number, endMins: number, isAllDay: boolean): AppEvent => {
    const dStr = ymd(date);
    const dt = new Date(`${dStr}T00:00:00`);
    const toIso = (mins: number) => {
        const t = new Date(dt.getTime() + mins * MS_IN_MINUTE);
        return toFloatingIso(t);
    };
    if (isAllDay) {
        return {
            id: generateEventId(), title: "", type: "info",
            startTime: dStr,
            endTime: ymd(addDays(dt))
        };
    }
    return {
        id: generateEventId(), title: "", type: "busy",
        startTime: toIso(startMins), endTime: toIso(endMins)
    };
};

export const canEditEvent = (ev: AppEvent | undefined, calendars: readonly {id: string, accessRole?: string}[]) => {
    if (!ev) return true;
    const cal = calendars.find(c => c.id === (ev.remoteCollectionId || "primary"));
    return !cal || cal.accessRole === "owner" || cal.accessRole === "writer";
};

export function usePlanActions(
    timelineDate: Date, 
    setInspectorState: React.Dispatch<React.SetStateAction<InspectorState | undefined>>,
    hydratedEvents: AppEvent[],
    interceptRecurringAction: (event: AppEvent, actionType: "edit" | "delete", updates: Partial<AppEvent> | undefined, execute: (mode: RecurringMode) => void) => void
) {
    const [, setTasks] = useTasks();
    const [, setEvents] = useEvents();
    const [settings] = useSettings();
    const [calendars] = useCalendars();

    const createEvent = (task: AppTask, overrides: Partial<AppEvent>) => {
        const defaultCal = calendars.find(c => c.primary)?.id || "primary";
        const dStr = ymd(timelineDate);
        setEvents(prev => [...prev, {
            id: generateEventId(), taskId: task.id, type: "busy", title: task.title,
            startTime: `${dStr}T00:00:00`, endTime: `${dStr}T01:00:00`,
            remoteCollectionId: defaultCal, ...overrides
        }]);
    };

    const onAddTask = (defaults: Partial<AppTask> = {}) => {
        const newTask = createDefaultTask(defaults, settings.defaultTaskDuration || 0);
        setInspectorState({ type: "new_task", draft: newTask });
    };

    const onAddEvent = (dateArg: Date | string, startArg?: number, endArg?: number) => {
        const start = typeof startArg === "number" ? startArg : ID_LENGTH * MINUTES_IN_HOUR;
        const newEvent = createDefaultEvent(dateArg instanceof Date ? dateArg : timelineDate, start, typeof endArg === "number" ? endArg : start + MINUTES_IN_HOUR, typeof startArg !== "number");
        const draftEvent = {
            ...newEvent,
            remoteCollectionId: calendars.find(c => c.primary)?.id || "primary"
        };
        setInspectorState({ type: "new_event", draft: draftEvent });
    };

    const onResizeEvent = (id: string, startTime: string, endTime: string) => {
        const ev = hydratedEvents.find((e: AppEvent) => e.id === id);
        if (!ev || !canEditEvent(ev, calendars)) return;
        
        interceptRecurringAction(ev, "edit", { startTime, endTime }, (mode) => {
             setEvents(es => applyRecurringUpdate(es, ev, mode, { startTime, endTime }));
        });
    };

    const onMoveEvent = onResizeEvent;

    const onDeleteTask = (id: string) => {
        setTasks(ts => ts.filter((t: AppTask) => t.id !== id));
        setEvents(es => es.filter((e: AppEvent) => e.taskId !== id));
    };

    return { createEvent, onAddTask, onAddEvent, onResizeEvent, onMoveEvent, onDeleteTask };
}

